import React, { useState, useRef } from 'react';
import { X, UploadCloud, CheckCircle, AlertCircle, Loader } from 'lucide-react';
import { matchAccessoryByName, uploadAccessoryImage, updateAccessory } from '../../utils/api';

interface BulkImageUploadModalProps {
  onClose: () => void;
  onSuccess: () => void;
}

interface UploadItem {
  file: File;
  name: string; // The parsed product name from the file name
  status: 'pending' | 'uploading' | 'success' | 'not_found' | 'error';
  errorMessage?: string;
  matchedId?: string;
}

const BulkImageUploadModal: React.FC<BulkImageUploadModalProps> = ({ onClose, onSuccess }) => {
  const [items, setItems] = useState<UploadItem[]>([]);
  const [isUploading, setIsUploading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFiles = (files: FileList | File[]) => {
    const newItems: UploadItem[] = Array.from(files)
      .filter(f => f.type.startsWith('image/'))
      .map(file => {
        // Remove extension to get the product name
        const name = file.name.substring(0, file.name.lastIndexOf('.')) || file.name;
        return {
          file,
          name,
          status: 'pending'
        };
      });

    setItems(prev => [...prev, ...newItems]);
  };

  const onDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const onDrop = (e: React.DragEvent) => {
    e.preventDefault();
    if (e.dataTransfer.files) {
      handleFiles(e.dataTransfer.files);
    }
  };

  const onFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      handleFiles(e.target.files);
    }
  };

  const startUpload = async () => {
    if (items.length === 0 || isUploading) return;
    
    setIsUploading(true);

    for (let i = 0; i < items.length; i++) {
      const item = items[i];
      if (item.status === 'success') continue; // Skip already uploaded

      // Set to uploading
      setItems(prev => prev.map((p, idx) => idx === i ? { ...p, status: 'uploading' } : p));

      try {
        // 1. Match the product by exact name (ignoring case)
        const matchData = await matchAccessoryByName(item.name);
        
        if (!matchData) {
          setItems(prev => prev.map((p, idx) => idx === i ? { 
            ...p, 
            status: 'not_found', 
            errorMessage: 'No se encontr├│ un producto con este nombre exacto.' 
          } : p));
          continue;
        }

        // 2. Upload the file to Supabase Storage (reuses natural upload flow)
        const imageUrl = await uploadAccessoryImage(item.file);

        // 3. Update the product record
        await updateAccessory(matchData.id, { image_url: imageUrl });

        setItems(prev => prev.map((p, idx) => idx === i ? { 
          ...p, 
          status: 'success',
          matchedId: matchData.id
        } : p));

      } catch (error: any) {
        console.error(`Error uploading ${item.name}:`, error);
        setItems(prev => prev.map((p, idx) => idx === i ? { 
          ...p, 
          status: 'error',
          errorMessage: error.message || 'Error en la subida.'
        } : p));
      }
    }

    setIsUploading(false);
    onSuccess(); // Refresh the list behind the scenes
  };

  const removePending = (index: number) => {
    if (isUploading) return;
    setItems(prev => prev.filter((_, idx) => idx !== index));
  };

  return (
    <div className="fixed inset-0 bg-black/80 flex items-center justify-center p-4 z-50">
      <div className="bg-gray-900 border border-gray-800 rounded-xl p-6 w-full max-w-3xl flex flex-col max-h-[90vh]">
        <div className="flex justify-between items-center mb-6">
          <div>
            <h2 className="text-xl font-bold text-white">Carga Masiva de Im├ígenes</h2>
            <p className="text-sm text-gray-400 mt-1">
              Aseg├║rate de que el nombre del archivo (sin extensi├│n) sea <strong>exactamente igual</strong> al nombre del producto.
            </p>
          </div>
          <button 
            onClick={onClose}
            disabled={isUploading}
            className="text-gray-400 hover:text-white disabled:opacity-50"
          >
            <X size={24} />
          </button>
        </div>

        {/* Dropzone */}
        {!isUploading && (
          <div 
            onDragOver={onDragOver}
            onDrop={onDrop}
            className="border-2 border-dashed border-gray-700 rounded-lg p-10 text-center flex flex-col items-center justify-center mb-6 hover:border-geeko-green/50 transition-colors cursor-pointer bg-gray-800/30"
            onClick={() => fileInputRef.current?.click()}
          >
            <input 
              type="file" 
              multiple 
              accept="image/*" 
              className="hidden" 
              ref={fileInputRef}
              onChange={onFileSelect}
            />
            <UploadCloud size={48} className="text-gray-500 mb-4" />
            <p className="text-gray-300 font-medium">Haz clic aqu├¡ o arrastra im├ígenes</p>
            <p className="text-gray-500 text-sm mt-2">JPG, PNG o WEBP</p>
          </div>
        )}

        {/* File List */}
        <div className="flex-1 overflow-y-auto pr-2 space-y-2 min-h-[150px]">
          {items.length === 0 ? (
            <div className="text-center text-gray-500 py-10">No hay im├ígenes seleccionadas</div>
          ) : (
            items.map((item, idx) => (
              <div key={idx} className="bg-gray-800 rounded p-3 flex items-center justify-between">
                <div className="flex flex-col truncate">
                  <span className="text-white text-sm font-medium truncate" title={item.file.name}>{item.file.name}</span>
                  <span className="text-xs text-gray-400 mt-0.5">
                    Buscando match con: <strong className="text-gray-300">"{item.name}"</strong>
                  </span>
                </div>
                
                <div className="flex items-center ml-4 shrink-0">
                  {item.status === 'pending' && (
                    <button 
                      onClick={() => removePending(idx)}
                      disabled={isUploading}
                      className="text-gray-500 hover:text-red-400"
                    >
                      <X size={18} />
                    </button>
                  )}
                  {item.status === 'uploading' && <Loader size={18} className="text-geeko-cyan animate-spin" />}
                  {item.status === 'success' && <CheckCircle size={18} className="text-geeko-green" />}
                  {(item.status === 'not_found' || item.status === 'error') && (
                    <div className="flex items-center text-red-400" title={item.errorMessage}>
                      <span className="text-xs mr-2 max-w-[150px] truncate">{item.errorMessage}</span>
                      <AlertCircle size={18} />
                    </div>
                  )}
                </div>
              </div>
            ))
          )}
        </div>

        {/* Footer Actions */}
        <div className="flex justify-between items-center mt-6 pt-4 border-t border-gray-800">
          <div className="text-sm text-gray-400">
            Total: {items.length} im├ígenes
          </div>
          <div className="flex gap-3">
            <button
              type="button"
              onClick={onClose}
              disabled={isUploading}
              className="px-4 py-2 bg-gray-800 text-white rounded font-medium hover:bg-gray-700 disabled:opacity-50"
            >
              Cerrar
            </button>
            <button
              onClick={startUpload}
              disabled={items.length === 0 || isUploading}
              className="px-6 py-2 bg-geeko-green text-black rounded font-bold hover:bg-[#8EFFA1] disabled:opacity-50 disabled:bg-geeko-green/50 flex items-center gap-2"
            >
              {isUploading && <Loader size={16} className="animate-spin" />}
              {isUploading ? 'Procesando...' : 'Iniciar Subida Masiva'}
            </button>
          </div>
        </div>

      </div>
    </div>
  );
};

export default BulkImageUploadModal;

import React, { useState, useEffect } from 'react';
import { X, Save, AlertTriangle, Zap, RefreshCw } from 'lucide-react';
import { adminApplyDiscountByRarity, adminClearDiscountByRarity, fetchDistinctRarities } from '../../utils/api';

interface BulkRarityOfferModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSuccess: () => void;
  gameCode?: string;
}

export const BulkRarityOfferModal: React.FC<BulkRarityOfferModalProps> = ({ isOpen, onClose, onSuccess, gameCode }) => {
  const [selectedGameCode, setSelectedGameCode] = useState<string>('MTG');
  const [rarity, setRarity] = useState<string>('rare');
  const [rarityOptions, setRarityOptions] = useState<string[]>([]);
  const [discountPercentage, setDiscountPercentage] = useState<number>(0);
  const [endDate, setEndDate] = useState<string>('');
  const [overwriteExisting, setOverwriteExisting] = useState<boolean>(false);
  const [includeFoil, setIncludeFoil] = useState<boolean>(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [loadingRarities, setLoadingRarities] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Sync selectedGameCode with prop when modal opens
  useEffect(() => {
    if (isOpen) {
      const initialGame = gameCode || 'MTG';
      setSelectedGameCode(initialGame);
    }
  }, [isOpen, gameCode]);

  // Load distinct rarities for the selected game
  useEffect(() => {
    if (!isOpen) return;

    const loadRarities = async () => {
      setLoadingRarities(true);
      setError(null);
      try {
        const rarities = await fetchDistinctRarities(selectedGameCode);
        setRarityOptions(rarities);
        
        // Pick a default rarity from the fetched list if available
        if (rarities.length > 0) {
          // Try to select 'rare' or 'Rare' if it exists, otherwise the first one
          const defaultRare = rarities.find(r => r.toLowerCase() === 'rare') || rarities[0];
          setRarity(defaultRare);
        } else {
          setRarity('');
        }
      } catch (err: any) {
        console.error('Failed to load rarities:', err);
        setError('No se pudieron cargar las rarezas para este juego.');
      } finally {
        setLoadingRarities(false);
      }
    };

    loadRarities();
  }, [isOpen, selectedGameCode]);

  if (!isOpen) return null;

  const handleApply = async () => {
    if (discountPercentage <= 0 || discountPercentage > 100) {
      setError("El porcentaje de descuento debe ser mayor a 0 y menor o igual a 100.");
      return;
    }
    if (!rarity) {
      setError("Debe seleccionar una rareza v├ílida.");
      return;
    }

    try {
      setIsSubmitting(true);
      setError(null);
      
      // Construct UTC-4 date if selected, otherwise null for permanent discount
      const fullEndDate = endDate ? `${endDate}T23:59:59.999-04:00` : null;
      
      const res = await adminApplyDiscountByRarity(
        rarity, 
        discountPercentage, 
        fullEndDate, 
        overwriteExisting, 
        includeFoil, 
        selectedGameCode
      );

      if (!res.success) throw new Error(res.message);
      
      alert(`┬í├ëxito! Se actualizaron ${res.updated_count} cartas de rareza ${rarity}.`);
      onSuccess();
      onClose();
    } catch (err: any) {
      console.error(err);
      setError(err.message || 'Error aplicando el descuento masivo');
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleClear = async () => {
    if (!rarity) {
      setError("Debe seleccionar una rareza v├ílida para remover descuentos.");
      return;
    }

    if (!window.confirm(`┬┐Est├ís seguro de que deseas ELIMINAR TODOS los descuentos de las cartas de rareza ${rarity} para el juego ${selectedGameCode}?`)) {
      return;
    }

    try {
      setIsSubmitting(true);
      setError(null);
      const res = await adminClearDiscountByRarity(rarity, selectedGameCode);
      if (!res.success) throw new Error(res.message);
      
      alert(`┬í├ëxito! Se eliminaron los descuentos de ${res.updated_count} cartas de rareza ${rarity}.`);
      onSuccess();
      onClose();
    } catch (err: any) {
      console.error(err);
      setError(err.message || 'Error eliminando el descuento masivo');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black/80 flex items-center justify-center p-4 z-50">
      <div className="bg-geeko-dark rounded-xl max-w-lg w-full border border-purple-500/30 overflow-hidden shadow-2xl flex flex-col max-h-[90vh]">
        {/* Header */}
        <div className="flex justify-between items-center p-4 border-b border-gray-800 bg-geeko-darker relative overflow-hidden">
          <div className="absolute inset-0 bg-gradient-to-r from-purple-500/10 to-blue-500/10 opacity-50"></div>
          <h2 className="text-xl font-black text-white flex items-center relative z-10">
            <Zap className="w-5 h-5 mr-2 text-yellow-400" />
            Ofertas por Rareza (Masivo)
          </h2>
          <button onClick={onClose} className="text-gray-400 hover:text-white relative z-10">
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Content */}
        <div className="p-6 overflow-y-auto">
          {error && (
            <div className="mb-4 bg-red-500/10 border border-red-500 text-red-500 p-3 rounded-md flex items-start text-sm">
              <AlertTriangle className="w-5 h-5 mr-2 shrink-0" />
              <span>{error}</span>
            </div>
          )}

          <div className="bg-gray-900/50 p-4 rounded-lg border border-gray-800 mb-6">
            <p className="text-gray-300 text-sm">
              Aplica un descuento simult├íneo a <strong>todas las cartas</strong> que coincidan con la rareza elegida.
            </p>
          </div>

          <div className="space-y-5">
            {/* Game Selector */}
            <div>
              <label className="block text-sm font-bold text-gray-300 mb-1">
                Selecciona el Juego
              </label>
              <select
                className="w-full bg-gray-900 border border-gray-700 rounded-md p-2 text-white focus:outline-none focus:border-purple-500"
                value={selectedGameCode}
                onChange={(e) => setSelectedGameCode(e.target.value)}
              >
                <option value="MTG">Magic: The Gathering (MTG)</option>
                <option value="POKEMON">Pok├⌐mon (PKM)</option>
                <option value="OPC">One Piece (OPC)</option>
              </select>
            </div>

            {/* Rarity Selector */}
            <div>
              <label className="block text-sm font-bold text-gray-300 mb-1 flex items-center justify-between">
                <span>Selecciona la Rareza</span>
                {loadingRarities && <RefreshCw className="w-3.5 h-3.5 animate-spin text-purple-400" />}
              </label>
              <select
                className="w-full bg-gray-900 border border-gray-700 rounded-md p-2 text-white focus:outline-none focus:border-purple-500 disabled:opacity-50"
                value={rarity}
                onChange={(e) => setRarity(e.target.value)}
                disabled={loadingRarities || rarityOptions.length === 0}
              >
                {rarityOptions.length > 0 ? (
                  rarityOptions.map((opt) => (
                    <option key={opt} value={opt}>
                      {opt.charAt(0).toUpperCase() + opt.slice(1)}
