                                onChange={(e) => setSearchTerm(e.target.value)}
                                className="bg-black/40 border border-white/10 rounded-2xl py-3 pl-11 pr-4 text-sm text-white focus:outline-none focus:border-geeko-gold focus:ring-1 focus:ring-geeko-gold/50 transition-all w-88 placeholder:text-slate-600"
                            />
                        </div>
                        <button 
                            onClick={fetchData}
                            className="p-3 bg-black/40 border border-white/10 hover:border-white/30 text-slate-400 hover:text-white rounded-2xl transition-all"
                        >
                            <RefreshCw size={18} className={loading ? 'animate-spin' : ''} />
                        </button>
                    </div>

                    <div className="overflow-x-auto rounded-2xl border border-white/5 bg-black/20">
                        <table className="w-full text-left text-sm text-slate-300">
                            <thead className="text-[10px] uppercase bg-black/40 text-slate-500 font-black tracking-[0.2em]">
                                <tr>
                                    <th className="px-6 py-5 rounded-tl-2xl">Usuario</th>
                                    <th className="px-6 py-5">Nombre Real</th>
                                    <th className="px-6 py-5 text-right">Cr├⌐ditos Geek</th>
                                    <th className="px-6 py-5 text-right rounded-tr-2xl">Acci├│n</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-white/5">
                                {loading ? (
                                    <tr><td colSpan={4} className="px-6 py-12 text-center text-slate-500 font-bold tracking-widest text-[10px]">CARGANDO USUARIOS...</td></tr>
                                ) : users.length === 0 ? (
                                    <tr><td colSpan={4} className="px-6 py-12 text-center text-slate-500 font-bold tracking-widest text-[10px]">NO SE ENCONTRARON USUARIOS.</td></tr>
                                ) : (
                                    users.map((u) => (
                                        <tr key={u.id} className="hover:bg-white/5 transition-colors group">
                                            <td className="px-6 py-4 font-bold text-white">
                                                <div>{u.username || <span className="text-slate-600 italic">Sin username</span>}</div>
                                                {u.email && <div className="text-xs text-slate-500 font-normal mt-0.5">{u.email}</div>}
                                            </td>
                                            <td className="px-6 py-4 text-slate-400">
                                                <div>{u.first_name || u.last_name ? `${u.first_name || ''} ${u.last_name || ''}` : <span className="text-slate-600 italic">-</span>}</div>
                                                {u.cedula && <div className="text-xs text-slate-500 mt-0.5">C.I. {u.cedula}</div>}
                                            </td>
                                            <td className="px-6 py-4 text-right">
                                                <span className={`font-black px-3 py-1.5 rounded-lg text-xs ${u.geek_credits > 0 ? 'bg-geeko-gold/10 text-geeko-gold border border-geeko-gold/20' : 'text-slate-500 bg-white/5 border border-white/5'}`}>
                                                    {u.geek_credits || 0} CG
                                                </span>
                                            </td>
                                            <td className="px-6 py-4 text-right">
                                                <button 
                                                    onClick={() => handleManage(u)}
                                                    className="px-4 py-2 bg-white/5 text-slate-300 hover:bg-geeko-gold hover:text-black rounded-xl text-[10px] font-black uppercase tracking-widest transition-all opacity-50 group-hover:opacity-100 border border-white/5"
                                                >
                                                    Ajustar
                                                </button>
                                            </td>
                                        </tr>
                                    ))
                                )}
                            </tbody>
                        </table>
                    </div>
                </>
            ) : (
                <div className="overflow-x-auto rounded-2xl border border-white/5 bg-black/20">
                    <div className="flex items-center justify-between p-6 border-b border-white/5 bg-black/40">
                        <div>
                            <h4 className="text-white font-bold text-sm">Registro de Auditor├¡a Global</h4>
                            <p className="text-slate-500 text-xs mt-1">├Ültimos movimientos de cr├⌐ditos en el sistema.</p>
                        </div>
                        <button 
                            onClick={fetchData}
                            className="p-2.5 bg-white/5 border border-white/10 hover:border-white/30 text-slate-400 hover:text-white rounded-xl transition-all"
                        >
                            <RefreshCw size={14} className={loading ? 'animate-spin' : ''} />
                        </button>
                    </div>
                    <table className="w-full text-left text-sm text-slate-300">
                        <thead className="text-[10px] uppercase bg-black/20 text-slate-500 font-black tracking-[0.2em]">
                            <tr>
                                <th className="px-6 py-4">Fecha</th>
                                <th className="px-6 py-4">Usuario</th>
                                <th className="px-6 py-4">Administrador</th>
                                <th className="px-6 py-4 text-right">Monto</th>
                                <th className="px-6 py-4">Motivo</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-white/5">
                            {loading ? (
                                <tr><td colSpan={5} className="px-6 py-12 text-center text-slate-500 font-bold tracking-widest text-[10px]">CARGANDO AUDITOR├ìA...</td></tr>
                            ) : auditLogs.length === 0 ? (
                                <tr><td colSpan={5} className="px-6 py-12 text-center text-slate-500 font-bold tracking-widest text-[10px]">NO HAY REGISTROS DE AUDITOR├ìA.</td></tr>
                            ) : (
                                auditLogs.map((log) => (
                                    <tr key={log.id} className="hover:bg-white/5 transition-colors">
                                        <td className="px-6 py-4 whitespace-nowrap text-xs text-slate-500">
                                            {new Date(log.created_at).toLocaleString()}
                                        </td>
                                        <td className="px-6 py-4">
                                            <span className="text-white font-bold">{log.user?.username || 'Desconocido'}</span>
                                        </td>
                                        <td className="px-6 py-4">
                                            <span className="text-slate-400">{log.admin?.username || 'Sistema'}</span>
                                        </td>
                                        <td className="px-6 py-4 text-right">
                                            <span className={`font-black text-xs px-2 py-1 rounded-md border ${log.amount > 0 ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20' : 'bg-rose-500/10 text-rose-400 border-rose-500/20'}`}>
                                                {log.amount > 0 ? '+' : ''}{log.amount} CG
                                            </span>
                                        </td>
                                        <td className="px-6 py-4 text-slate-400 italic text-xs max-w-xs">
                                            {log.reason}
                                        </td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                </div>
            )}

            <ManageCreditsModal 
                isOpen={isModalOpen}
                onClose={() => setIsModalOpen(false)}
                userProfile={selectedUser}
                onSuccess={fetchData}
            />
        </div>
    );
};

import React, { useState } from 'react';
import { supabase } from '../../context/AuthContext';
import { LogIn, UserPlus, Mail, Lock, ArrowLeft, Eye, EyeOff } from 'lucide-react';

export const AuthModal = ({ isOpen, onClose, initialMode = 'login' }: {
    isOpen: boolean;
    onClose: () => void;
    initialMode?: 'login' | 'register' | 'forgot-password'
}) => {
    const [mode, setMode] = useState<'login' | 'register' | 'forgot-password' | 'success'>(initialMode);
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');
    const [showPassword, setShowPassword] = useState(false);
    const [showConfirmPassword, setShowConfirmPassword] = useState(false);
    const [docType, setDocType] = useState('V');
    const [docNumber, setDocNumber] = useState('');
    const [fullName, setFullName] = useState('');
    const [phone, setPhone] = useState('');
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [successMessage, setSuccessMessage] = useState<string | null>(null);

    if (!isOpen) return null;

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);
        setError(null);
        setSuccessMessage(null);

        try {
            if (mode === 'login') {
                const { error } = await supabase.auth.signInWithPassword({ email, password });
                if (error) throw error;
                onClose();
            } else if (mode === 'register') {
                if (password !== confirmPassword) {
                    throw new Error("Las contrase├▒as no coinciden");
                }
                const spaceIndex = fullName.indexOf(' ');
                const firstName = spaceIndex !== -1 ? fullName.substring(0, spaceIndex) : fullName;
                const lastName = spaceIndex !== -1 ? fullName.substring(spaceIndex + 1) : '';

                const { error } = await supabase.auth.signUp({
                    email,
                    password,
                    options: {
                        emailRedirectTo: window.location.origin,
                        data: {
                            role: 'user',
                            first_name: firstName,
                            last_name: lastName,
                            cedula: `${docType}-${docNumber}`,
                            phone: phone
                        }
                    }
                });
                if (error) throw error;
                setMode('success');
            } else if (mode === 'forgot-password') {
                const { error } = await supabase.auth.resetPasswordForEmail(email, {
                    redirectTo: `${window.location.origin}/update-password`,
                });
                if (error) throw error;
                setSuccessMessage('Si el correo existe, recibir├ís un enlace de recuperaci├│n.');
            }
        } catch (err: any) {
            setError(err.message);
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
            <div className="bg-slate-900 border border-slate-800 w-full max-w-md max-h-[95vh] rounded-2xl overflow-hidden shadow-2xl animate-in fade-in zoom-in duration-300 flex flex-col transition-all">
                <div className="p-8 overflow-y-auto">
                    <div className="flex flex-col items-center mb-8">
                        <div className="w-16 h-16 bg-blue-600/20 rounded-2xl flex items-center justify-center mb-4 border border-blue-500/30">
                            {mode === 'login' ? <LogIn className="text-blue-400 w-8 h-8" /> :
                                mode === 'register' ? <UserPlus className="text-blue-400 w-8 h-8" /> :
                                    mode === 'success' ? <Mail className="text-green-400 w-8 h-8" /> :
                                        <Lock className="text-blue-400 w-8 h-8" />}
                        </div>
                        <h2 className="text-3xl font-bold text-white text-center">
                            {mode === 'login' ? 'Bienvenido' :
                                mode === 'register' ? 'Crear Cuenta' :
                                    mode === 'success' ? '┬íRevisa tu Correo!' :
                                        'Recuperar Contrase├▒a'}
                        </h2>
                        <p className="text-slate-400 mt-2 text-center px-4">
                            {mode === 'login' ? 'Accede a tu colecci├│n TCG' :
                                mode === 'register' ? '├Ünete a la mejor comunidad TCG' :
                                    mode === 'success' ? 'Hemos enviado una misiva m├ígica a tu correo.' :
                                        'Te enviaremos las instrucciones a tu correo'}
                        </p>
                    </div>

                    {mode === 'success' ? (
                        <div className="text-center space-y-6 pb-4">
                            <div className="bg-green-500/10 border border-green-500/20 rounded-2xl p-6 shadow-inner">
                                <p className="text-green-400 text-sm leading-relaxed">
                                    Por favor, revisa tu bandeja de entrada (y tu carpeta de spam, por si los duendes la escondieron) para confirmar tu cuenta y completar tu registro en <strong>Geekorium</strong>.
                                </p>
                            </div>
                            <button
                                onClick={onClose}
                                className="w-full bg-slate-800 hover:bg-slate-700 text-white font-semibold py-3 rounded-xl transition-all border border-slate-700 hover:border-slate-600"
                            >
                                Entendido
                            </button>
                        </div>
                    ) : (
                        <form onSubmit={handleSubmit} className="space-y-4">
                        <div className="space-y-2">
                            <label className="text-sm font-medium text-slate-300 ml-1">Email</label>
                            <div className="relative">
                                <Mail className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500 w-5 h-5" />
                                <input
                                    type="email"
                                    value={email}
                                    onChange={(e) => setEmail(e.target.value)}
                                    className="w-full bg-slate-800/50 border border-slate-700 rounded-xl py-3 pl-11 pr-4 text-white placeholder:text-slate-600 focus:outline-none focus:ring-2 focus:ring-blue-500/50 focus:border-blue-500/50 transition-all"
                                    placeholder="tu@email.com"
                                    required
                                />
                            </div>
                        </div>

                        {mode !== 'forgot-password' && (
                            <div className="space-y-2">
                                <label className="text-sm font-medium text-slate-300 ml-1">Contrase├▒a</label>
                                <div className="relative">
                                    <Lock className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500 w-5 h-5" />
                                    <input
                                        type={showPassword ? 'text' : 'password'}
                                        value={password}
                                        onChange={(e) => setPassword(e.target.value)}
                                        className="w-full bg-slate-800/50 border border-slate-700 rounded-xl py-3 pl-11 pr-11 text-white placeholder:text-slate-600 focus:outline-none focus:ring-2 focus:ring-blue-500/50 focus:border-blue-500/50 transition-all"
                                        placeholder="ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó"
                                        required
                                    />
                                    <button
                                        type="button"
                                        onClick={() => setShowPassword(!showPassword)}
                                        className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-300 focus:outline-none"
                                    >
                                        {showPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                                    </button>
                                </div>
                            </div>
                        )}

                        {mode === 'register' && (
                            <div className="space-y-2 animate-in slide-in-from-top-2 fade-in duration-300">
                                <label className="text-sm font-medium text-slate-300 ml-1">Confirmar contrase├▒a</label>
                                <div className="relative">
                                    <Lock className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500 w-5 h-5" />
                                    <input
                                        type={showConfirmPassword ? 'text' : 'password'}
                                        value={confirmPassword}
                                        onChange={(e) => setConfirmPassword(e.target.value)}
                                        className="w-full bg-slate-800/50 border border-slate-700 rounded-xl py-3 pl-11 pr-11 text-white placeholder:text-slate-600 focus:outline-none focus:ring-2 focus:ring-blue-500/50 focus:border-blue-500/50 transition-all"
                                        placeholder="Repite tu contrase├▒a"
                                        required
                                    />
                                    <button
                                        type="button"
                                        onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                                        className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-300 focus:outline-none"
                                    >
                                        {showConfirmPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                                    </button>
                                </div>
                            </div>
                        )}

                        {mode === 'register' && (
                            <div className="flex gap-4 animate-in slide-in-from-top-2 fade-in duration-300">
                                <div className="w-1/3 space-y-2">
                                    <label className="text-sm font-medium text-slate-300 ml-1">Tipo</label>
                                    <select
                                        value={docType}
                                        onChange={(e) => setDocType(e.target.value)}
                                        className="w-full bg-slate-800/50 border border-slate-700 rounded-xl py-3 px-4 text-white focus:outline-none focus:ring-2 focus:ring-blue-500/50 focus:border-blue-500/50 transition-all"
                                    >
                                        <option value="V">V</option>
                                        <option value="E">E</option>
                                        <option value="J">J</option>
                                    </select>
                                </div>
                                <div className="w-2/3 space-y-2">
                                    <label className="text-sm font-medium text-slate-300 ml-1">N┬║ Documento</label>
                                    <input
                                        type="text"
                                        value={docNumber}
                                        onChange={(e) => setDocNumber(e.target.value)}
                                        className="w-full bg-slate-800/50 border border-slate-700 rounded-xl py-3 px-4 text-white placeholder:text-slate-600 focus:outline-none focus:ring-2 focus:ring-blue-500/50 focus:border-blue-500/50 transition-all"
                                        placeholder="12345678"
                                        required
                                    />
                                </div>
                            </div>
                        )}

                        {mode === 'register' && (
                            <div className="space-y-2 animate-in slide-in-from-top-2 fade-in duration-300">
                                <label className="text-sm font-medium text-slate-300 ml-1">Nombre y apellido</label>
                                <input
                                    type="text"
                                    value={fullName}
                                    onChange={(e) => setFullName(e.target.value)}
                                    className="w-full bg-slate-800/50 border border-slate-700 rounded-xl py-3 px-4 text-white placeholder:text-slate-600 focus:outline-none focus:ring-2 focus:ring-blue-500/50 focus:border-blue-500/50 transition-all"
                                    placeholder="Carlos Cede├▒o"
                                    required
                                />
                            </div>
                        )}

                        {mode === 'register' && (
                            <div className="space-y-2 animate-in slide-in-from-top-2 fade-in duration-300">
                                <label className="text-sm font-medium text-slate-300 ml-1">Celular</label>
                                <input
                                    type="tel"
                                    value={phone}
                                    onChange={(e) => setPhone(e.target.value)}
                                    className="w-full bg-slate-800/50 border border-slate-700 rounded-xl py-3 px-4 text-white placeholder:text-slate-600 focus:outline-none focus:ring-2 focus:ring-blue-500/50 focus:border-blue-500/50 transition-all"
                                    placeholder="04241234567"
                                    required
                                />
                            </div>
                        )}

                        {mode === 'login' && (
                            <div className="flex justify-end">
                                <button
                                    type="button"
                                    onClick={() => setMode('forgot-password')}
                                    className="text-sm text-blue-400 hover:text-blue-300 hover:underline"
                                >
                                    ┬┐Olvidaste tu contrase├▒a?
                                </button>
                            </div>
                        )}

                        {error && (
                            <div className="bg-red-500/10 border border-red-500/20 text-red-400 p-3 rounded-xl text-sm text-center">
                                {error}
                            </div>
                        )}

                        {successMessage && (
                            <div className="bg-green-500/10 border border-green-500/20 text-green-400 p-3 rounded-xl text-sm text-center">
                                {successMessage}
                            </div>
                        )}

                        <button
                            type="submit"
                            disabled={loading}
                            className="w-full bg-blue-600 hover:bg-blue-500 text-white font-semibold py-3 rounded-xl shadow-lg shadow-blue-600/20 transition-all disabled:opacity-50 disabled:cursor-not-allowed transform active:scale-[0.98]"
                        >
                            {loading ? 'Procesando...' :
                                mode === 'login' ? 'Iniciar Sesi├│n' :
                                    mode === 'register' ? 'Registrarse' :
                                        'Enviar Enlace'}
                        </button>
                    </form>
                    )}

                    {mode !== 'success' && (
                        <div className="mt-8 text-center text-slate-400 text-sm">
                            {mode === 'login' ? (
                                <>
                                    ┬┐No tienes cuenta?
                                    <button
                                        onClick={() => setMode('register')}
                                        className="text-blue-400 font-semibold ml-2 hover:underline focus:outline-none"
                                    >
                                        Reg├¡strate
                                    </button>
                                </>
                            ) : mode === 'register' ? (
                                <>
                                    ┬┐Ya tienes cuenta?
                                    <button
                                        onClick={() => setMode('login')}
                                        className="text-blue-400 font-semibold ml-2 hover:underline focus:outline-none"
                                    >
                                        Inicia sesi├│n
                                    </button>
                                </>
                            ) : (
                                <button
                                    onClick={() => setMode('login')}
                                    className="flex items-center justify-center gap-2 text-slate-400 hover:text-white mx-auto transition-colors"
                                >
                                    <ArrowLeft className="w-4 h-4" />
                                    Volver al inicio de sesi├│n
                                </button>
                            )}
                        </div>
                    )}
                </div>

                <div className="bg-slate-800/50 p-4 flex justify-center border-t border-slate-800">
                    <button onClick={onClose} className="text-slate-500 hover:text-slate-300 text-sm font-medium transition-all">
                        Cerrar ventana
                    </button>
                </div>
            </div>
        </div>
    );
};

import React, { useState } from 'react';
import { RotateCw, Plus, ChevronLeft, ChevronRight } from 'lucide-react';
import { fetchCardDetails, addToCart } from '../../utils/api';
import { CardImage } from './CardImage';

export interface CardFace {
  image_url?: string;
  image_uris?: {
    small?: string;
    normal?: string;
    large?: string;
    png?: string;
  };
  name: string;
  mana_cost?: string;
  type_line?: string;
  oracle_text?: string;
}

export interface CardProps {
  name: string;
  set: string;
  imageUrl?: string;
  image_url?: string;
  price: number;
  card_id: string;
  rarity?: string;
  type?: string;
  card_faces?: CardFace[];
  viewMode?: 'grid' | 'list';
  total_stock?: number;
  original_price?: number;
  discount_percentage?: number;
  finish?: string;
  is_foil?: boolean;
  isArchive?: boolean;
  showCartButton?: boolean;
  is_accessory?: boolean;
  accessory_id?: string;
  restocked_at?: string;
  additional_images?: string[];
  onClick?: () => void;
}

export const Card = React.memo<CardProps>(({ name, set, imageUrl, image_url, price, original_price, discount_percentage, card_id, rarity, type, card_faces, viewMode = 'grid', total_stock, finish, is_foil, isArchive, showCartButton = false, is_accessory, accessory_id, additional_images, restocked_at, onClick }) => {
  const isNew = restocked_at ? (Date.now() - new Date(restocked_at).getTime()) < 14 * 24 * 60 * 60 * 1000 : false;
  const [currentFaceIndex, setCurrentFaceIndex] = useState(0);
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const [addingToCart, setAddingToCart] = useState(false);

  const isDFC = name?.includes(' // ');
  const hasMultipleFaces = (card_faces && card_faces.length > 1) || isDFC;

  const allImages = React.useMemo(() => {
    let mainImg = imageUrl || image_url;
    if (card_faces && card_faces.length > 1) {
      mainImg = card_faces[currentFaceIndex].image_uris?.normal || card_faces[currentFaceIndex].image_url || mainImg;
    } else if (isDFC && currentFaceIndex === 1 && mainImg) {
      if (mainImg.includes('/front/')) mainImg = mainImg.replace('/front/', '/back/');
      else if (mainImg.includes('.jpg')) mainImg = mainImg.replace('.jpg', '_back.jpg');
      else if (mainImg.includes('.png')) mainImg = mainImg.replace('.png', '_back.png');
    }

    const list = mainImg ? [mainImg] : [];
    if (additional_images && additional_images.length > 0) {
      additional_images.forEach(img => {
        if (img && img !== mainImg) list.push(img);
      });
    }
    return list;
  }, [hasMultipleFaces, isDFC, card_faces, currentFaceIndex, imageUrl, image_url, additional_images]);

  const currentName = (card_faces && card_faces.length > 1) ? card_faces[currentFaceIndex].name : (isDFC && name ? name.split(' // ')[currentFaceIndex] : name);
  const isPresale = currentName?.toLowerCase().includes('(preventa)');
  const cleanName = isPresale ? currentName.replace(/\(preventa\)/gi, '').trim() : currentName;

  const currentType = (card_faces && card_faces.length > 1) ? card_faces[currentFaceIndex].type_line || type : type;
  const imgSrc = allImages[currentImageIndex] || allImages[0] || '';

  const handleFlip = (e: React.MouseEvent) => {
    e.stopPropagation();
    e.preventDefault();
    setCurrentFaceIndex((prev) => (prev + 1) % (card_faces && card_faces.length > 1 ? card_faces.length : 2));
    setCurrentImageIndex(0);
  };

  const handleQuickAdd = async (e: React.MouseEvent) => {
    e.stopPropagation();
    e.preventDefault();
    if (addingToCart) return;

    setAddingToCart(true);
    try {
      if (is_accessory || accessory_id) {
          // If it's an accessory, we use a specialized helper if available or pass flag
          const result = await addToCart(accessory_id || card_id, 1, finish, true);
          if (result && !result.success) throw new Error(result.message || result.error || 'Error interno al agregar.');
      } else {
          const result = await addToCart(card_id, 1, finish);
          if (result && !result.success) throw new Error(result.message || result.error || 'Error interno al agregar.');
      }
    } catch (err: any) {
      console.error("Cart addition failed:", err);
      alert(err.message || "Error al a├▒adir al carrito. Por favor, intenta de nuevo.");
    } finally {
      setAddingToCart(false);
    }
  };


  const isFoil = is_foil === true || finish === 'foil' || name.toLowerCase().includes(' foil ') || (type?.toLowerCase().includes('foil')); // Simple heuristic if finish prop not fully populated yet

  const handlePreFetch = () => {
    // Pre-fetch card details on hover
    try {
      fetchCardDetails(card_id);
    } catch {
      // Ignore errors during pre-fetch
    }
  };

  if (viewMode === 'list') {
    return (
      <a
        href={`card/${card_id}`}
        onClick={(e) => {
          if (!e.ctrlKey && !e.metaKey) {
            e.preventDefault();
            onClick?.();
          }
        }}
        onMouseEnter={handlePreFetch}
        data-testid="product-card"
        className="flex items-center gap-4 px-4 py-3 bg-white dark:bg-black/40 hover:bg-neutral-50 dark:hover:bg-neutral-900 border border-neutral-200 dark:border-white/5 hover:border-geeko-cyan/50 dark:hover:border-geeko-cyan/30 rounded-xl transition-all cursor-pointer group shadow-sm dark:shadow-none"
      >
        <div className="w-12 h-16 bg-neutral-200 dark:bg-[#1a1a1a] rounded-md overflow-hidden flex-shrink-0 relative">
          <CardImage src={imgSrc} alt={currentName} size="small" fallbackIconSize={20} className="rounded-md" />
          {!!hasMultipleFaces && (
            <div className="absolute inset-0 bg-black/40 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
              <RotateCw size={12} className="text-white" />
            </div>
          )}
          {isFoil && (
            <div className="absolute inset-0 foil-shimmer opacity-30 pointer-events-none" />
          )}
        </div>

        <div className="mt-4 flex-1 flex flex-col min-w-0">
        <h3 className="text-black dark:text-white font-bold text-sm sm:text-base leading-tight group-hover:text-geeko-cyan transition-colors break-words whitespace-normal relative z-10 flex flex-wrap items-center gap-2">
            {cleanName}
            {isPresale && (
              <span className="px-1.5 py-0.5 bg-geeko-cyan text-black text-[7px] font-black uppercase rounded shadow-lg shadow-geeko-cyan/20">Preventa</span>
            )}
            {isNew && (
              <span className="px-1.5 py-0.5 bg-purple-600 text-[7px] font-black uppercase rounded shadow-lg shadow-purple-500/20 animate-pulse">Nuevo</span>
            )}
          </h3>
          <div className="flex items-center gap-2 mt-0.5">
            <span className="text-[10px] text-neutral-600 dark:text-text-low font-bold uppercase tracking-wider px-1.5 py-0.5 bg-black/5 dark:bg-white/5 rounded">{set}</span>
            {!is_accessory && rarity && (
              <span className={`text-[9px] font-black uppercase tracking-widest ${rarity.toLowerCase() === 'mythic' ? 'text-orange-400' :
                rarity.toLowerCase() === 'rare' ? 'text-geeko-gold' : 'text-text-low'
                }`}>
                {rarity}
              </span>
            )}
            {isFoil && (
              <span className="flex items-center gap-1 text-[8px] bg-gradient-to-r from-pink-500 via-purple-500 to-cyan-500 text-white px-1.5 py-0.5 rounded uppercase font-bold tracking-wider animate-pulse">
                <svg width="8" height="10" viewBox="0 0 10 12" fill="none" className="drop-shadow-sm">
                  <rect x="0.5" y="0.5" width="9" height="11" rx="1.5" stroke="currentColor" strokeWidth="1" />
                  <path d="M2 3 L8 3 M2 5 L6 5" stroke="currentColor" strokeWidth="1" />
                  <circle cx="7" cy="8" r="1.5" fill="currentColor" />
                </svg>
                Foil
              </span>
            )}
          </div>
        </div>

        {/* Stock Indicator List View */}
        <div className="hidden sm:flex flex-col items-center justify-center px-4">
          {total_stock !== undefined && total_stock > 0 ? (
            <span className="text-[10px] font-black uppercase tracking-widest text-geeko-cyan bg-geeko-cyan/10 px-2 py-1 rounded-md">
              DISP: {total_stock}
            </span>
          ) : (
            <span className="text-[10px] font-bold text-text-low uppercase tracking-widest">Por Encargo</span>
          )}
        </div>

        <div className="text-right flex flex-col items-end min-w-[80px] ml-auto pl-2 relative">
          <span className="text-[9px] uppercase text-text-low font-bold tracking-wider">Mercado</span>
          {discount_percentage && discount_percentage > 0 ? (
              <div className="flex flex-col items-end gap-0.5">
                  <span className="text-[9px] text-text-low font-bold line-through">${original_price?.toFixed(2)}</span>
                  <div className="flex items-center gap-1.5">
                      <span className="text-geeko-cyan font-mono font-bold text-base leading-none">
                        {typeof price === 'number' ? `$${price.toFixed(2)}` : '---'}
                      </span>
                      <span className="text-[8px] bg-purple-500/20 text-purple-400 border border-purple-500/30 px-1 py-0.5 rounded font-black">-{discount_percentage}%</span>
                  </div>
              </div>
          ) : (
              <div className="flex items-center gap-1.5">
                <span className="text-geeko-cyan font-mono font-bold text-base leading-none">
                  {typeof price === 'number' ? `$${price.toFixed(2)}` : '---'}
                </span>
                {isFoil && (
                  <span className="text-[10px] bg-gradient-to-r from-pink-500 via-purple-500 to-cyan-500 text-white px-1.5 py-0.5 rounded uppercase font-black tracking-tighter" title="Versi├│n Foil">
                    FOIL
                  </span>
                )}
              </div>
          )}
        </div>

        {showCartButton && !isArchive && (
          <button
            onClick={handleQuickAdd}
            className={`ml-4 w-9 h-9 rounded-full flex items-center justify-center transition-all border border-white/5 ${addingToCart ? 'bg-geeko-cyan text-black' : 'bg-white/5 text-text-low hover:bg-geeko-cyan hover:text-black hover:scale-110'}`}
            title={(total_stock || 0) > 0 ? "Agregar al Carrito R├ípido" : "Por encargo"}
          >
            {addingToCart ? <div className="w-4 h-4 border-2 border-black/30 border-t-black rounded-full animate-spin" /> : <Plus size={20} strokeWidth={3} />}
          </button>
        )}
      </a>
    );
  }

  // Grid View
  return (
    <a
      href={`card/${card_id}`}
      onClick={(e) => {
        if (!e.ctrlKey && !e.metaKey) {
          e.preventDefault();
          onClick?.();
        }
      }}
      onMouseEnter={handlePreFetch}
      data-testid="product-card"
      className="relative group p-2 sm:p-4 bg-white dark:bg-neutral-900/40 border border-neutral-200 dark:border-white/5 rounded-[1.5rem] hover:bg-neutral-50 dark:hover:bg-neutral-900/80 transition-all cursor-pointer flex flex-col h-full hover:border-geeko-cyan/50 dark:hover:border-geeko-cyan/30 shadow-sm dark:shadow-none"
    >
      <div className="relative aspect-[63/88] w-full rounded-lg overflow-hidden bg-neutral-200 dark:bg-neutral-800 shadow-lg">

      {/* Flip Button overlay */}
      {!!hasMultipleFaces && (
        <button
          onClick={handleFlip}
          className="absolute top-2 left-2 z-10 p-1.5 bg-black/60 hover:bg-geeko-cyan text-white rounded-full border border-white/10 transition-colors"
        >
          <RotateCw size={14} className="group-hover:rotate-180 transition-transform duration-500" />
        </button>
      )}

      {/* PREVENTA Badge Overlay */}
      {isPresale && (
        <div className="absolute top-2 left-2 z-10 px-2 py-1 bg-geeko-cyan text-black text-[8px] font-black uppercase rounded shadow-lg shadow-geeko-cyan/30 flex items-center gap-1 animate-in zoom-in duration-300">
          <div className="w-1.5 h-1.5 bg-black rounded-full animate-pulse" />
          Preventa
        </div>
      )}

      {/* NEW Badge Overlay */}
      {isNew && (
        <div className={`absolute ${isPresale ? 'top-10' : 'top-2'} left-2 z-10 px-2 py-1 bg-purple-600 text-white text-[8px] font-black uppercase rounded shadow-lg shadow-purple-600/30 flex items-center gap-1 animate-in zoom-in duration-300`}>
          <div className="w-1 h-1 bg-white rounded-full animate-ping" />
          Nuevo
        </div>
      )}

      {/* Discount Ribbon (Top Left Diagonal) */}
      {!!(discount_percentage && discount_percentage > 0) && (
        <div className="absolute top-0 left-0 w-20 h-20 overflow-hidden z-10 pointer-events-none rounded-tl-2xl">
          <div className="absolute top-[16px] left-[-22px] w-[100px] py-1.5 bg-gradient-to-r from-purple-600 to-pink-600 text-white text-[10px] font-black uppercase text-center -rotate-45 shadow-[0_4px_15px_rgba(147,51,234,0.6)] border-y border-white/20 tracking-tighter">
            -{discount_percentage}%
          </div>
        </div>
      )}

      {/* Dynamic Background Glow for Hover */}
      <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-black/20 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300 pointer-events-none z-10" />

      {/* Card Image */}
      <div className={`relative aspect-[2.5/3.5] w-full bg-neutral-100 dark:bg-[#1a1a1a] overflow-hidden ${isFoil ? 'holo-effect' : ''}`}>
        {isFoil && (
          <div className="absolute inset-0 z-20 foil-shimmer opacity-30 mix-blend-overlay pointer-events-none" />
        )}

        <CardImage src={imgSrc} alt={currentName} size="small" fallbackIconSize={40} className="group-hover:scale-110 transition-transform duration-500" />

        {/* Carousel Navigation */}
        {!hasMultipleFaces && allImages.length > 1 && (
          <>
            <button
              onClick={(e) => {
                e.stopPropagation();
                e.preventDefault();
                setCurrentImageIndex((prev) => prev === 0 ? allImages.length - 1 : prev - 1);
              }}
              className="absolute top-1/2 left-2 -translate-y-1/2 z-20 p-1.5 bg-black/60 hover:bg-geeko-cyan text-white rounded-full opacity-0 group-hover:opacity-100 transition-all border border-white/10"
            >
              <ChevronLeft size={16} />
            </button>
            <button
              onClick={(e) => {
                e.stopPropagation();
                e.preventDefault();
                setCurrentImageIndex((prev) => (prev + 1) % allImages.length);
              }}
              className="absolute top-1/2 right-2 -translate-y-1/2 z-20 p-1.5 bg-black/60 hover:bg-geeko-cyan text-white rounded-full opacity-0 group-hover:opacity-100 transition-all border border-white/10"
            >
              <ChevronRight size={16} />
            </button>

            {/* Carousel Indicators */}
            <div className={`absolute left-1/2 -translate-x-1/2 z-20 flex gap-1.5 opacity-0 group-hover:opacity-100 transition-opacity ${total_stock !== undefined && total_stock > 0 ? 'bottom-8' : 'bottom-3'}`}>
              {allImages.map((_, idx) => (
                <div 
                  key={idx} 
                  className={`w-1.5 h-1.5 rounded-full transition-colors ${idx === currentImageIndex ? 'bg-geeko-cyan shadow-[0_0_5px_rgba(0,209,255,0.8)]' : 'bg-white/50'}`} 
                />
              ))}
            </div>
          </>
        )}

        {/* Stock display - Repositioned to bottom-left to avoid overlap with cart button */}
        {total_stock !== undefined && total_stock > 0 && (
          <div className="absolute bottom-3 left-3 z-20 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest backdrop-blur-md border border-white/20 dark:border-white/10 bg-black/80 dark:bg-black/95 text-white shadow-lg">
            DISP: {total_stock}
          </div>
        )}

        {/* Rarity Badge (Overlay) */}
        {!is_accessory && rarity && type?.toLowerCase() !== 'sealed product' && type?.toLowerCase() !== 'sealed' && rarity.toLowerCase() !== 'com├║n' && rarity.toLowerCase() !== 'comun' && rarity.toLowerCase() !== 'common' && (
          <div className={`absolute top-2 right-2 px-2 py-0.5 rounded-full text-[9px] font-black uppercase tracking-wider backdrop-blur-md border border-white/10 z-10 ${rarity.toLowerCase() === 'mythic' ? 'bg-orange-500/20 text-orange-400 border-orange-500/30' :
            rarity.toLowerCase() === 'rare' ? 'bg-geeko-gold/20 text-geeko-gold border-geeko-gold/30' :
