                ? 'w-12 lg:w-10 bg-white text-black scale-100 opacity-100' 
                : 'w-12 lg:w-10 hover:w-[140px] bg-geeko-cyan text-black border border-white/20 shadow-[0_0_15px_rgba(0, 209, 255, 0.4)] opacity-100 translate-y-0 scale-100'
            }`}
          >
