              {addingToCart ? (
                <div className="w-4 h-4 border-2 border-black/30 border-t-black rounded-full animate-spin flex-shrink-0" />
              ) : (
                <Plus size={22} strokeWidth={3.5} className="flex-shrink-0" />
              )}
              <span className="text-[10px] font-black uppercase tracking-tight opacity-0 group-hover/addbtn:opacity-100 transition-opacity duration-300 pointer-events-none">
                A├▒adir al carrito
              </span>
            </div>
            </button>
          )}
        </div>
      </div>

      {/* Card Info */}
      <div className="p-4 flex flex-col gap-1 z-20 bg-neutral-50 dark:bg-[#0a0a0a]/90 backdrop-blur-md border-t border-neutral-200 dark:border-white/5 flex-grow">
        {/* Fix text overlap: Truncate + Title */}
        <h3 className="text-black dark:text-white text-sm font-bold truncate leading-snug group-hover:text-geeko-cyan transition-colors" title={cleanName}>
          {cleanName}
        </h3>

        <div className="text-xs text-neutral-500 dark:text-neutral-400 mt-2 truncate flex items-center gap-1.5 font-medium">
          <span className="px-1.5 py-0.5 bg-black/5 dark:bg-white/5 rounded text-[10px] font-black uppercase tracking-widest text-neutral-600 dark:text-text-low">
            {set}
          </span>
          {currentType && <span className="truncate max-w-[30%] opacity-50 text-right">{currentType.split('ΓÇö')[0].trim()}</span>}
        </div>

        {/* Price Row */}
        <div className="mt-auto pt-3 flex items-center justify-between border-t border-neutral-200 dark:border-white/5">
          <div className="flex flex-col text-right w-full relative">
            <span className="text-[8px] uppercase text-neutral-500 dark:text-text-low font-bold tracking-wider absolute -top-2 right-0">Mercado</span>
            {discount_percentage && discount_percentage > 0 ? (
                <div className="flex flex-col items-end gap-0.5">
                    <div className="flex items-center gap-1.5 justify-end">
                        <span className="text-[9px] text-neutral-400 dark:text-text-low font-bold line-through">${original_price?.toFixed(2)}</span>
                        <span className="text-[8px] bg-purple-500/10 dark:bg-purple-500/20 text-purple-600 dark:text-purple-400 border border-purple-500/20 dark:border-purple-500/30 px-1 rounded font-black">-{discount_percentage}%</span>
                    </div>
                    <div className="flex items-center justify-end gap-1.5">
                      <span className="text-geeko-cyan font-mono font-bold text-base tracking-tight leading-none">
                        {price && price > 0 ? `$${price.toFixed(2)}` : 'S/P'}
                      </span>
                    </div>
                </div>
            ) : (
                <div className="flex items-center justify-end gap-1.5">
                  <span className="text-geeko-cyan font-mono font-bold text-base tracking-tight leading-none">
                    {price && price > 0 ? `$${price.toFixed(2)}` : 'S/P'}
                  </span>
                  {isFoil && (
                    <span className="text-[10px] bg-gradient-to-r from-pink-500 via-purple-500 to-cyan-500 text-white px-1.5 py-0.5 rounded uppercase font-black tracking-tighter" title="Versi├│n Foil">
                      FOIL
                    </span>
                  )}
                </div>
            )}
          </div>

        </div>
      </div>
    </a>
  );
});

import React from 'react';
import { Card } from './Card';
import type { CardProps } from './Card';

export interface CardGridProps {
  cards: (CardProps & { card_id: string })[];
  onCardClick?: (id: string, imageUrl?: string, fullCard?: any) => void;
  viewMode?: 'grid' | 'list';
  isArchive?: boolean;
  showCartButton?: boolean;
}

export const CardGrid: React.FC<CardGridProps> = ({ cards, onCardClick, viewMode = 'grid', isArchive, showCartButton }) => {
  return (
    <section className="w-full">
      {cards.length === 0 ? (
        <div className="text-center text-text-low py-12 text-lg">
          No se encontraron cartas.
        </div>
      ) : (
        <div className={viewMode === 'grid'
          ? "grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 gap-4"
          : "flex flex-col gap-2"
        }>
          {cards.map((card) => (
            <Card
              key={card.card_id}
              {...card}
              viewMode={viewMode}
              isArchive={isArchive}
              showCartButton={showCartButton}
              onClick={() => onCardClick && onCardClick(card.card_id, card.image_url, card)}
            />
          ))}
        </div>
      )}
    </section>
  );
}

import React, { useState, useMemo } from 'react';
import { Search, X, Sliders, Filter, Check, Package, ChevronDown, ChevronUp } from 'lucide-react';
import { rarityMap, typeMap, colorMap } from '../../utils/translations';

const gameNameMap: Record<string, string> = {
  'MTG': 'Magic: The Gathering',
  'PKM': 'Pok├⌐mon',
  'OPC': 'One Piece',
  'DGM': 'Digimon',
  'LOR': 'Lorcana',
  'YGO': 'Yu-Gi-Oh!',
  'FAB': 'Flesh and Blood',
  'WXS': 'Wixoss',
  'GND': 'Gundam Card Game',
  'RFB': 'Riftbound'
};

export interface Filters {
  games: string[];
  sets: string[];
  rarities: string[];
  colors: string[];
  types: string[];
  categories?: string[];
  yearRange: [number, number];
  priceRange: [number | undefined, number | undefined];
  only_new?: boolean;
  only_discount?: boolean;
  only_presale?: boolean;
}

export interface FiltersPanelProps {
  filters: Filters;
  selected: Partial<Filters>;
  onChange: (selected: Partial<Filters>) => void;
  setsOptions: string[];
  isAccessoryMode?: boolean;
}

export const FiltersPanel: React.FC<FiltersPanelProps> = ({ filters, selected, onChange, setsOptions, isAccessoryMode }) => {
  const [setSearch, setSetSearch] = useState('');
  const [expandedSections, setExpandedSections] = useState<Record<string, boolean>>(() => {
    const initialState: Record<string, boolean> = {};
    if (selected.games && selected.games.length > 0) initialState.games = true;
    if (selected.sets && selected.sets.length > 0) initialState.sets = true;
    if (selected.categories && selected.categories.length > 0) initialState.categories = true;
    if (selected.rarities && selected.rarities.length > 0) initialState.rarities = true;
    if (selected.colors && selected.colors.length > 0) initialState.colors = true;
    if (selected.types && selected.types.length > 0) initialState.types = true;
    if (selected.priceRange && ((selected.priceRange[0] !== undefined && selected.priceRange[0] > 0) || (selected.priceRange[1] !== undefined))) initialState.price = true;
    if (selected.yearRange && (selected.yearRange[0] > 1993 || selected.yearRange[1] < 2026)) initialState.year = true;
    return initialState;
  });

  const toggleSection = (section: string) => {
    setExpandedSections(prev => ({ ...prev, [section]: !prev[section] }));
  };

  const filteredSets = useMemo(() => {
    if (!setSearch) return setsOptions.slice(0, 50);
    return setsOptions.filter(s => s.toLowerCase().includes(setSearch.toLowerCase())).slice(0, 50);
  }, [setsOptions, setSearch]);

  const handleCheckbox = (key: keyof Omit<Filters, 'yearRange'>, value: string) => {
    const prev = (selected[key] as string[]) || [];
    if (prev.includes(value)) {
      onChange({ ...selected, [key]: prev.filter((v: string) => v !== value) });
    } else {
      onChange({ ...selected, [key]: [...prev, value] });
    }
  };

  const clearFilters = () => {
    onChange({});
    setSetSearch('');
  };

  const hasActiveFilters = Object.values(selected).some(v => v && (typeof v === 'boolean' ? v : (v as any).length > 0));

  const selectedGame = selected.games && selected.games.length === 1 ? selected.games[0] : null;

  const getGameSpecificColors = () => {
    if (selectedGame === 'MTG') return ['White', 'Blue', 'Black', 'Red', 'Green', 'Colorless', 'Multicolor'];
    if (selectedGame === 'OPC' || selectedGame === 'ONE PIECE') return ['Red', 'Blue', 'Green', 'Purple', 'Black', 'Yellow'];
    if (selectedGame === 'DGM' || selectedGame === 'DIGIMON') return ['Red', 'Blue', 'Yellow', 'Green', 'Black', 'Purple', 'White'];
    if (selectedGame === 'PKM' || selectedGame === 'POKEMON') return ['Grass', 'Fire', 'Water', 'Lightning', 'Psychic', 'Fighting', 'Darkness', 'Metal', 'Fairy', 'Dragon', 'Colorless'];
    // Gundam Card Game ΓÇö naciones/colores del universo Gundam
    if (selectedGame === 'GND') return ['Red', 'Blue', 'Yellow', 'Green', 'Purple', 'White'];
    return []; // No mostrar colores si no hay juego espec├¡fico o no aplica
  };

  const getGameSpecificTypes = () => {
    if (selectedGame === 'MTG') return ['Creature', 'Instant', 'Sorcery', 'Enchantment', 'Artifact', 'Planeswalker', 'Land'];
    if (selectedGame === 'PKM' || selectedGame === 'POKEMON') return ['Pok├⌐mon', 'Trainer', 'Energy'];
    if (selectedGame === 'OPC' || selectedGame === 'ONE PIECE') return ['Character', 'Event', 'Stage', 'Leader'];
    // Gundam Card Game ΓÇö tipos de carta del juego
    if (selectedGame === 'GND') return ['Unit', 'Command', 'Resource', 'Pilot', 'Base'];
    return [];
  };

  const currentColors = getGameSpecificColors();
  const currentTypes = getGameSpecificTypes();

  return (
    <aside className="w-full glass-panel border border-neutral-200 dark:border-white/5 p-8 rounded-[32px] shadow-2xl space-y-10">
      <div className="flex items-center justify-between mb-2">
        <h2 className="text-sm md:text-lg font-black italic tracking-tighter text-black dark:text-white flex items-center gap-2">
          <Sliders size={18} className="text-geeko-cyan" />
          FILTROS
        </h2>
        {hasActiveFilters && (
          <button
            onClick={clearFilters}
            className="text-[10px] font-bold uppercase tracking-widest text-neutral-500 dark:text-text-low hover:text-red-500 dark:hover:text-red-400 transition-colors flex items-center gap-1 group"
          >
            <X size={10} className="group-hover:rotate-90 transition-transform" />
            Reiniciar
          </button>
        )}
      </div>

      {/* Juegos - Ocultar si ya hay uno seleccionado */}
      {!selectedGame && (
        <section className="border-b border-neutral-200 dark:border-white/5 pb-6">
          <button 
            onClick={() => toggleSection('games')}
            className="w-full flex items-center justify-between text-[10px] md:text-[11px] font-black uppercase tracking-[0.2em] text-neutral-500 dark:text-text-low mb-2 hover:text-black dark:hover:text-text-high transition-colors"
          >
            <div className="flex items-center gap-2">
              <div className="w-1.5 h-1.5 bg-geeko-cyan rounded-full shadow-[0_0_10px_rgba(0, 209, 255, 0.8)]"></div>
              Universo de Juegos
            </div>
            {expandedSections.games ? <ChevronUp size={14} /> : <ChevronDown size={14} />}
          </button>
          
          {expandedSections.games && (
            <div className="flex flex-wrap gap-2 pt-3 animate-in fade-in slide-in-from-top-1 duration-200">
              {filters.games.map(game => {
                const isSelected = selected.games?.includes(game);
                return (
                  <button
                    key={game}
                    onClick={() => handleCheckbox('games', game)}
                    className={`px-4 py-2 rounded-xl text-[11px] md:text-[12px] font-bold transition-all border ${isSelected
                      ? 'bg-geeko-violet-accent/10 dark:bg-geeko-violet-accent/20 border-geeko-cyan/40 text-geeko-cyan shadow-lg shadow-geeko-cyan/10'
                      : 'bg-white dark:bg-neutral-900/50 border-neutral-200 dark:border-neutral-800 text-neutral-600 dark:text-text-low hover:border-neutral-400 dark:hover:border-neutral-700 hover:text-black dark:hover:text-text-high'
                      }`}
                  >
                    {gameNameMap[game] || game}
                  </button>
                );
              })}
            </div>
          )}
        </section>
      )}

      {/* Sets - Solo Singles */}
      {!isAccessoryMode && (
        <section className="border-b border-neutral-200 dark:border-white/5 pb-6">
          <button 
            onClick={() => toggleSection('sets')}
            className="w-full flex items-center justify-between text-[11px] font-black uppercase tracking-[0.2em] text-neutral-500 dark:text-text-low mb-2 hover:text-black dark:hover:text-text-high transition-colors"
          >
            <div className="flex items-center gap-2">
              <div className="w-1.5 h-1.5 bg-geeko-violet-accent rounded-full shadow-[0_0_10px_rgba(55,50,102,0.9)]"></div>
              Expansi├│n / Set
            </div>
            {expandedSections.sets ? <ChevronUp size={14} /> : <ChevronDown size={14} />}
          </button>

          {expandedSections.sets && (
            <div className="pt-3 animate-in fade-in slide-in-from-top-1 duration-200">
              <div className="relative mb-3">
                <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-neutral-400 dark:text-text-low" />
                <input
                  type="text"
                  placeholder="Buscar sets..."
                  value={setSearch}
                  onChange={(e) => setSetSearch(e.target.value)}
                  className="w-full bg-white dark:bg-neutral-900/50 border border-neutral-200 dark:border-neutral-800 rounded-xl py-2.5 pl-9 pr-4 text-xs text-black dark:text-text-high placeholder:text-neutral-400 dark:placeholder:text-text-low/50 focus:outline-none focus:border-purple-500/50 transition-all font-medium"
                />
              </div>
              <div className="max-h-52 overflow-y-auto pr-2 custom-scrollbar space-y-1">
                {filteredSets.length > 0 ? (
                  filteredSets.map(setName => (
                    <button
                      key={setName}
                      onClick={() => handleCheckbox('sets', setName)}
                      className={`flex items-center justify-between w-full px-3 py-2 rounded-lg text-left text-[11px] md:text-[12px] font-medium transition-all ${selected.sets?.includes(setName)
                        ? 'bg-geeko-cyan/10 text-geeko-cyan'
                        : 'text-neutral-600 dark:text-text-low hover:bg-black/5 dark:hover:bg-white/5 hover:text-black dark:hover:text-text-high'
                        }`}
                    >
                      <span className="truncate pr-4">{setName}</span>
                      {selected.sets?.includes(setName) && <Check size={12} />}
                    </button>
                  ))
                ) : (
                  <p className="text-[10px] text-text-low italic py-4 text-center">No hay sets.</p>
                )}
              </div>
            </div>
          )}
        </section>
      )}

      {/* Categor├¡as - Solo Cat├ílogo */}
      {isAccessoryMode && filters.categories && (
        <section className="border-b border-white/5 pb-6">
          <button 
            onClick={() => toggleSection('categories')}
            className="w-full flex items-center justify-between text-[11px] font-black uppercase tracking-[0.2em] text-text-low mb-2 hover:text-text-high transition-colors"
          >
            <div className="flex items-center gap-2">
              <div className="w-1.5 h-1.5 bg-orange-500 rounded-full shadow-[0_0_10px_rgba(249,115,22,0.8)]"></div>
              Categor├¡a
            </div>
            {expandedSections.categories ? <ChevronUp size={14} /> : <ChevronDown size={14} />}
          </button>

          {expandedSections.categories && (
            <div className="grid grid-cols-1 gap-2 pt-3 animate-in fade-in slide-in-from-top-1 duration-200">
              {filters.categories
                .map(category => {
                  const isSelected = selected.categories?.includes(category);
                  return (
                    <button
                      key={category}
                      onClick={() => handleCheckbox('categories' as any, category)}
                      className={`flex items-center justify-between w-full px-4 py-3 rounded-xl border transition-all ${isSelected
                        ? 'bg-orange-500/10 border-orange-500/40 text-orange-400 shadow-lg shadow-orange-500/5'
                        : 'bg-neutral-900/50 border-neutral-800 text-text-low hover:border-neutral-700'
                        }`}
                    >
                      <div className="flex items-center gap-3">
                        <Package size={14} className={isSelected ? 'text-orange-400' : 'text-text-low'} />
                        <span className="text-[10px] font-black uppercase tracking-tight">{category}</span>
                      </div>
                      {isSelected && <Check size={12} />}
                    </button>
                  );
                })}
            </div>
          )}
        </section>
      )}

      {/* Rareza - Solo para Cartas */}
      {!isAccessoryMode && filters.rarities && (
        <section className="border-b border-neutral-200 dark:border-white/5 pb-6">
          <button 
            onClick={() => toggleSection('rarities')}
            className="w-full flex items-center justify-between text-[11px] font-black uppercase tracking-[0.2em] text-neutral-500 dark:text-text-low mb-2 hover:text-black dark:hover:text-text-high transition-colors"
          >
            <div className="flex items-center gap-2">
              <div className="w-1.5 h-1.5 bg-geeko-gold rounded-full shadow-[0_0_10px_rgba(255,215,0,0.8)]"></div>
              Rareza
            </div>
            {expandedSections.rarities ? <ChevronUp size={14} /> : <ChevronDown size={14} />}
          </button>

          {expandedSections.rarities && (
            <div className="grid grid-cols-2 gap-2 pt-3 animate-in fade-in slide-in-from-top-1 duration-200">
              {filters.rarities.map(rarity => {
                const isSelected = selected.rarities?.includes(rarity);
                return (
                  <button
                    key={rarity}
                    onClick={() => handleCheckbox('rarities', rarity)}
                    className={`flex items-center gap-2 px-3 py-2.5 rounded-xl border transition-all ${isSelected
                      ? 'bg-geeko-gold/10 border-geeko-gold/40 text-geeko-gold shadow-lg shadow-geeko-gold/5'
                      : 'bg-white dark:bg-neutral-900/50 border-neutral-200 dark:border-neutral-800 text-neutral-600 dark:text-text-low hover:border-neutral-400 dark:hover:border-neutral-700'
                      }`}
                  >
                    <div className={`w-1.5 h-1.5 rounded-full ${isSelected ? 'bg-geeko-gold animate-pulse' : 'bg-neutral-700'}`} />
                    <span className="text-[10px] font-black uppercase tracking-tight">{rarityMap[rarity] || rarity}</span>
                  </button>
                );
              })}
            </div>
          )}
        </section>
      )}

      {/* Colores Contextuales */}
      {!isAccessoryMode && currentColors.length > 0 && (
        <section className="border-b border-neutral-200 dark:border-white/5 pb-6">
          <button 
            onClick={() => toggleSection('colors')}
            className="w-full flex items-center justify-between text-[11px] font-black uppercase tracking-[0.2em] text-neutral-500 dark:text-text-low mb-2 hover:text-black dark:hover:text-text-high transition-colors"
          >
            <div className="flex items-center gap-2">
              <div className="w-1.5 h-1.5 bg-geeko-cyan rounded-full shadow-[0_0_10px_rgba(0, 209, 255, 0.8)]"></div>
              {selectedGame === 'MTG' ? 'Mana (Colores)' : 'Colores'}
            </div>
            {expandedSections.colors ? <ChevronUp size={14} /> : <ChevronDown size={14} />}
          </button>

          {expandedSections.colors && (
            <div className="grid grid-cols-4 gap-2 pt-3 animate-in fade-in slide-in-from-top-1 duration-200">
              {currentColors.map(color => {
                const isSelected = selected.colors?.includes(color);
                const colorClassMap: Record<string, string> = {
                  'White': 'bg-[#F8E7B9] shadow-[0_0_10px_#F8E7B9]',
                  'Blue': 'bg-[#0E68AB] shadow-[0_0_10px_#0E68AB]',
                  'Black': 'bg-[#150B00] shadow-[0_0_10px_#150B00] border border-white/20',
                  'Red': 'bg-[#D3202A] shadow-[0_0_10px_#D3202A]',
                  'Green': 'bg-[#00733E] shadow-[0_0_10px_#00733E]',
                  'Colorless': 'bg-[#D3D3D3] shadow-[0_0_10px_#D3D3D3]',
                  'Multicolor': 'bg-gradient-to-br from-[#F8E7B9] via-[#D3202A] to-[#0E68AB]',
                  'Grass': 'bg-[#7db808]', 'Fire': 'bg-[#e3350d]', 'Water': 'bg-[#318bc9]', 'Lightning': 'bg-[#eed535]',
                  'Psychic': 'bg-[#a33ea1]', 'Fighting': 'bg-[#ce4069]', 'Darkness': 'bg-[#707070]', 'Metal': 'bg-[#b7b7ce]',
                  'Fairy': 'bg-[#fdb9e9]', 'Dragon': 'bg-[#53a4cf]',
                  'Purple': 'bg-[#800080]', 'Yellow': 'bg-[#ffff00]',
                };

                return (
                  <button
                    key={color}
                    onClick={() => handleCheckbox('colors', color)}
                    title={colorMap[color] || color}
                    className={`relative group w-full aspect-square rounded-xl border flex items-center justify-center transition-all ${isSelected
                      ? 'border-geeko-cyan/50 bg-geeko-cyan/10'
                      : 'border-neutral-200 dark:border-neutral-800 bg-white dark:bg-neutral-900/50 hover:border-neutral-400 dark:hover:border-neutral-600'
                      }`}
                  >
                    <div className={`w-4 h-4 rounded-full ${colorClassMap[color] || 'bg-neutral-500'} ${isSelected ? 'scale-125' : 'opacity-80 group-hover:opacity-100'} transition-all`} />
                    {isSelected && <div className="absolute top-1 right-1"><Check size={8} className="text-geeko-cyan" /></div>}
                  </button>
                );
              })}
            </div>
          )}
        </section>
      )}

      {/* Tipos Contextuales */}
      {!isAccessoryMode && currentTypes.length > 0 && (
        <section className="border-b border-neutral-200 dark:border-white/5 pb-6">
          <button 
            onClick={() => toggleSection('types')}
            className="w-full flex items-center justify-between text-[11px] font-black uppercase tracking-widest text-neutral-500 dark:text-text-low mb-2 hover:text-black dark:hover:text-text-high transition-colors"
          >
            <div className="flex items-center gap-2">
              <div className="w-1 h-3 bg-red-600 rounded-full"></div>
              {selectedGame === 'MTG' ? 'Tipo de Carta' : 'Tipo'}
            </div>
            {expandedSections.types ? <ChevronUp size={14} /> : <ChevronDown size={14} />}
          </button>

          {expandedSections.types && (
            <div className="flex flex-wrap gap-2 pt-3 animate-in fade-in slide-in-from-top-1 duration-200">
              {currentTypes.map(type => {
                const isSelected = selected.types?.includes(type);
                return (
                  <button
                    key={type}
                    onClick={() => handleCheckbox('types', type)}
                    className={`px-3 py-1.5 rounded-lg text-[10px] md:text-[11px] font-bold transition-all border ${isSelected
                      ? 'bg-red-600/10 border-red-500/50 text-red-400'
                      : 'bg-white dark:bg-neutral-900/50 border-neutral-200 dark:border-neutral-800 text-neutral-600 dark:text-text-low hover:text-black dark:hover:text-text-high hover:border-neutral-400 dark:hover:border-neutral-700'
                      }`}
                  >
                    {typeMap[type] || type}
                  </button>
                );
              })}
            </div>
          )}
        </section>
      )}

      {/* Promociones y Ofertas */}
      <section className="border-b border-neutral-200 dark:border-white/5 pb-6 space-y-3">
        <div className="flex items-center justify-between text-[11px] font-black uppercase tracking-[0.2em] text-neutral-500 dark:text-text-low mb-2">
          <div className="flex items-center gap-2">
            <div className="w-1.5 h-1.5 bg-emerald-400 rounded-full shadow-[0_0_10px_rgba(52,211,153,0.8)]"></div>
            Promociones
          </div>
        </div>

        <div className="grid grid-cols-2 gap-3">
          <button
            onClick={() => onChange({ ...selected, only_discount: !selected.only_discount })}
            className={`flex items-center gap-2.5 px-3 py-2.5 rounded-xl text-xs font-bold transition-all border ${
              selected.only_discount
                ? 'bg-emerald-500/10 dark:bg-emerald-500/20 border-emerald-400/50 dark:border-emerald-500/50 text-emerald-600 dark:text-emerald-400 shadow-[0_0_15px_rgba(16,185,129,0.1)] dark:shadow-[0_0_15px_rgba(16,185,129,0.2)]'
                : 'bg-neutral-50 dark:bg-neutral-900/50 border-neutral-200 dark:border-neutral-800 text-neutral-600 dark:text-text-low hover:border-neutral-300 dark:hover:border-neutral-700 hover:text-black dark:hover:text-text-high'
            }`}
          >
            <div className={`w-3.5 h-3.5 rounded flex items-center justify-center border ${selected.only_discount ? 'bg-emerald-500 border-emerald-400 text-white dark:text-black' : 'border-neutral-300 dark:border-neutral-700 bg-white dark:bg-neutral-800'}`}>
              {selected.only_discount && <Check size={10} strokeWidth={3} />}
            </div>
            En Descuento
          </button>

          <button
            onClick={() => onChange({ ...selected, only_presale: !selected.only_presale })}
            className={`flex items-center gap-2.5 px-3 py-2.5 rounded-xl text-xs font-bold transition-all border ${
              selected.only_presale
                ? 'bg-purple-500/10 dark:bg-purple-500/20 border-purple-400/50 dark:border-purple-500/50 text-purple-600 dark:text-purple-400 shadow-[0_0_15px_rgba(168,85,247,0.1)] dark:shadow-[0_0_15px_rgba(168,85,247,0.2)]'
                : 'bg-neutral-50 dark:bg-neutral-900/50 border-neutral-200 dark:border-neutral-800 text-neutral-600 dark:text-text-low hover:border-neutral-300 dark:hover:border-neutral-700 hover:text-black dark:hover:text-text-high'
