import React, { useRef } from 'react';
import { Card } from '../Card/Card';
import type { CardProps } from '../Card/Card';
import { ChevronLeft, ChevronRight } from 'lucide-react';

interface DealsCarouselProps {
  title: string;
  cards: (CardProps & { card_id: string })[];
  onCardClick?: (id: string, card?: any) => void;
  isArchive?: boolean;
}

export const DealsCarousel: React.FC<DealsCarouselProps> = ({ title, cards, onCardClick, isArchive }) => {
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  const scrollLeft = () => {
    if (scrollContainerRef.current) {
      const scrollAmount = scrollContainerRef.current.clientWidth * 0.9;
      scrollContainerRef.current.scrollBy({ left: -scrollAmount, behavior: 'smooth' });
    }
  };

  const scrollRight = () => {
    if (scrollContainerRef.current) {
      const scrollAmount = scrollContainerRef.current.clientWidth * 0.9;
      scrollContainerRef.current.scrollBy({ left: scrollAmount, behavior: 'smooth' });
    }
  };

  if (cards.length === 0) return null;

  return (
    <div className="relative group mb-8 px-4">
      <div className="flex flex-col items-center mb-4">
        <span className="text-[10px] font-black uppercase tracking-[0.4em] text-white mb-2 animate-pulse">
          {isArchive ? 'Coleccionables' : 'Stock Geekorium'}
        </span>
        <h2 className="text-3xl md:text-4xl font-black italic uppercase tracking-tighter text-white drop-shadow-[0_0_15px_rgba(255,255,255,0.1)]">
          {title}
        </h2>
        <div className="w-24 h-1 bg-gradient-to-r from-transparent via-white to-transparent mt-4"></div>
      </div>
      
      {/* Carrusel container */}
      <div className="relative">
        {/* Navigation Buttons - Adjusted for floating look */}
        <button
          onClick={scrollLeft}
          className="absolute left-0 top-1/2 -translate-y-1/2 -translate-x-2 md:-translate-x-8 z-30 w-12 h-12 rounded-full bg-black/60 backdrop-blur-md border border-white/10 flex items-center justify-center opacity-0 group-hover:opacity-100 hover:bg-white hover:text-black transition-all shadow-[0_0_20px_rgba(0,0,0,0.5)]"
        >
          <ChevronLeft size={24} />
        </button>
        
        <button
          onClick={scrollRight}
          className="absolute right-0 top-1/2 -translate-y-1/2 translate-x-2 md:translate-x-8 z-30 w-12 h-12 rounded-full bg-black/60 backdrop-blur-md border border-white/10 flex items-center justify-center opacity-0 group-hover:opacity-100 hover:bg-white hover:text-black transition-all shadow-[0_0_20px_rgba(0,0,0,0.5)]"
        >
          <ChevronRight size={24} />
        </button>

        {/* Scrollable Area */}
        <div 
          ref={scrollContainerRef}
          className="flex overflow-x-auto gap-6 pb-8 no-scrollbar scroll-smooth snap-x"
        >
          {cards.map((card) => (
            <div key={card.card_id} className="min-w-[160px] w-[160px] md:min-w-[180px] md:w-[180px] flex-shrink-0 snap-start">
              <Card
                {...card}
                viewMode="grid"
                isArchive={isArchive}
                showCartButton={true}
                onClick={() => onCardClick && onCardClick(card.card_id, card)}
              />
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { fetchEvents } from '../../utils/api';
import { useNavigate } from 'react-router-dom';

export const UpcomingMissionsWidget: React.FC = () => {
    const [events, setEvents] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const navigate = useNavigate();

    useEffect(() => {
        const loadEvents = async () => {
            try {
                const data = await fetchEvents();
                // Only take the next 6 events
                setEvents(data.slice(0, 6));
            } catch (error) {
                console.error("Failed to load events", error);
            } finally {
                setLoading(false);
            }
        };
        loadEvents();
    }, []);


    const getGameColor = (gameCode: string) => {
        switch (gameCode) {
            case 'MTG': return 'text-orange-500';
            case 'PKM': return 'text-yellow-500';
            case 'YGO': return 'text-amber-600';
            case 'DGM': return 'text-blue-500';
            case 'OPC': return 'text-red-500';
            case 'FAB': return 'text-purple-500';
            default: return 'text-white';
        }
    };

    if (loading) {
        return (
            <div className="w-72 bg-neutral-900/50 rounded-2xl border border-white/5 p-4 animate-pulse h-96"></div>
        );
    }

    if (events.length === 0) {
        return null; // Don't show the widget if there are no events
    }

    return (
        <div className="w-full flex flex-col gap-3">
            <div className="border border-geeko-cyan/30 rounded-lg p-3 text-center bg-gradient-to-r from-transparent via-geeko-cyan/5 to-transparent mb-2">
                <h3 className="text-black dark:text-white text-xs font-black uppercase tracking-widest">Pr├│ximas Misiones</h3>
            </div>
            
            <div className="flex flex-col gap-2">
                {events.map(event => {
                    const date = new Date(event.event_date);
                    const dayName = date.toLocaleDateString('es-ES', { weekday: 'long' });
                    const dateString = date.toLocaleDateString('es-ES', { day: '2-digit', month: '2-digit', year: '2-digit' });
                    
                    return (
                        <div 
                            key={event.id}
                            onClick={() => navigate('/tournaments')}
                            className="flex items-center gap-4 bg-white dark:bg-gradient-to-r from-neutral-900/80 to-black border border-neutral-200 dark:border-white/5 shadow-sm dark:shadow-none rounded-xl p-3 cursor-pointer hover:border-neutral-300 dark:hover:border-white/20 transition-all hover:translate-x-1 group"
                        >
                            {/* Game Icon / Code Indicator */}
                            <div className={`w-8 h-8 rounded-full bg-neutral-100 dark:bg-white/5 flex items-center justify-center font-black text-[9px] border border-neutral-200 dark:border-white/10 group-hover:bg-neutral-200 dark:group-hover:bg-white/10 ${getGameColor(event.game_code)}`}>
                                {event.game_code}
                            </div>
                            
                            <div className="flex flex-col">
                                <span className="text-black dark:text-white font-black text-[10px] uppercase tracking-wider">
                                    {dayName} {dateString}
                                </span>
                                <span className="text-neutral-500 dark:text-neutral-400 text-[11px] font-medium leading-tight group-hover:text-black dark:group-hover:text-white transition-colors">
                                    {event.name}
                                </span>
                            </div>
                        </div>
                    );
                })}
            </div>
        </div>
    );
};

