        }

        // Optimistic Update
        setOptimisticItems(displayItems.map(item => 
            item.id === cartItemId ? { ...item, quantity: newQuantity } : item
        ));

        setUpdating(cartItemId);
        try {
            await updateCartItemQuantity(cartItemId, newQuantity);
            // No need to call refreshCart here as api.ts dispatches 'cart-updated'
            // which CartContext listens to.
        } catch (err) {
            console.error('Failed to update quantity', err);
            alert('Error al actualizar cantidad');
            refreshCart(); // Rollback to server state
        } finally {
            setUpdating(null);
            setOptimisticItems(null);
        }
    };

    const handleRemoveItem = async (cartItemId: string) => {
        // Optimistic Remove
        setOptimisticItems(displayItems.filter(item => item.id !== cartItemId));
        
        setUpdating(cartItemId);
        try {
            await removeFromCart(cartItemId);
        } catch (err) {
            console.error('Failed to remove item', err);
            alert('Error al eliminar item');
            refreshCart(); // Rollback
        } finally {
            setUpdating(null);
            setOptimisticItems(null);
        }
    };

    const navigate = useNavigate();

    const handleCheckout = () => {
        onClose();
        navigate('/checkout');
    };

    const subtotal = Array.isArray(displayItems)
        ? displayItems.reduce((acc, item) => acc + (item.products?.price || item.price || 0) * item.quantity, 0)
        : 0;

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-[150] overflow-hidden">
            <div className="absolute inset-0 bg-black/60 backdrop-blur-sm transition-opacity" onClick={onClose} />

            <div
                data-testid="cart-drawer"
                className="absolute inset-y-0 right-0 max-w-full flex"
            >
                <div className="w-screen max-w-md flex flex-col bg-[#0a0a0a] border-l border-white/10 shadow-2xl animate-in slide-in-from-right duration-300">

                    {/* Header */}
                    <div className="px-6 py-6 border-b border-white/5 flex items-center justify-between bg-neutral-900/20">
                        <div className="flex items-center gap-3">
                            <div className="p-2 bg-geeko-cyan/10 rounded-lg">
                                <ShoppingCart size={20} className="text-geeko-cyan" />
                            </div>
                            <h2 className="text-lg font-black tracking-tight uppercase">Tu Carrito</h2>
                        </div>
                        <button onClick={onClose} className="p-2 hover:bg-white/10 rounded-full transition-colors text-text-low">
                            <X size={20} />
                        </button>
                    </div>

                    {/* Items List */}
                    <div className="flex-1 overflow-y-auto px-6 py-8 space-y-6 custom-scrollbar">
                        {isLoading && displayItems.length === 0 ? (
                            <div className="flex flex-col items-center justify-center h-full gap-4">
                                <Loader2 size={32} className="text-geeko-cyan animate-spin" />
                                <span className="text-xs font-bold text-text-low uppercase tracking-widest">Cargando Carrito...</span>
                            </div>
                        ) : displayItems.length === 0 ? (
                            <div className="flex flex-col items-center justify-center h-full text-center space-y-6 opacity-50">
                                <div className="w-20 h-20 bg-neutral-900 rounded-full flex items-center justify-center">
                                    <ShoppingCart size={32} />
                                </div>
                                <div>
                                    <p className="text-sm font-bold text-white mb-1">Tu carrito est├í vac├¡o</p>
                                    <p className="text-xs text-text-low">Agrega algunos productos del Cat├ílogo.</p>
                                </div>
                            </div>
                        ) : (
                            displayItems.map((item) => (
                                <div key={item.id} data-testid="cart-item" className="flex gap-4 p-4 rounded-2xl bg-white/5 border border-white/5 hover:border-white/10 transition-all group">
                                    <div className="w-20 h-28 bg-neutral-900 rounded-lg overflow-hidden flex-shrink-0 border border-white/10">
                                        <img src={item.image_url || item.products?.image_url} alt={item.name || item.products?.name} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500" />
                                    </div>
                                    <div className="flex-1 flex flex-col justify-between py-1">
                                        <div>
                                            <h4 className="text-sm font-bold text-white leading-tight mb-1">{item.name || item.products?.name}</h4>
                                            <p className="text-[10px] font-black uppercase text-text-low">{item.set_code || item.products?.set_code}</p>

                                            {/* Finish & stock badges */}
                                            <div className="flex flex-wrap gap-1 mt-1">
                                                {(item.is_foil || (item.products?.finish || '').toLowerCase() === 'foil') && (
                                                    <span className="inline-block px-2 py-0.5 rounded-full text-[8px] font-black uppercase tracking-widest bg-gradient-to-r from-pink-500 via-purple-500 to-cyan-500 text-white">
                                                        Γ£ª Foil
                                                    </span>
                                                )}
                                                {((item.stock ?? item.products?.stock ?? 1) === 0) && (
                                                    <span className="inline-block px-2 py-0.5 rounded-full text-[8px] font-black uppercase tracking-widest bg-amber-500/20 border border-amber-500/40 text-amber-400">
                                                        Por Encargo
                                                    </span>
                                                )}
                                                {((item.discount_percentage || item.products?.discount_percentage || 0) > 0) && (
                                                    <span className="inline-block px-2 py-0.5 rounded-full text-[8px] font-black uppercase tracking-widest bg-red-500/20 border border-red-500/40 text-red-400">
                                                        -{item.discount_percentage || item.products?.discount_percentage}% OFF
                                                    </span>
                                                )}
                                            </div>
                                        </div>
                                        <div className="flex items-center justify-between">
                                            <div className="flex flex-col">
                                                <span className="text-sm font-mono font-black text-geeko-cyan">{formatPrice(item.price || item.products?.price)}</span>
                                                {((item.original_price || item.products?.original_price || 0) > (item.price || item.products?.price || 0)) && (
                                                    <span className="text-[10px] text-text-low line-through decoration-red-500/50">
                                                        {formatPrice(item.original_price || item.products?.original_price)}
                                                    </span>
                                                )}
                                            </div>

                                            {/* Quantity Controls */}
                                            <div className="flex items-center gap-2">
                                                <button
                                                    onClick={() => handleUpdateQuantity(item.id, item.quantity - 1)}
                                                    data-testid="decrease-quantity-button"
                                                    className="w-7 h-7 bg-black/40 hover:bg-red-500/20 border border-white/5 
                                                               hover:border-red-500/50 rounded-lg flex items-center justify-center 
                                                               transition-all group/btn disabled:opacity-50 disabled:cursor-not-allowed"
                                                    disabled={item.quantity <= 1 || updating === item.id}
                                                >
                                                    {updating === item.id ? (
                                                        <Loader2 size={14} className="text-text-low animate-spin" />
                                                    ) : (
                                                        <Minus size={14} className="text-text-low group-hover/btn:text-red-500" />
                                                    )}
                                                </button>

                                                <span className="text-xs font-bold min-w-[2rem] text-center">
                                                    x{item.quantity}
                                                </span>

                                                <button
                                                    onClick={() => handleUpdateQuantity(item.id, item.quantity + 1)}
                                                    data-testid="increase-quantity-button"
                                                    title={item.quantity >= (item.stock ?? item.products?.stock ?? 99) ? "Stock m├íximo alcanzado" : undefined}
                                                    className={`w-7 h-7 bg-black/40 border border-white/5 rounded-lg flex items-center justify-center transition-all group/btn ${item.quantity >= (item.stock ?? item.products?.stock ?? 99)
                                                        ? 'opacity-50 cursor-not-allowed'
                                                        : 'hover:bg-geeko-cyan/20 hover:border-geeko-cyan/50'
                                                        }`}
                                                    disabled={updating === item.id || item.quantity >= (item.stock ?? item.products?.stock ?? 99)}
                                                >
                                                    {updating === item.id ? (
                                                        <Loader2 size={14} className="text-text-low animate-spin" />
                                                    ) : (
                                                        <Plus size={14} className="text-text-low group-hover/btn:text-geeko-cyan" />
                                                    )}
                                                </button>

                                                <button
                                                    onClick={() => handleRemoveItem(item.id)}
                                                    data-testid="remove-item-button"
                                                    className="w-7 h-7 bg-black/40 hover:bg-red-500/20 border border-white/5 
                                                               hover:border-red-500/50 rounded-lg flex items-center justify-center 
                                                               transition-all group/btn ml-2 disabled:opacity-50 disabled:cursor-not-allowed"
                                                    disabled={updating === item.id}
                                                >
                                                    {updating === item.id ? (
                                                        <Loader2 size={14} className="text-text-low animate-spin" />
                                                    ) : (
                                                        <Trash2 size={14} className="text-text-low group-hover/btn:text-red-500" />
                                                    )}
                                                </button>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            ))
                        )}
                    </div>

                    {/* Footer / Summary */}
                    {displayItems.length > 0 && (
                        <div className="p-8 bg-[#080808] border-t border-white/10 space-y-6">
                            <div className="space-y-3">
                                <div className="flex justify-between text-xs font-bold text-text-low uppercase tracking-widest">
                                    <span>Subtotal</span>
                                    <span>{formatPrice(subtotal)}</span>
                                </div>
                                <div className="flex justify-between text-xs font-bold text-text-low uppercase tracking-widest">
                                    <span>Env├¡o</span>
                                    <span className="text-geeko-cyan">Gratis</span>
                                </div>
                                <div className="h-px bg-white/5 my-4" />
                                <div className="flex justify-between items-end">
                                    <span className="text-sm font-black uppercase tracking-widest">Total</span>
                                    <span className="text-3xl font-black text-white font-mono leading-none">{formatPrice(subtotal)}</span>
                                </div>
                            </div>

                            <button
                                onClick={handleCheckout}
                                data-testid="checkout-button"
                                className="w-full h-14 bg-geeko-cyan hover:bg-cyan-400 text-black font-black uppercase tracking-widest text-xs rounded-2xl flex items-center justify-center gap-3 shadow-[0_0_30px_rgba(0, 209, 255, 0.2)] hover:shadow-[0_0_50px_rgba(0, 209, 255, 0.4)] transition-all transform active:scale-[0.98]"
                            >
                                <CreditCard size={18} />
                                Finalizar Compra
                            </button>

                            <p className="text-[10px] text-center text-text-low font-medium">
                                Pago seguro procesado por Geekorium Engine.
                            </p>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

import { useState, useEffect } from 'react';
import { Link, useSearchParams, useNavigate, useLocation } from 'react-router-dom';
import { ShoppingCart, Search } from 'lucide-react';
import { SearchBar } from '../SearchBar/SearchBar';
import { UserMenu } from './UserMenu';
import { useAuth } from '../../context/AuthContext';
import { ThemeToggle } from '../ThemeToggle/ThemeToggle';

interface HeaderProps {
    onCartOpen: () => void;
    cartCount: number;
}

export const Header = ({ onCartOpen, cartCount }: HeaderProps) => {
    const { user: _user, openAuthModal } = useAuth();
    const [searchParams, setSearchParams] = useSearchParams();
    const [query, setQuery] = useState(searchParams.get('q') || '');
    const navigate = useNavigate();
    const location = useLocation();



    const tcgGames = [
        { name: 'Magic', code: 'MTG', icon: '/logos/tcg/MTG.png' },
        { name: 'Pok├⌐mon', code: 'PKM', icon: '/logos/tcg/PKM.png' },
        { name: 'Yu-Gi-Oh!', code: 'YGO', icon: '/logos/tcg/YGO.png' },
        { name: 'Riftbound', code: 'RFB', icon: '/logos/tcg/RFB.png' },
        { name: 'One Piece', code: 'OPC', icon: '/logos/tcg/OPC.png' },
        { name: 'Digimon', code: 'DGM', icon: '/logos/tcg/DGM.png' },
        { name: 'Gundam', code: 'GND', icon: '/logos/tcg/GND.png' },
        { name: 'Flesh and Blood', code: 'FAB', icon: '/logos/tcg/FAB.png' },
        { name: 'Otros', code: 'OTHERS', icon: '/logos/tcg/OTHERS.png' }
    ];

    useEffect(() => {
        const q = searchParams.get('q') || '';
        if (q !== query) setQuery(q);
    }, [searchParams]);

    const handleSearch = (val: string) => {
        setQuery(val);
        const newParams = new URLSearchParams(searchParams);
        if (val) newParams.set('q', val);
        else newParams.delete('q');
        setSearchParams(newParams);
    };

    const navigateToGame = (gameCode: string) => {
        if (location.pathname === '/rankings') {
            navigate(`/rankings?game=${gameCode}`);
        } else {
            const tab = (gameCode === 'MTG' || gameCode === 'GND') ? 'marketplace' : 'catalog';
            navigate(`/?game=${gameCode}&tab=${tab}`);
        }
    };

    return (
        <header className="sticky top-0 z-50 w-full bg-white/95 dark:bg-[#0a0a0a]/95 backdrop-blur-xl border-b border-neutral-200 dark:border-white/5 shadow-2xl">
            {/* Top Bar: Logo & Search & User */}
            <div className="max-w-[1600px] mx-auto px-4 h-14 lg:h-[60px] flex items-center justify-between gap-12">
                <Link to="/" className="flex-shrink-0 group relative">
                    <img src="/branding/Logo.png" alt="Geekorium" className="hidden dark:block w-28 sm:w-40 object-contain group-hover:scale-105 transition-transform" />
                    <img src="/branding/Logo-Light.png" alt="Geekorium" className="block dark:hidden w-28 sm:w-40 object-contain group-hover:scale-105 transition-transform" />
                    <span className="absolute -top-1 -right-4 bg-red-600 text-white text-[8px] font-black px-1.5 py-0.5 rounded-md rotate-12 shadow-lg">BETA</span>
                </Link>

                {/* Main Utility Nav - Always show on PC */}
                <nav className="hidden lg:flex items-center gap-8 xl:gap-14">
                    {[
                        { name: 'Home', path: '/' },
                        { name: 'Artilugios', path: '/?tab=catalog' },
                        { name: 'Hechizos', path: '/?tab=marketplace&game=MTG&category=Singles' },
                        { name: 'Misiones', path: '/tournaments' },
                        { name: 'Rankings', path: '/rankings' },
                        { name: 'Inv├│canos', path: '/help' }
                    ].map((item) => (
                        <Link 
                            key={item.name}
                            to={item.path}
                            className="text-sm xl:text-base font-bold text-neutral-600 dark:text-text-low hover:text-black dark:hover:text-text-high transition-all relative group py-2"
                        >
                            {item.name}
                            {item.name === 'Home' && !searchParams.get('tab') && (
                                <div className="absolute bottom-0 left-0 w-1/2 h-0.5 bg-black dark:bg-white rounded-full" />
                            )}
                            <div className="absolute bottom-0 left-0 w-0 group-hover:w-full h-0.5 bg-black dark:bg-white transition-all duration-300 rounded-full" />
                        </Link>
                    ))}
                </nav>

                {/* Search & Cart & Auth */}
                <div className="flex-1 max-w-2xl hidden lg:block mx-auto transition-all duration-500">
                    <div className="relative group">
                        <Search size={14} className="absolute left-4 top-1/2 -translate-y-1/2 text-neutral-500 dark:text-text-low group-focus-within:text-geeko-cyan transition-colors" />
                        <input 
                            type="text"
                            value={query}
                            onChange={(e) => handleSearch(e.target.value)}
                            placeholder="Buscar..."
                            className="w-full bg-neutral-100 dark:bg-neutral-900/50 border border-neutral-300 dark:border-white/10 rounded-full py-2.5 pl-10 pr-4 text-[11px] text-black dark:text-white placeholder:text-neutral-500 dark:placeholder:text-neutral-600 focus:outline-none focus:border-geeko-cyan/50 focus:ring-1 focus:ring-geeko-cyan/20 transition-all shadow-inner"
                        />
                    </div>
                </div>

                <div className="flex items-center gap-4 md:gap-6">
                    <div className="flex items-center gap-3">
                        <button onClick={onCartOpen} data-testid="cart-button" className="hidden lg:flex relative p-2 text-neutral-600 dark:text-text-low hover:text-black dark:hover:text-text-high transition-all">
                            <ShoppingCart size={22} />
                            {cartCount > 0 && (
                                <div className="absolute -top-1 -right-1 bg-black dark:bg-white text-white dark:text-black text-[9px] font-black w-4 h-4 rounded-full flex items-center justify-center">
                                    {cartCount}
                                </div>
                            )}
                        </button>
                        <div className="flex items-center">
                            {_user ? (
                                <UserMenu />
                            ) : (
                                <button 
                                    onClick={openAuthModal}
                                    className="px-4 py-2 bg-black dark:bg-white text-white dark:text-black font-black text-[11px] uppercase tracking-widest rounded-xl hover:scale-105 transition-transform"
                                >
                                    Iniciar Sesi├│n
                                </button>
                            )}
                        </div>
                        <ThemeToggle />
                    </div>
                </div>
            </div>

            {/* Navigation Bar: 8 Categories Matrix -> REPLACED WITH CIRCULAR SELECTOR */}
            <nav className="hidden lg:block bg-neutral-100 dark:bg-black/40 border-t border-neutral-200 dark:border-white/5 py-2">
                <div className="max-w-[1600px] mx-auto px-4 flex justify-center items-center gap-8 xl:gap-14 h-20">
                    {tcgGames.map((game) => {
                        const isActive = searchParams.get('game') === game.code;
                        return (
                            <button 
                                key={game.code}
                                onClick={() => navigateToGame(game.code)}
                                className="group flex flex-col items-center gap-2 transition-all duration-300"
                            >
                                <div className={`w-11 h-11 xl:w-14 xl:h-14 rounded-full flex items-center justify-center transition-all ${isActive ? 'bg-black dark:bg-white shadow-[0_0_20px_rgba(0,0,0,0.2)] dark:shadow-[0_0_20px_rgba(255,255,255,0.4)]' : 'bg-white dark:bg-neutral-800/80 hover:bg-neutral-200 dark:hover:bg-neutral-700 shadow-sm dark:shadow-none backdrop-blur-sm'}`}>
                                    <img src={game.icon} alt={game.name} className={`w-6 h-6 xl:w-9 xl:h-9 object-contain transition-all ${isActive ? 'grayscale-0 scale-110' : 'grayscale group-hover:grayscale-0 group-hover:scale-110'}`} />
                                </div>
                                <span className={`text-[11px] xl:text-[14px] font-black italic uppercase tracking-tighter transition-all ${isActive ? 'text-black dark:text-text-high' : 'text-neutral-500 dark:text-text-low group-hover:text-black dark:group-hover:text-neutral-300'}`}>
                                    {game.code === 'MTG' ? 'MTG' : game.name}
                                </span>
                            </button>
                        );
                    })}

                    {/* Integrated Productos Category - REMOVED AS PER REQUEST */}

                </div>
            </nav>

            {/* Mobile Search - shown only on small screens */}
            <div className="lg:hidden p-4 border-t border-white/5">
                <SearchBar value={query} onChange={handleSearch} placeholder="Buscar..." />
            </div>
        </header>
    );
};

import React, { useState, useEffect } from 'react';
