import React from 'react';
// @ts-expect-error - plugin-pwa type definitions might not be instantly available
import { useRegisterSW } from 'virtual:pwa-register/react';
import { RefreshCw, X } from 'lucide-react';

export const PwaReloadPrompt: React.FC = () => {
  const {
    needRefresh: [needRefresh, setNeedRefresh],
    updateServiceWorker,
  } = useRegisterSW({
    onRegistered(r: any) {
      // eslint-disable-next-line prefer-template
      console.log('SW Registered: ' + r)
    },
    onRegisterError(error: any) {
      console.log('SW registration error', error)
    },
  });

  const [isUpdating, setIsUpdating] = React.useState(false);

  if (!needRefresh) return null;

  const handleUpdate = async () => {
    setIsUpdating(true);
    try {
      await updateServiceWorker(true);
      // Fallback for iOS/Safari where controllerchange might not fire reliably
      setTimeout(() => {
        window.location.reload();
      }, 1500);
    } catch (err) {
      console.error('Error actualizando SW:', err);
      setIsUpdating(false);
      window.location.reload();
    }
  };

  return (
    <div className="fixed bottom-4 left-4 right-4 md:left-auto md:right-4 md:w-96 z-[9999] bg-neutral-900 border border-geeko-cyan/30 rounded-2xl p-4 shadow-[0_0_30px_rgba(0,209,255,0.2)] animate-in slide-in-from-bottom-5">
      <div className="flex items-start justify-between gap-4">
        <div className="flex-1">
          <h3 className="text-white font-bold mb-1 flex items-center gap-2">
            <RefreshCw size={16} className={`text-geeko-cyan ${isUpdating ? 'animate-spin' : 'animate-spin-slow'}`} />
            Actualizaci├│n Disponible
          </h3>
          <p className="text-neutral-400 text-sm mb-4">
            Hay una nueva versi├│n de la aplicaci├│n con mejoras y correcciones.
          </p>
          <div className="flex gap-2">
            <button
              onClick={handleUpdate}
              disabled={isUpdating}
              className="flex-1 bg-geeko-cyan text-black font-bold py-2 px-4 rounded-xl text-sm hover:bg-cyan-400 transition-colors disabled:opacity-50"
            >
              {isUpdating ? 'Actualizando...' : 'Actualizar Ahora'}
            </button>
            <button
              onClick={() => setNeedRefresh(false)}
              disabled={isUpdating}
              className="px-4 py-2 bg-white/5 text-white font-bold rounded-xl text-sm hover:bg-white/10 transition-colors disabled:opacity-50"
            >
              Cerrar
            </button>
          </div>
        </div>
        <button
          onClick={() => setNeedRefresh(false)}
          className="text-neutral-500 hover:text-white transition-colors p-1"
        >
          <X size={16} />
        </button>
      </div>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { fetchUserAddresses, saveUserAddress, updateUserAddress, deleteUserAddress } from '../../utils/api';
import { MapPin, Plus, Trash2, Edit2, Check, Star, AlertCircle, Loader2, Home, Briefcase, X } from 'lucide-react';

interface Address {
    id: string;
    name: string;
    full_name: string;
    phone: string;
    address_line1: string;
    address_line2?: string;
    city: string;
    state: string;
    zip_code?: string;
    country: string;
    is_default: boolean;
    is_billing: boolean;
}

export const AddressBook: React.FC = () => {
    const [addresses, setAddresses] = useState<Address[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingAddress, setEditingAddress] = useState<Address | null>(null);
    const [saving, setSaving] = useState(false);

    const [form, setForm] = useState({
        name: '',
        full_name: '',
        phone: '',
        address_line1: '',
        address_line2: '',
        city: 'Caracas',
        state: 'Distrito Capital',
        zip_code: '',
        country: 'Venezuela',
        is_default: false,
        is_billing: false,
    });

    const loadAddresses = async () => {
        setLoading(true);
        setError(null);
        try {
            const data = await fetchUserAddresses();
            setAddresses(data);
        } catch (err: any) {
            console.error('Error fetching addresses:', err);
            setError('Error al cargar la libreta de direcciones.');
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        loadAddresses();
    }, []);

    const openAddModal = () => {
        setEditingAddress(null);
        setForm({
            name: '',
            full_name: '',
            phone: '',
            address_line1: '',
            address_line2: '',
            city: 'Caracas',
            state: 'Distrito Capital',
            zip_code: '',
            country: 'Venezuela',
            is_default: addresses.length === 0, // default if first
            is_billing: addresses.length === 0, // default if first
        });
        setIsModalOpen(true);
    };

    const openEditModal = (addr: Address) => {
        setEditingAddress(addr);
        setForm({
            name: addr.name,
            full_name: addr.full_name,
            phone: addr.phone,
            address_line1: addr.address_line1,
            address_line2: addr.address_line2 || '',
            city: addr.city,
            state: addr.state,
            zip_code: addr.zip_code || '',
            country: addr.country,
            is_default: addr.is_default,
            is_billing: addr.is_billing,
        });
        setIsModalOpen(true);
    };

    const handleDelete = async (id: string) => {
        if (!window.confirm('┬┐Est├ís seguro de eliminar esta direcci├│n?')) return;
        try {
            await deleteUserAddress(id);
            loadAddresses();
        } catch (err: any) {
            console.error('Error deleting address:', err);
            alert('Error al eliminar la direcci├│n.');
        }
    };

    const handleSetDefault = async (addr: Address, type: 'shipping' | 'billing') => {
        try {
            const updates = {
                ...addr,
                is_default: type === 'shipping' ? true : addr.is_default,
                is_billing: type === 'billing' ? true : addr.is_billing,
            };
            await updateUserAddress(addr.id, updates);
            loadAddresses();
        } catch (err: any) {
            console.error('Error updating default status:', err);
            alert('Error al actualizar direcci├│n predeterminada.');
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setSaving(true);
        setError(null);
        try {
            if (editingAddress) {
                await updateUserAddress(editingAddress.id, form);
            } else {
                await saveUserAddress(form);
            }
            setIsModalOpen(false);
            loadAddresses();
        } catch (err: any) {
            console.error('Error saving address:', err);
            setError(err.message || 'Error al guardar la direcci├│n.');
        } finally {
            setSaving(false);
        }
    };

    const getAddressIcon = (name: string) => {
        const lower = name.toLowerCase();
        if (lower.includes('casa') || lower.includes('home') || lower.includes('apto') || lower.includes('resid')) return <Home size={18} />;
        if (lower.includes('trabajo') || lower.includes('oficina') || lower.includes('work') || lower.includes('tienda')) return <Briefcase size={18} />;
        return <MapPin size={18} />;
    };

    if (loading && addresses.length === 0) {
        return (
            <div className="p-8 text-center bg-white/5 rounded-3xl border border-white/5 backdrop-blur-sm">
