                                        addr.is_default
                                            ? 'bg-geeko-cyan/10 border-geeko-cyan/30 text-geeko-cyan'
                                            : 'bg-white/5 border-white/5 text-slate-400 hover:bg-white/10'
                                    }`}
                                >
                                    <Star size={10} fill={addr.is_default ? 'currentColor' : 'none'} />
