import React, { useState, useEffect } from 'react';
import { supabase } from '../../utils/supabaseClient';
import { useAuth } from '../../context/AuthContext';
import { Clock, TrendingUp, TrendingDown, Coins } from 'lucide-react';

export const CreditHistoryList: React.FC = () => {
    const { user } = useAuth();
    const [history, setHistory] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchHistory = async () => {
            if (!user) return;
            setLoading(true);
            const { data, error } = await supabase
                .from('credit_history')
                .select('*')
                .eq('user_id', user.id)
                .order('created_at', { ascending: false });
            
            if (!error && data) {
                setHistory(data);
            }
            setLoading(false);
        };

        fetchHistory();
    }, [user]);

    if (loading) {
        return <div className="text-center py-8 text-slate-500 animate-pulse font-bold uppercase tracking-widest text-xs">Cargando Historial...</div>;
    }

    if (history.length === 0) {
        return (
            <div className="bg-white/5 border border-white/10 rounded-2xl p-8 text-center flex flex-col items-center justify-center gap-3">
                <Coins size={32} className="text-slate-700" />
                <p className="text-slate-400 font-bold italic">No tienes movimientos de cr├⌐ditos registrados.</p>
            </div>
        );
    }

    return (
        <div className="space-y-3">
            {history.map((record) => (
                <div key={record.id} className="bg-white/5 border border-white/10 rounded-xl p-4 flex items-center justify-between hover:bg-white/10 transition-colors">
                    <div className="flex items-center gap-4">
                        <div className={`p-2 rounded-lg ${record.amount > 0 ? 'bg-geeko-cyan/20 text-geeko-cyan' : 'bg-red-500/20 text-red-500'}`}>
                            {record.amount > 0 ? <TrendingUp size={20} /> : <TrendingDown size={20} />}
                        </div>
                        <div>
                            <p className="text-white font-bold text-sm">{record.reason}</p>
                            <div className="flex items-center gap-1 text-slate-500 text-xs mt-1">
                                <Clock size={12} />
                                <span>{new Date(record.created_at).toLocaleString()}</span>
                            </div>
                        </div>
                    </div>
                    <div className={`font-black text-lg ${record.amount > 0 ? 'text-geeko-cyan' : 'text-red-500'}`}>
                        {record.amount > 0 ? '+' : ''}{record.amount} CG
                    </div>
                </div>
            ))}
        </div>
    );
};

import { useState, useEffect } from 'react';
import { TrendingUp, TrendingDown, Clock, Loader2, DollarSign } from 'lucide-react';
import { useAuth } from '../../context/AuthContext';
import { supabase } from '../../utils/supabaseClient';

interface Movement {
    printing_id: string;
    condition_id: number;
    card_name: string;
    set_code: string;
    previous_price: number;
    current_price: number;
    price_delta: number;
    last_updated: string;
    quantity: number;
}

export const InventoryMovements = () => {
    const { session } = useAuth();
    const [movements, setMovements] = useState<Movement[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        if (session?.user?.id) {
            fetchMovements();
        }
    }, [session?.user?.id]);

    const fetchMovements = async () => {
        setLoading(true);
        setError(null);
        try {
            const { data, error } = await supabase.rpc('get_inventory_movements', {
                p_user_id: session?.user?.id
            });

            if (error) throw error;
            setMovements(data || []);
        } catch (err: any) {
            console.error("Error fetching inventory movements:", err);
            setError(err.message || 'Error cargando movimientos');
        } finally {
            setLoading(false);
        }
    };

    if (loading) {
        return (
            <div className="flex flex-col items-center justify-center p-12 text-slate-400">
                <Loader2 className="w-8 h-8 animate-spin mb-4 text-[#00D1FF]" />
                <p className="text-sm font-medium uppercase tracking-widest">Calculando Variaciones...</p>
            </div>
        );
    }

    if (error) {
        return (
            <div className="p-6 bg-red-500/10 border border-red-500/20 rounded-xl text-center">
                <p className="text-red-400 font-bold mb-2">Error de conexi├│n</p>
                <p className="text-sm text-red-400/80">{error}</p>
                <button 
                    onClick={fetchMovements}
                    className="mt-4 px-4 py-2 bg-red-500/20 hover:bg-red-500/30 text-red-300 rounded-lg transition-colors text-xs font-bold uppercase tracking-widest"
                >
                    Reintentar
                </button>
            </div>
        );
    }

    if (movements.length === 0) {
        return (
            <div className="flex flex-col items-center justify-center p-12 text-slate-500 bg-slate-800/30 rounded-xl border border-white/5">
                <Clock className="w-12 h-12 mb-4 opacity-50" />
                <p className="text-lg font-bold">Sin Movimientos Recientes</p>
                <p className="text-sm mt-2 text-center max-w-md">
                    Los precios de las cartas en tu inventario no han registrado variaciones significativas en las ├║ltimas 24 horas.
                </p>
            </div>
        );
    }

    const totalPortfolioChange = movements.reduce((acc, curr) => acc + (curr.price_delta * curr.quantity), 0);
    const isPositive = totalPortfolioChange >= 0;

    return (
        <div className="space-y-6">
            <div className="flex items-center justify-between p-6 bg-slate-800/50 rounded-2xl border border-white/5">
                <div>
                    <h3 className="text-lg font-black text-white uppercase tracking-tighter">Fluctuaci├│n Diaria</h3>
                    <p className="text-xs text-slate-400 mt-1">Suma del cambio de valor de todas las cartas afectadas</p>
                </div>
                <div className={`flex items-center gap-3 px-6 py-3 rounded-xl border ${
                    isPositive 
                        ? 'bg-emerald-500/10 border-emerald-500/30 text-emerald-400' 
                        : 'bg-red-500/10 border-red-500/30 text-red-400'
                }`}>
                    {isPositive ? <TrendingUp className="w-6 h-6" /> : <TrendingDown className="w-6 h-6" />}
                    <span className="text-2xl font-black tracking-tighter">
                        {isPositive ? '+' : ''}{totalPortfolioChange.toFixed(2)} USD
                    </span>
                </div>
            </div>

            <div className="bg-slate-900/50 rounded-2xl border border-white/5 overflow-hidden">
                <table className="w-full text-left border-collapse">
                    <thead>
                        <tr className="bg-slate-800/50 text-[10px] uppercase tracking-widest text-slate-400 border-b border-white/5">
                            <th className="p-4 font-bold">Carta</th>
                            <th className="p-4 font-bold text-center">Set</th>
                            <th className="p-4 font-bold text-center">Cant.</th>
                            <th className="p-4 font-bold text-right">Ayer</th>
                            <th className="p-4 font-bold text-right">Hoy</th>
                            <th className="p-4 font-bold text-right">Variaci├│n</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-white/5">
                        {movements.map((mov, idx) => {
                            const isUp = mov.price_delta > 0;
                            return (
                                <tr key={`${mov.printing_id}-${mov.condition_id}-${idx}`} className="hover:bg-white/[0.02] transition-colors">
                                    <td className="p-4">
                                        <p className="font-bold text-white text-sm">{mov.card_name}</p>
                                        <p className="text-xs text-slate-500 mt-0.5">ID: {mov.printing_id.split('-')[0]}</p>
                                    </td>
                                    <td className="p-4 text-center">
                                        <span className="px-2 py-1 bg-white/5 rounded-md text-xs font-mono text-slate-300 uppercase">
                                            {mov.set_code}
                                        </span>
                                    </td>
                                    <td className="p-4 text-center text-sm font-bold text-slate-300">
                                        x{mov.quantity}
                                    </td>
                                    <td className="p-4 text-right">
                                        <div className="flex items-center justify-end gap-1 text-sm text-slate-400">
                                            <DollarSign className="w-3 h-3" />
                                            {mov.previous_price.toFixed(2)}
                                        </div>
                                    </td>
                                    <td className="p-4 text-right">
                                        <div className="flex items-center justify-end gap-1 text-sm font-bold text-white">
                                            <DollarSign className="w-3 h-3" />
                                            {mov.current_price.toFixed(2)}
                                        </div>
                                    </td>
                                    <td className="p-4 text-right">
                                        <div className={`inline-flex items-center justify-end gap-1 px-2.5 py-1 rounded text-xs font-bold ${
                                            isUp ? 'bg-emerald-500/20 text-emerald-400' : 'bg-red-500/20 text-red-400'
                                        }`}>
                                            {isUp ? <TrendingUp className="w-3 h-3" /> : <TrendingDown className="w-3 h-3" />}
                                            {isUp ? '+' : ''}{mov.price_delta.toFixed(2)}
                                        </div>
                                    </td>
                                </tr>
                            );
                        })}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

import React, { useEffect, useState } from 'react';
import { useAuth } from '../../context/AuthContext';
import { fetchUserMissions } from '../../utils/api';
import { Loader2, Calendar, Tag } from 'lucide-react';

export const MyMissionsList: React.FC = () => {
    const { user } = useAuth();
    const [missions, setMissions] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const loadMissions = async () => {
            if (!user) return;
            try {
                const data = await fetchUserMissions(user.id, user.email);
                setMissions(data);
            } catch (error) {
                console.error("Failed to load missions:", error);
            } finally {
                setLoading(false);
            }
        };
        loadMissions();
    }, [user]);

    if (loading) {
        return (
            <div className="flex justify-center items-center py-12">
                <Loader2 className="animate-spin text-geeko-gold" size={32} />
            </div>
        );
    }

    if (missions.length === 0) {
        return (
            <div className="text-center py-12 bg-white/5 border border-white/10 rounded-2xl">
                <p className="text-neutral-400 font-bold uppercase tracking-widest text-sm">A├ÜN NO TE HAS INSCRITO EN NINGUNA MISI├ôN</p>
                <p className="text-neutral-500 text-xs mt-2">Visita la pesta├▒a de Misiones para ver los pr├│ximos eventos y torneos.</p>
            </div>
        );
    }

    return (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {missions.map((reg) => {
                const event = reg.events;
                if (!event) return null;

                const eventDate = new Date(event.event_date);
                const isPast = eventDate < new Date();
                const isCancelled = !event.is_active;
                
                let statusBadge = null;
                if (isCancelled) {
                    statusBadge = <span className="px-2 py-1 bg-red-500/20 text-red-400 border border-red-500/30 rounded text-[10px] font-black uppercase tracking-wider">CANCELADA</span>;
                } else if (isPast) {
                    statusBadge = <span className="px-2 py-1 bg-neutral-500/20 text-neutral-400 border border-neutral-500/30 rounded text-[10px] font-black uppercase tracking-wider">FINALIZADA</span>;
                } else {
                    statusBadge = <span className="px-2 py-1 bg-emerald-500/20 text-emerald-400 border border-emerald-500/30 rounded text-[10px] font-black uppercase tracking-wider">ACTIVA</span>;
                }

                // Temporary logic for payment status (will default to PENDING for most until we use it fully)
                const paymentStatus = reg.payment_status || 'PENDING';
                let paymentBadge = null;
                if (!isPast && !isCancelled) {
                    if (paymentStatus === 'PAID') {
                        paymentBadge = <span className="px-2 py-1 bg-geeko-gold/20 text-geeko-gold border border-geeko-gold/30 rounded text-[10px] font-black uppercase tracking-wider">PAGADO</span>;
                    } else if (paymentStatus === 'PENDING') {
                        paymentBadge = <span className="px-2 py-1 bg-orange-500/20 text-orange-400 border border-orange-500/30 rounded text-[10px] font-black uppercase tracking-wider">POR PAGAR</span>;
                    }
                }

                return (
                    <div key={reg.id} className={`bg-[#0a0a0a] border ${isPast ? 'border-white/5 opacity-70' : 'border-white/10'} rounded-2xl overflow-hidden hover:border-white/20 transition-all flex flex-col`}>
                        {event.image_url ? (
                            <div className="w-full h-32 overflow-hidden relative">
                                <img src={event.image_url} alt={event.name} className="w-full h-full object-cover opacity-80 hover:opacity-100 transition-opacity" />
                                <div className="absolute inset-0 bg-gradient-to-t from-[#0a0a0a] to-transparent"></div>
                                <div className="absolute bottom-3 left-4 flex gap-2">
                                    {statusBadge}
                                </div>
                            </div>
                        ) : (
                            <div className="w-full h-20 bg-neutral-900 relative">
                                <div className="absolute bottom-3 left-4 flex gap-2">
                                    {statusBadge}
                                </div>
                            </div>
                        )}
                        
                        <div className="p-5 flex-1 flex flex-col">
                            <h3 className="text-xl font-black italic uppercase tracking-tighter text-white mb-2 line-clamp-2">{event.name}</h3>
                            
                            <div className="space-y-2 mt-auto">
                                <div className="flex items-center gap-2 text-neutral-400 text-xs font-medium">
                                    <Calendar size={14} className="text-geeko-gold" />
                                    <span>{eventDate.toLocaleDateString('es-ES', { day: 'numeric', month: 'long', year: 'numeric' })}</span>
                                </div>
                                
                                {event.format && (
                                    <div className="flex items-center gap-2 text-neutral-400 text-xs font-medium">
                                        <Tag size={14} className="text-geeko-cyan" />
                                        <span>Formato: {event.format}</span>
                                    </div>
                                )}

                                <div className="flex items-center justify-between pt-4 mt-4 border-t border-white/5">
                                    <div className="text-xs font-black uppercase tracking-widest text-neutral-500">
                                        Entrada: <span className="text-white">{event.entry_fee || 'Gratis'}</span>
                                    </div>
                                    {paymentBadge}
                                </div>
                            </div>
                        </div>
                    </div>
                );
            })}
        </div>
    );
};

import React, { useEffect, useState } from 'react';
import { supabase } from '../../utils/supabaseClient';
import { useAuth } from '../../context/AuthContext';
import { Package, ChevronRight, Clock, CheckCircle, Truck, AlertCircle, Loader2, Calendar } from 'lucide-react';
import { Link } from 'react-router-dom';

interface OrderItem {
    product_id: string | null;
    accessory_id: string | null;
    product_name: string;
    products?: { release_date: string | null } | null;
    accessories?: { release_date: string | null } | null;
}

interface Order {
    id: string;
    status: string;
    total_amount: number;
    created_at: string;
    order_items: OrderItem[];
}

const ORDER_STATUS_CONFIG: Record<string, { label: string; icon: any; color: string; bg: string }> = {
    pending_payment: { label: 'Pendiente de Pago', icon: Clock, color: 'text-orange-400', bg: 'bg-orange-400/10' },
    payment_uploaded: { label: 'Pago en Revisi├│n', icon: Clock, color: 'text-yellow-400', bg: 'bg-yellow-400/10' },
    paid: { label: 'Pagado', icon: CheckCircle, color: 'text-green-400', bg: 'bg-green-400/10' },
    processing: { label: 'Procesando', icon: Package, color: 'text-blue-400', bg: 'bg-blue-400/10' },
    ready_for_pickup: { label: 'Listo para Pick Up', icon: CheckCircle, color: 'text-white', bg: 'bg-cyan-400/10' },
    shipped: { label: 'Enviado', icon: Truck, color: 'text-purple-400', bg: 'bg-purple-400/10' },
    delivered: { label: 'Entregado', icon: CheckCircle, color: 'text-gray-400', bg: 'bg-gray-400/10' },
    cancelled: { label: 'Cancelado', icon: AlertCircle, color: 'text-red-400', bg: 'bg-red-400/10' },
};

const OrdersList: React.FC = () => {
    const { user } = useAuth();
    const [orders, setOrders] = useState<Order[]>([]);
    const [loading, setLoading] = useState(true);
    const [activeTab, setActiveTab] = useState<'all' | 'singles' | 'sealed' | 'presales'>('all');

    useEffect(() => {
        const fetchOrders = async () => {
            if (!user) return;
            
            setLoading(true);
            try {
                const { data, error } = await supabase
                    .from('orders')
                    .select(`
                        id, 
                        status, 
                        total_amount, 
                        created_at,
                        order_items(
                            product_id,
                            accessory_id,
                            product_name,
                            products(release_date),
                            accessories(release_date)
                        )
                    `)
                    .eq('user_id', user.id)
                    .order('created_at', { ascending: false });

                if (error) throw error;
                setOrders((data as any) || []);
            } catch (error) {
                console.error('Error fetching user orders:', error);
            } finally {
                setLoading(false);
            }
        };

        fetchOrders();
    }, [user]);

    const isPreventa = (item: OrderItem) => {
        const name = item.product_name || '';
        return (
            name.toLowerCase().includes('(preventa)') || 
            name.toLowerCase().includes('preventa') ||
            !!item.products?.release_date ||
            !!item.accessories?.release_date
        );
    };

    const isSingle = (item: OrderItem) => {
        return !!item.product_id && !isPreventa(item);
    };

    const isAccessoryOrSealed = (item: OrderItem) => {
        return !!item.accessory_id && !isPreventa(item);
    };

    const getOrderReleaseDate = (order: Order) => {
        const dates = order.order_items
            .map(item => item.products?.release_date || item.accessories?.release_date)
            .filter(Boolean) as string[];
        
        if (dates.length === 0) return null;
        
        // Find furthest release date
        const maxDate = new Date(Math.max(...dates.map(d => new Date(d).getTime())));
        return maxDate.toLocaleDateString('es-ES', { 
            day: 'numeric', 
            month: 'long', 
            year: 'numeric' 
        });
    };

    const filteredOrders = orders.filter(order => {
        const items = order.order_items || [];
        if (activeTab === 'all') return true;
        if (activeTab === 'singles') return items.some(isSingle);
        if (activeTab === 'sealed') return items.some(isAccessoryOrSealed);
        if (activeTab === 'presales') return items.some(isPreventa);
        return true;
    });

    if (loading) {
        return (
            <div className="p-12 text-center bg-white/5 rounded-3xl border border-white/5 backdrop-blur-sm">
                <Loader2 className="w-8 h-8 text-geeko-gold animate-spin mx-auto mb-4" />
                <p className="text-slate-400 font-bold uppercase tracking-widest text-[10px]">Consultando terminal central...</p>
            </div>
        );
    }

    if (orders.length === 0) {
        return (
            <div className="p-12 text-center bg-white/5 rounded-3xl border border-dashed border-white/10 backdrop-blur-sm">
                <Package className="w-12 h-12 text-slate-700 mx-auto mb-4" />
                <p className="text-slate-400 font-bold uppercase tracking-widest text-xs mb-2">
                    No tienes pedidos registrados a├║n
                </p>
                <Link to="/" className="text-[10px] text-geeko-gold uppercase font-black tracking-widest hover:opacity-80 transition-opacity underline decoration-geeko-gold/30 underline-offset-4">
                    Explorar el Emporio
                </Link>
            </div>
        );
    }

    return (
        <div className="space-y-6">
            {/* Filter Tabs */}
            <div className="flex flex-wrap gap-2 pb-2 border-b border-white/5">
                {[
                    { id: 'all', label: 'Todos' },
                    { id: 'singles', label: 'Singles (Cartas)' },
                    { id: 'sealed', label: 'Sellado / Accesorios' },
                    { id: 'presales', label: 'Preventas (Pre-orders)' },
                ].map(tab => (
                    <button
                        key={tab.id}
                        onClick={() => setActiveTab(tab.id as any)}
                        className={`px-4 py-2 rounded-xl text-xs font-black uppercase tracking-wider transition-all border ${
                            activeTab === tab.id
                                ? 'bg-geeko-gold/15 border-geeko-gold/40 text-geeko-gold shadow-[0_0_15px_rgba(255,184,0,0.15)]'
                                : 'bg-white/5 border-white/5 text-slate-400 hover:bg-white/10 hover:text-white'
                        }`}
                    >
                        {tab.label}
                    </button>
                ))}
            </div>

            {filteredOrders.length === 0 ? (
                <div className="p-12 text-center bg-white/5 rounded-3xl border border-dashed border-white/10">
                    <Package className="w-10 h-10 text-slate-700 mx-auto mb-3" />
                    <p className="text-slate-400 text-xs font-bold uppercase tracking-widest">
                        Ning├║n pedido coincide con esta categor├¡a
                    </p>
                </div>
            ) : (
                <div className="space-y-4">
                    {filteredOrders.map((order) => {
                        const config = ORDER_STATUS_CONFIG[order.status] || { 
                            label: order.status, 
                            icon: Package, 
                            color: 'text-slate-400', 
                            bg: 'bg-slate-400/10' 
                        };
                        const StatusIcon = config.icon;
                        const isOrderPresale = order.order_items?.some(isPreventa);
                        const estArrival = isOrderPresale ? getOrderReleaseDate(order) : null;

                        return (
                            <Link
                                key={order.id}
                                to={`/order/${order.id}`}
                                className="group block p-6 bg-neutral-900/40 border border-white/5 rounded-[2rem] hover:bg-white/5 transition-all hover:border-white/10 relative overflow-hidden"
                            >
                                <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 relative z-10">
                                    <div className="flex items-center gap-5">
                                        <div className={`w-14 h-14 rounded-2xl ${config.bg} flex items-center justify-center border border-white/5 group-hover:scale-110 transition-transform`}>
                                            <StatusIcon className={config.color} size={24} />
                                        </div>
                                        <div>
                                            <div className="flex items-center gap-3 mb-1">
                                                <h3 className="text-sm font-black font-mono text-white opacity-80">
                                                    #{order.id.slice(0, 8)}
                                                </h3>
                                                <span className={`px-3 py-0.5 rounded-full text-[9px] font-black uppercase tracking-widest ${config.color} ${config.bg} border border-white/5`}>
                                                    {config.label}
                                                </span>
                                                {isOrderPresale && (
                                                    <span className="px-2.5 py-0.5 rounded-full text-[9px] font-black uppercase tracking-widest bg-orange-500/10 text-orange-400 border border-orange-500/20">
                                                        Preventa
                                                    </span>
                                                )}
                                            </div>
                                            <p className="text-[10px] text-slate-500 font-bold uppercase tracking-[0.2em]">
                                                {new Date(order.created_at).toLocaleDateString('es-ES', { 
                                                    day: 'numeric', 
                                                    month: 'long', 
                                                    year: 'numeric' 
                                                })}
                                            </p>
                                        </div>
                                    </div>

                                    <div className="flex items-center justify-between md:justify-end gap-8">
                                        {estArrival && (
                                            <div className="text-right hidden sm:block bg-orange-500/5 border border-orange-500/15 rounded-xl px-4 py-2">
                                                <p className="text-[8px] uppercase font-black text-orange-400 tracking-widest flex items-center justify-end gap-1 mb-0.5">
                                                    <Calendar size={10} /> Liberaci├│n Estimada
                                                </p>
                                                <p className="text-xs font-black text-white">{estArrival}</p>
                                            </div>
                                        )}
                                        <div className="text-right">
                                            <p className="text-[9px] uppercase font-black text-slate-500 tracking-widest mb-1">Monto Total</p>
                                            <p className="text-xl font-black font-mono text-white italic">
                                                ${Number(order.total_amount).toFixed(2)}
                                            </p>
                                        </div>
                                        <div className="p-3 rounded-full bg-white/5 text-slate-600 group-hover:text-geeko-gold group-hover:bg-geeko-gold/10 transition-all">
                                            <ChevronRight size={20} />
                                        </div>
                                    </div>
                                </div>

                                {estArrival && (
                                    <div className="mt-4 pt-3 border-t border-white/5 flex items-center gap-2 text-[10px] text-orange-400 font-bold uppercase tracking-wider sm:hidden">
                                        <Calendar size={12} />
                                        Llegada estimada: {estArrival}
                                    </div>
                                )}
                                
                                {/* Interactive Background Accent */}
                                <div className={`absolute top-0 right-0 w-32 h-32 opacity-0 group-hover:opacity-10 transition-opacity blur-3xl rounded-full ${config.bg.replace('/10', '/30')}`} />
                            </Link>
                        );
                    })}
                </div>
            )}
            
            <p className="text-[10px] text-center text-geeko-gold uppercase font-black tracking-widest opacity-40 pt-4">
                Los pedidos realizados como invitado se rastrean v├¡a link de WhatsApp enviados a tu correo
            </p>
        </div>
    );
};

export default OrdersList;

import { useEffect, useState } from 'react';
import { supabase } from '../../utils/supabaseClient';
import { History } from 'lucide-react';
import { PlayerHistoryModal } from '../Admin/PlayerHistoryModal';

interface PlayerRankingsListProps {
    userId: string;
    username: string;
}

const calculateRank = (kills: number, faction: string) => {
    const isZeon = faction === 'ZEON';
    const prefix = isZeon ? 'Z' : 'F';
    let baseName = '';
    let displayName = '';
    
    if (kills >= 80) { baseName = 'ALMIRANTE'; displayName = 'Almirante'; }
    else if (kills >= 50) { baseName = 'CONTRALMIRANTE'; displayName = 'Contraalmirante'; }
    else if (kills >= 30) { baseName = 'CAPITAN'; displayName = 'Capit├ín'; }
    else if (kills >= 20) { baseName = 'COMANDANTE'; displayName = 'Comandante'; }
    else if (kills >= 12) { baseName = 'TENIENTE'; displayName = 'Teniente'; }
    else if (kills >= 8) { baseName = 'INSIGNIA'; displayName = 'Insignia'; }
    else if (kills >= 4) { baseName = 'SUBOFICIAL EN JEFE'; displayName = 'Suboficial en Jefe'; }
    else { baseName = 'CABO'; displayName = isZeon ? 'Cadete' : 'Tripulante'; }
    
    return { name: displayName, icon: `/assets/ranks/${prefix} ${baseName}.png` };
};

export const PlayerRankingsList = ({ userId, username }: PlayerRankingsListProps) => {
    const [rankings, setRankings] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [historyPlayer, setHistoryPlayer] = useState<{id: string, name: string} | null>(null);

    useEffect(() => {
        const fetchRankings = async () => {
            if (!userId) return;
            // Fetch rankings matching user_id OR matching username exactly
            const { data } = await supabase
                .from('player_rankings')
                .select(`
                    *,
                    ranking_seasons (
                        title,
                        game_context
                    )
                `)
                .or(`user_id.eq.${userId},name.ilike.${username}`);

            if (data) {
                setRankings(data);
            }
            setLoading(false);
        };

        fetchRankings();
    }, [userId, username]);

    if (loading) {
        return <div className="animate-pulse text-white/50 text-sm font-bold uppercase tracking-widest">Buscando misiones militares...</div>;
    }

    if (rankings.length === 0) {
        return (
            <div className="text-center py-8">
                <p className="text-white/40 text-xs font-bold uppercase tracking-widest">A├║n no tienes rangos militares asignados.</p>
                <p className="text-white/20 text-[10px] mt-2">Dile al administrador que enlace tu usuario en el panel de rankings.</p>
            </div>
        );
    }

    return (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {rankings.map((ranking) => {
                const rank = calculateRank(ranking.confirmed_kills || 0, ranking.faction);
                
                return (
                    <div key={ranking.id} className="bg-gradient-to-br from-[#0A0D18] to-black border border-[#1C233A] rounded-2xl p-4 relative overflow-hidden group hover:border-[#4B6EEB]/50 transition-colors">
                        {/* Glow */}
                        <div className="absolute top-0 right-0 w-32 h-32 bg-[#4B6EEB]/10 rounded-full blur-3xl group-hover:bg-[#4B6EEB]/20 transition-colors" />
                        
                        <div className="absolute top-4 right-4 z-20">
                            <button 
                                onClick={() => setHistoryPlayer({ id: ranking.id, name: `${username} - ${ranking.ranking_seasons?.title}` })}
                                className="w-8 h-8 rounded-full bg-black/50 border border-white/10 flex items-center justify-center text-slate-400 hover:text-[#4B6EEB] hover:border-[#4B6EEB]/50 transition-all hover:scale-110"
                                title="Ver Historial"
                            >
                                <History size={14} />
                            </button>
                        </div>

                        <div className="flex items-center gap-4 relative z-10">
                            {/* Rank Icon */}
                            <div className="w-16 h-16 shrink-0 flex items-center justify-center">
                                <img src={rank.icon} alt={rank.name} className="max-w-full max-h-full object-contain filter drop-shadow-lg group-hover:scale-110 transition-transform" />
                            </div>
                            
                            {/* Info */}
                            <div className="flex-1">
                                <div className="text-[9px] text-[#5A6D93] font-black uppercase tracking-widest mb-1">
                                    {ranking.ranking_seasons?.game_context || 'TCG'} ΓÇó {ranking.ranking_seasons?.title}
                                </div>
                                <h4 className="text-white font-black italic tracking-wider text-lg uppercase">{rank.name}</h4>
                                <div className="text-xs text-white/60 font-bold uppercase tracking-widest mt-1 flex gap-3">
                                    <span>Kills: <span className="text-[#00FF85]">{ranking.confirmed_kills || 0}</span></span>
                                    <span>Conq: <span className="text-white/80">{ranking.conquest_points || 0}</span></span>
                                    <span>Derribo: <span className="text-white/80">{ranking.takedown_points || 0}</span></span>
                                </div>
                            </div>
                        </div>
                    </div>
                );
            })}
            
            {historyPlayer && (
                <PlayerHistoryModal 
                    playerId={historyPlayer.id} 
                    playerName={historyPlayer.name} 
                    onClose={() => setHistoryPlayer(null)} 
                />
            )}
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { X, Save, User, MapPin, Phone, Hash, AlertCircle, Camera, Lock, Key, Mail } from 'lucide-react';
import { uploadUserAvatar, updateUserPassword, sendPasswordResetEmail } from '../../utils/api';
import { supabase } from '../../utils/supabaseClient';
import { useAuth } from '../../context/AuthContext';

interface ProfileSettingsModalProps {
    isOpen: boolean;
    onClose: () => void;
    currentProfile: any;
    onProfileUpdated: () => void;
}

export const ProfileSettingsModal: React.FC<ProfileSettingsModalProps> = ({ isOpen, onClose, currentProfile, onProfileUpdated }) => {
    const { user } = useAuth();
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [success, setSuccess] = useState(false);
    const [avatarFile, setAvatarFile] = useState<File | null>(null);
    const [avatarPreview, setAvatarPreview] = useState<string | null>(null);

    const [formData, setFormData] = useState({
        username: '',
        first_name: '',
        last_name: '',
        cedula: '',
        phone: '',
        address: '',
        wizards_email: '',
        pokemon_id: '',
        bandai_id: ''
    });

    const [password, setPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');
    const [passwordLoading, setPasswordLoading] = useState(false);
    const [passwordSuccess, setPasswordSuccess] = useState(false);
    const [passwordError, setPasswordError] = useState<string | null>(null);

    useEffect(() => {
        if (currentProfile) {
            setFormData({
                username: currentProfile.username || '',
                first_name: currentProfile.first_name || '',
                last_name: currentProfile.last_name || '',
                cedula: currentProfile.cedula || '',
                phone: currentProfile.phone || '',
                address: currentProfile.address || '',
                wizards_email: currentProfile.wizards_email || '',
                pokemon_id: currentProfile.pokemon_id || '',
                bandai_id: currentProfile.bandai_id || ''
            });
            setAvatarPreview(currentProfile.avatar_url || null);
        }
    }, [currentProfile]);

    if (!isOpen || !user) return null;

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
        setError(null);
        setSuccess(false);
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const file = e.target.files[0];
            setAvatarFile(file);
            setAvatarPreview(URL.createObjectURL(file));
            setError(null);
            setSuccess(false);
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);
        setError(null);
        setSuccess(false);

        try {
            let avatarUrl = currentProfile?.avatar_url;
            if (avatarFile) {
                avatarUrl = await uploadUserAvatar(avatarFile, user.id);
            }

            // Nullify empty fields to avoid unique/validation constraint errors
            const dataToUpdate = {
                ...formData,
                avatar_url: avatarUrl,
                username: formData.username.trim() === '' ? null : formData.username.trim(),
                wizards_email: formData.wizards_email.trim() === '' ? null : formData.wizards_email.trim(),
                pokemon_id: formData.pokemon_id.trim() === '' ? null : formData.pokemon_id.trim(),
                bandai_id: formData.bandai_id.trim() === '' ? null : formData.bandai_id.trim()
            };

            const { error: updateError } = await supabase
                .from('profiles')
                .update(dataToUpdate)
                .eq('id', user.id);

            if (updateError) {
                if (updateError.code === '23505' && updateError.message.includes('username')) {
                    throw new Error('El nombre de usuario ya est├í en uso. Por favor elige otro.');
                }
                throw updateError;
            }

            setSuccess(true);
            onProfileUpdated();
            setTimeout(() => {
                onClose();
            }, 1500);

        } catch (err: any) {
            setError(err.message || 'Error al guardar los cambios.');
        } finally {
            setLoading(false);
        }
    };

    const handlePasswordUpdate = async (e: React.MouseEvent) => {
        e.preventDefault();
        if (password.length < 6) {
            setPasswordError('La contrase├▒a debe tener al menos 6 caracteres.');
            return;
        }
        if (password !== confirmPassword) {
            setPasswordError('Las contrase├▒as no coinciden.');
            return;
        }

        setPasswordLoading(true);
        setPasswordError(null);
        setPasswordSuccess(false);

        try {
            await updateUserPassword(password);
            setPasswordSuccess(true);
            setPassword('');
            setConfirmPassword('');
        } catch (err: any) {
            setPasswordError(err.message || 'Error al actualizar contrase├▒a.');
        } finally {
            setPasswordLoading(false);
        }
    };

    const handleSendResetEmail = async (e: React.MouseEvent) => {
        e.preventDefault();
        setPasswordLoading(true);
        setPasswordError(null);
        setPasswordSuccess(false);

        try {
            if (!user.email) throw new Error('No se encontr├│ el correo del usuario.');
            await sendPasswordResetEmail(user.email);
            setPasswordSuccess(true);
        } catch (err: any) {
            setPasswordError(err.message || 'Error al enviar correo de recuperaci├│n.');
        } finally {
            setPasswordLoading(false);
        }
    };

    return (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4">
            <div className="absolute inset-0 bg-black/80 backdrop-blur-sm transition-opacity" onClick={onClose} />
            
            <div className="relative bg-[#0a0a0a] border border-white/10 w-full max-w-2xl rounded-3xl shadow-[0_0_50px_rgba(0,0,0,0.8)] overflow-hidden flex flex-col max-h-[90vh] animate-in fade-in zoom-in-95 duration-200">
                {/* Header */}
                <div className="px-6 py-4 border-b border-white/5 flex items-center justify-between sticky top-0 bg-[#0a0a0a] z-10">
                    <h2 className="text-xl font-black italic uppercase tracking-tighter text-white flex items-center gap-2">
                        Ajustes de <span className="text-geeko-cyan">Perfil</span>
                    </h2>
                    <button onClick={onClose} className="p-2 hover:bg-white/10 rounded-full transition-colors text-text-low hover:text-white">
                        <X size={20} />
                    </button>
                </div>

                {/* Form Content */}
                <div className="overflow-y-auto p-6 custom-scrollbar">
                    <form id="profile-form" onSubmit={handleSubmit} className="space-y-6">
                        
                        {/* Status Messages */}
                        {error && (
                            <div className="p-4 bg-red-500/10 border border-red-500/20 rounded-xl flex items-start gap-3">
                                <AlertCircle size={20} className="text-red-500 flex-shrink-0 mt-0.5" />
                                <p className="text-red-400 text-sm font-medium">{error}</p>
                            </div>
                        )}
                        {success && (
                            <div className="p-4 bg-green-500/10 border border-green-500/20 rounded-xl">
                                <p className="text-green-400 text-sm font-bold text-center">┬íPerfil actualizado correctamente!</p>
                            </div>
                        )}

                        {/* Avatar Upload */}
                        <div className="flex items-center gap-6 pb-4 border-b border-white/5">
                            <div className="relative group w-24 h-24 rounded-full overflow-hidden bg-neutral-900 border-2 border-white/10 flex-shrink-0">
                                {avatarPreview ? (
                                    <img src={avatarPreview} alt="Avatar Preview" className="w-full h-full object-cover" />
                                ) : (
                                    <div className="w-full h-full flex items-center justify-center">
                                        <User size={32} className="text-slate-500" />
                                    </div>
                                )}
                                <label className="absolute inset-0 bg-black/60 flex flex-col items-center justify-center opacity-0 group-hover:opacity-100 cursor-pointer transition-opacity">
                                    <Camera size={20} className="text-white mb-1" />
                                    <span className="text-[9px] font-black uppercase text-white tracking-widest">Cambiar</span>
                                    <input type="file" accept="image/*" onChange={handleFileChange} className="hidden" />
                                </label>
                            </div>
                            <div>
                                <h3 className="text-sm font-bold text-white mb-1">Foto de Perfil</h3>
                                <p className="text-xs text-slate-400">Recomendado: 400x400px. JPG, PNG o GIF.</p>
                            </div>
                        </div>

                        <div className="space-y-4">
                            <h3 className="text-[10px] font-black text-text-low uppercase tracking-[0.2em] border-b border-white/5 pb-2">Informaci├│n de Usuario</h3>
                            
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                <div className="space-y-1">
                                    <label className="text-xs font-bold text-slate-400 uppercase">Nombre de Usuario (├Ünico)</label>
                                    <div className="relative">
                                        <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                                            <User size={14} className="text-geeko-cyan" />
                                        </div>
                                        <input 
                                            type="text" 
                                            name="username"
                                            value={formData.username}
                                            onChange={handleChange}
                                            className="w-full bg-white/5 border border-white/10 rounded-xl py-2.5 pl-9 pr-4 text-sm text-white focus:outline-none focus:border-geeko-cyan focus:ring-1 focus:ring-geeko-cyan transition-all"
                                            placeholder="ej. cyber_geek"
                                        />
                                    </div>
                                </div>
                                <div className="space-y-1">
                                    <label className="text-xs font-bold text-slate-400 uppercase">C├⌐dula / Documento</label>
                                    <div className="relative">
                                        <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                                            <Hash size={14} className="text-slate-500" />
                                        </div>
                                        <input 
                                            type="text" 
