                    );
                })}
            </div>
            
            {/* Background Glow Effect */}
            <div className="absolute top-1/4 -right-1/4 w-[500px] h-[500px] rounded-full blur-[150px] opacity-20 pointer-events-none" style={{ backgroundColor: theme.primary }}></div>
        </div>
    );
};

import { useState, useEffect, useRef } from 'react';
import { searchCardNames } from '../../utils/api';

interface SearchBarProps {
  onSelect?: (card: any) => void;
  placeholder?: string;
  mobile?: boolean;
  value?: string;
  onChange?: (value: string) => void;
}

export function SearchBar({ onSelect, placeholder, mobile = false, value = "", onChange }: SearchBarProps) {
  const [suggestions, setSuggestions] = useState<string[]>([]);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const containerRef = useRef<HTMLFormElement>(null);

  // Mobile prop ignored for now to satisfy lint if not used in JSX
  if (mobile) { /* placeholder for mobile styles */ }

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
        setShowSuggestions(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    const fetchSuggestions = async () => {
      if (!value || value.length < 2) {
        setSuggestions([]);
        setShowSuggestions(false);
        return;
      }

      try {
        const results = await searchCardNames(value);
        setSuggestions(results);

        // Hide if exact match and it is the only result (UX preference to avoid re-popup after select)
        const isExactMatch = results.some(r => r.toLowerCase() === value.toLowerCase());
        if (isExactMatch && results.length === 1) {
          setShowSuggestions(false);
        } else {
          setShowSuggestions(true);
        }
      } catch (e) {
        console.error("Autocomplete fetch error", e);
      }
    };

    const timeoutId = setTimeout(fetchSuggestions, 300);
    return () => clearTimeout(timeoutId);
  }, [value]);

  const handleSelect = (suggestion: string) => {
    if (onChange) onChange(suggestion);
    if (onSelect) onSelect({ name: suggestion });
    setShowSuggestions(false);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setShowSuggestions(false);
    if (onChange && value) onChange(value);
  };

  return (
    <form ref={containerRef} className="relative w-full max-w-md" role="search" onSubmit={handleSubmit}>
      <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-4 h-4 text-neutral-500">
          <path strokeLinecap="round" strokeLinejoin="round" d="M21 21l-4.35-4.35m0 0A7.5 7.5 0 104.5 4.5a7.5 7.5 0 0012.15 12.15z" />
        </svg>
      </div>
      <input
        id="search-input"
        type="text"
        className="block w-full pl-10 pr-4 py-2 bg-neutral-800 border border-neutral-700 rounded-full text-white text-sm focus:outline-none focus:ring-2 focus:ring-purple-500/50 focus:border-purple-500/50 transition-all placeholder:text-neutral-500"
        placeholder={placeholder || 'Search cards, sets...'}
        value={value}
        onChange={e => onChange && onChange(e.target.value)}
        onFocus={() => {
          if (value && value.length >= 2) setShowSuggestions(true);
        }}
        autoComplete="off"
      />

      {showSuggestions && suggestions.length > 0 && (
        <div data-testid="suggestions-list" className="absolute z-50 w-full mt-1 bg-neutral-900/90 backdrop-blur-md border border-neutral-700 rounded-lg shadow-xl overflow-hidden max-h-60 overflow-y-auto">
          {suggestions.map((suggestion, index) => (
            <button
              key={index}
              type="button"
              className="w-full text-left px-4 py-2 text-sm text-neutral-300 hover:bg-neutral-800 hover:text-white transition-colors cursor-pointer"
              onClick={() => handleSelect(suggestion)}
            >
              {suggestion}
            </button>
          ))}
        </div>
      )}
    </form>
  );
};

import React, { useState, useRef } from 'react';
import { Upload, FileText, CheckCircle2, X, ArrowRight } from 'lucide-react';
import { useAuth } from '../../context/AuthContext';
import { GlassCard } from '../ui/GlassCard';

interface BulkImportProps {
    onImportComplete: (data: any) => void;
    importType: 'collection' | 'prices' | 'inventory' | 'catalog';
}

export const BulkImport: React.FC<BulkImportProps> = ({ onImportComplete, importType }) => {
    const { session } = useAuth();
    const [isDragging, setIsDragging] = useState(false);
    const [file, setFile] = useState<File | null>(null);
    const [formatName, setFormatName] = useState<string>('');
    const [step, setStep] = useState<1 | 2 | 3>(1); // 1: Upload, 2: Mapping, 3: Success
    const [rows, setRows] = useState<string[][]>([]);
    const [headers, setHeaders] = useState<string[]>([]);
    const [isAutoMapped, setIsAutoMapped] = useState(false);
    const fileInputRef = useRef<HTMLInputElement>(null);

    const TXT_FORMAT_REGEX = /^(\d+)\s+(.+?)\s+\((.+?)\)\s+(\d+)(?:\s+([*F]+))?$/;

    const handleDragOver = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragging(true);
    };

    const handleDragLeave = () => {
        setIsDragging(false);
    };

    const processFile = (selectedFile: File) => {
        if (!selectedFile.name.endsWith('.csv') && !selectedFile.name.endsWith('.txt')) {
            alert('Por favor, sube un archivo CSV o TXT.');
            return;
        }

        const reader = new FileReader();
        reader.onload = (e) => {
            const text = e.target?.result as string;
            const lines = text.split(/\r?\n/).filter(line => line.trim().length > 0);
            if (lines.length === 0) return;

            // Detect special .txt format: "1 Agatha's Soul Cauldron (WOE) 242"
            const isSpecialTxt = selectedFile.name.endsWith('.txt') && TXT_FORMAT_REGEX.test(lines[0]);

            if (isSpecialTxt) {
                const parsedRows = lines.map(line => {
                    const match = line.trim().match(TXT_FORMAT_REGEX);
                    if (match) {
                        return [
                            match[1], // quantity
                            match[2], // name
                            match[3], // set
                            match[4], // collector_number
                            (match[5] && (match[5].includes('*') || match[5].toLowerCase().includes('f'))) ? 'foil' : 'nonfoil' // finish
                        ];
                    }
                    return null;
                }).filter(row => row !== null) as string[][];

                if (parsedRows.length > 0) {
                    setHeaders(['quantity', 'name', 'set', 'collector_number', 'finish']);
                    setMapping({
                        quantity: 'quantity',
                        name: 'name',
                        set: 'set',
                        collector_number: 'collector_number',
                        finish: 'finish',
                        condition: '',
                        price: ''
                    });
                    setRows(parsedRows);
                    setFile(selectedFile);
                    setIsAutoMapped(true);
                    setStep(2);
                }
            } else {
                // CSV parsing with improved delimiter detection (comma, tab, semicolon, pipe)
                const firstLine = lines[0];
                let delimiter = ',';
                if (!firstLine.includes(',') && firstLine.includes('\t')) delimiter = '\t';
                else if (!firstLine.includes(',') && firstLine.includes(';')) delimiter = ';';
                else if (!firstLine.includes(',') && firstLine.includes('|')) delimiter = '|';

                const parsedRows = lines.map(line => {
                    const rowText = line.trim();
                    const cells = [];
                    let currentCell = '';
                    let inQuotes = false;

                    for (let i = 0; i < rowText.length; i++) {
                        const char = rowText[i];
                        if (char === '"') {
                            inQuotes = !inQuotes;
                        } else if (char === delimiter && !inQuotes) {
                            cells.push(currentCell.trim().replace(/^"|"$/g, ''));
                            currentCell = '';
                        } else {
                            currentCell += char;
                        }
                    }
                    cells.push(currentCell.trim().replace(/^"|"$/g, ''));
                    return cells;
                });

                if (parsedRows.length > 0) {
                    const csvHeaders = parsedRows[0];
                    const csvContent = parsedRows.slice(1);
                    setHeaders(csvHeaders);
                    setRows(csvContent);
                    setFile(selectedFile);

                    // Auto-detect known formats (e.g. ManaBox or our own CATALOG template)
                    const isManaBox = csvHeaders.includes('ManaBox ID') || csvHeaders.includes('Scryfall ID');
                    const isCatalog = importType === 'catalog' && (csvHeaders.includes('category_code') || csvHeaders.includes('suggested_price'));

                    if (isManaBox) {
                        setFormatName('ManaBox');
                        setMapping(prev => ({
                            ...prev,
                            name: csvHeaders.includes('Name') ? 'Name' : '',
                            set: csvHeaders.includes('Set code') ? 'Set code' : '',
                            collector_number: csvHeaders.includes('Collector number') ? 'Collector number' : '',
                            quantity: csvHeaders.includes('Quantity') ? 'Quantity' : '',
                            price: csvHeaders.includes('Purchase price') ? 'Purchase price' : '',
                            condition: csvHeaders.includes('Condition') ? 'Condition' : '',
                            finish: csvHeaders.includes('Foil') ? 'Foil' : '',
                            scryfall_id: csvHeaders.includes('Scryfall ID') ? 'Scryfall ID' : ''
                        }));
                        setIsAutoMapped(true);
                    } else if (isCatalog) {
                        setFormatName('Cat├ílogo');
                        const newMapping = { ...mapping };
                        
                        // Robust catalog auto-mapping
                        const catalogMap: Record<string, string[]> = {
                            name: ['name', 'producto', 'nombre'],
                            price: ['price', 'precio', 'venta'],
                            cost: ['cost', 'costo'],
                            suggested_price: ['suggested_price', 'precio_sugerido', 'sugerido'],
                            category_code: ['category_code', 'categor├¡a', 'categoria', 'category'],
                            game_id: ['game_id', 'id_juego', 'juego'],
                            stock: ['stock', 'cantidad', 'inventario'],
                            description: ['description', 'descripci├│n', 'descripcion'],
                            unit_type: ['unit_type', 'unidad', 'tipo'],
                            language: ['language', 'idioma']
                        };

                        Object.entries(catalogMap).forEach(([field, aliases]) => {
                            const found = csvHeaders.find(h => aliases.includes(h.toLowerCase().trim()));
                            if (found) newMapping[field] = found;
                        });

                        setMapping(newMapping);
                        setIsAutoMapped(true);
                    } else {
                        setFormatName('');
                        setIsAutoMapped(false);
                    }
                    setStep(2);
                }
            }
        };
        reader.readAsText(selectedFile);
    };

    const handleDrop = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragging(false);
        const selectedFile = e.dataTransfer.files[0];
        if (selectedFile) processFile(selectedFile);
    };

    const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
        const selectedFile = e.target.files?.[0];
        if (selectedFile) processFile(selectedFile);
    };

    const downloadTemplate = (tcg: string) => {
        const templates: Record<string, string> = {
            'MTG': 'Name,Set Code,Collector Number,Condition,Quantity,Price Paid\nBlack Lotus,LEA,1,NM,1,20000',
            'CATALOG': 'name,description,price,stock,category_code,unit_type,language,cost,suggested_price\nSleeves Dragon Shield Blue,High quality sleeves,12.50,50,SLEEVE,Unit,English,8.00,15.00'
        };

        const content = templates[tcg] || templates['MTG'];
        const blob = new Blob([content], { type: 'text/csv;charset=utf-8' });
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.style.display = 'none';
        a.href = url;
        a.download = `Geekorium_Template_${tcg}.csv`;
        document.body.appendChild(a);
        a.click();

        // Cleanup
        window.URL.revokeObjectURL(url);
        document.body.removeChild(a);
    };

    const downloadFailedRows = () => {
        if (!result?.failed_indices || result.failed_indices.length === 0) return;

        const failedRows = rows.filter((_, index) => result.failed_indices.includes(index));

        // Reconstruct content based on original format estimation
        // For simplicity, we'll try to keep the original structure if possible, 
        // or just dump the values we have.
        // If it was the special TXT format:
        let content = "";

        // Check if we are in special TXT mode by checking headers
        const isSpecialTxt = headers.includes('collector_number') && headers.includes('set') && (headers.length === 4 || headers.length === 5);

        if (isSpecialTxt) {
            // Reconstruct: "Quantity Name (Set) CollectorNumber [*F*]"
            content = failedRows.map(row => {
                const qty = row[headers.indexOf('quantity')] || '1';
                const name = row[headers.indexOf('name')] || '';
                const set = row[headers.indexOf('set')] || '';
                const num = row[headers.indexOf('collector_number')] || '';
                const finish = row[headers.indexOf('finish')];
                return `${qty} ${name} (${set}) ${num}${finish === 'foil' ? ' *F*' : ''}`;
            }).join('\n');
        } else {
            // CSV fallback
            content = [headers.join(',')].concat(failedRows.map(r => r.join(','))).join('\n');
        }

        const blob = new Blob([content], { type: 'text/plain;charset=utf-8' });
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.style.display = 'none';
        a.href = url;
        a.download = `failed_import_rows_${new Date().toISOString().split('T')[0]}.txt`;
        document.body.appendChild(a);
        a.click();

        window.URL.revokeObjectURL(url);
        document.body.removeChild(a);
    };

    const [mapping, setMapping] = useState<Record<string, string>>({
        name: '',
        set: '',
        collector_number: '',
        quantity: '',
        price: '',
        condition: '',
        finish: '',
        scryfall_id: '',
        // Catalog fields
        description: '',
        stock: '',
        category_code: '',
        unit_type: '',
        language: '',
        cost: '',
        suggested_price: '',
        game_id: ''
    });
    const [loading, setLoading] = useState(false);
    const [result, setResult] = useState<any>(null);
    const [progress, setProgress] = useState({ current: 0, total: 0, items: 0 });

const handleImport = async () => {
        if (!session) {
            alert('Por favor, inicia sesi├│n para importar tu colecci├│n.');
            return;
        }

        // Potential foil mismatch check
        const priceCol = headers.indexOf(mapping.price);
        const finishCol = headers.indexOf(mapping.finish);
        const nameCol = headers.indexOf(mapping.name);

        if (priceCol !== -1 && finishCol !== -1) {
            const highPricedNonFoils = rows.filter(row => {
                const price = parseFloat(row[priceCol]);
                const finish = row[finishCol]?.toLowerCase();
                return price > 50 && (finish === 'nonfoil' || !finish);
            });

            if (highPricedNonFoils.length > 0) {
                const firstCard = highPricedNonFoils[0][nameCol];
                const confirm = window.confirm(
                    `Se detectaron ${highPricedNonFoils.length} cartas con precio alto ($ > 50) marcadas como NO-FOIL (ej: ${firstCard}).\n\n` +
                    `┬┐Est├ís seguro de que quieres continuar? Esto podr├¡a ser un error de formato y causar que se guarden con el acabado incorrecto.`
                );
                if (!confirm) return;
            }
        }

        setLoading(true);
        try {
            const API_BASE = import.meta.env.VITE_API_BASE;

            const importData = rows.map(row => {
                const obj: any = {};
                headers.forEach((h, i) => obj[h] = row[i]);
                return obj;
            });

            // Chunks of 50 to prevent statement timeouts on the database side
            const CHUNK_SIZE = 50;
            const chunks = [];
            for (let i = 0; i < importData.length; i += CHUNK_SIZE) {
                chunks.push(importData.slice(i, i + CHUNK_SIZE));
            }

            setProgress({ current: 0, total: chunks.length, items: 0 });

            let totalImported = 0;
            let allErrors: string[] = [];
            let allFailedIndices: number[] = [];

            // Process chunks sequentially (concurrency 1) to avoid lock contention and timeouts
            const CONCURRENCY = 1;
            for (let i = 0; i < chunks.length; i += CONCURRENCY) {
                const batch = chunks.slice(i, i + CONCURRENCY);
                const promises = batch.map(async (chunk, batchIdx) => {
                    const response = await fetch(`${API_BASE}/api/collections/import?import_type=${importType}`, {
                        method: 'POST',
                        headers: {
                            'Content-Type': 'application/json',
                            'Authorization': `Bearer ${session?.access_token}`
                        },
                        body: JSON.stringify({
                            data: chunk,
                            mapping: mapping
                        })
                    });

                    if (!response.ok) {
                        const errorData = await response.json().catch(() => ({ detail: response.statusText }));
                        throw new Error(`Error en lote ${i + batchIdx + 1}: ${errorData.detail || errorData.error || response.statusText}`);
                    }

                    return response.json();
                });

                const chunkResults = await Promise.all(promises);

                chunkResults.forEach((chunkResult, batchIdx) => {
                    totalImported += chunkResult.imported_count || 0;
                    
                    const offset = (i + batchIdx) * CHUNK_SIZE;
                    
                    if (chunkResult.errors) {
                        const adjustedErrors = chunkResult.errors.map((err: string) => {
                            // Find the "Row N" pattern and adjust it
                            return err.replace(/Row (\d+)/, (_, p1) => `Row ${parseInt(p1) + offset}`);
                        });
                        allErrors = [...allErrors, ...adjustedErrors];
                    }
                    if (chunkResult.failed_indices) {
                        allFailedIndices = [...allFailedIndices, ...chunkResult.failed_indices.map((idx: number) => idx + offset)];
                    }
                });

                const completedCount = Math.min(i + CONCURRENCY, chunks.length);
                setProgress({
                    current: completedCount,
                    total: chunks.length,
                    items: totalImported
                });

                // Small cooldown between parallel batches to stay safe
                if (i + CONCURRENCY < chunks.length) {
                    await new Promise(resolve => setTimeout(resolve, 300));
                }
            }

            setResult({
                imported_count: totalImported,
                total_rows: importData.length,
                errors: allErrors,
                failed_indices: allFailedIndices
            });
            setStep(3);
        } catch (err: any) {
            console.error("Import error:", err);
            alert(`Error al importar datos: ${err.message}`);
        } finally {
            setLoading(false);
        }
    };

    const systemFields = importType === 'catalog' ? [
        { id: 'name', label: 'Nombre del Producto' },
        { id: 'description', label: 'Descripci├│n' },
        { id: 'price', label: 'Precio Geek (Venta)' },
        { id: 'stock', label: 'Stock Inicial' },
        { id: 'category_code', label: 'C├│digo de Categor├¡a' },
        { id: 'unit_type', label: 'Tipo de Unidad' },
        { id: 'language', label: 'Idioma' },
        { id: 'cost', label: 'Costo (USD)' },
        { id: 'suggested_price', label: 'Precio Sugerido' },
        { id: 'game_id', label: 'ID de Juego (Opcional)' }
    ] : [
        { id: 'name', label: 'Nombre de Carta' },
        { id: 'set', label: 'Set/C├│digo' },
        { id: 'collector_number', label: 'Num. Coleccionista' },
        { id: 'quantity', label: 'Cantidad' },
        { id: 'price', label: 'Precio/Valor' },
        { id: 'finish', label: 'Acabado (Foil/Non)' },
        { id: 'condition', label: 'Condici├│n' },
        { id: 'scryfall_id', label: 'Scryfall ID' }
    ];

    return (
        <div className="w-full max-w-4xl mx-auto">
            {step === 1 && (
                <div className="space-y-6">
                    <GlassCard
                        className={`p-12 border-2 border-dashed transition-all duration-500 ${isDragging ? 'border-geeko-cyan bg-geeko-cyan/5 scale-105' : 'border-white/10'
                            }`}
                        onDragOver={handleDragOver}
                        onDragLeave={handleDragLeave}
                        onDrop={handleDrop}
                        onClick={() => fileInputRef.current?.click()}
                    >
                        <input
                            type="file"
                            ref={fileInputRef}
                            onChange={handleFileSelect}
                            className="hidden"
                            accept=".csv,.txt"
                        />
                        <div className="flex flex-col items-center text-center space-y-6">
                            <div className="w-20 h-20 bg-geeko-cyan/10 rounded-3xl flex items-center justify-center border border-geeko-cyan/20 group-hover:scale-110 transition-transform">
                                <Upload className="text-geeko-cyan w-10 h-10 animate-bounce" />
                            </div>
                            <div>
                                <h2 className="text-3xl font-black italic tracking-tighter uppercase mb-2">
                                    Carga Masiva <span className="text-geeko-cyan">{importType === 'prices' ? 'PRECIOS' : importType === 'inventory' ? 'INVENTARIO' : importType === 'catalog' ? 'CAT├üLOGO' : 'COLECCI├ôN'}</span>
                                </h2>
                                <p className="text-slate-400 font-bold text-sm">
                                    Arrastra tu archivo CSV o haz clic para buscar.
                                </p>
                            </div>
                        </div>
                    </GlassCard>

                    <div className="flex flex-col items-center gap-4">
                        <p className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-500">┬┐No tienes un formato? Descarga uno:</p>
                        <div className="flex flex-wrap justify-center gap-3">
                            {(importType === 'catalog' ? ['CATALOG'] : ['MTG']).map(tcg => (
                                <button
                                    key={tcg}
                                    onClick={(e) => { e.stopPropagation(); downloadTemplate(tcg); }}
                                    className="px-6 py-2 bg-white/5 border border-white/10 rounded-full text-[10px] font-black uppercase tracking-widest hover:bg-geeko-cyan hover:text-black transition-all"
                                >
                                    Template {tcg === 'CATALOG' ? 'Cat├ílogo' : tcg}
                                </button>
                            ))}
                        </div>
                    </div>
                </div>
            )}

            {step === 2 && (
                <GlassCard className="p-8 space-y-8 animate-in fade-in slide-in-from-bottom-4">
                    <div className="flex items-center justify-between border-b border-white/10 pb-6">
                        <div className="flex items-center gap-4">
                            <FileText className="text-geeko-cyan w-8 h-8" />
                            <div>
                                <h3 className="text-xl font-black italic uppercase">{file?.name}</h3>
                                <p className="text-slate-500 text-xs font-bold">
