                                                        const catVal = row[headers.indexOf(mapping.category_code)];
                                                        const priceVal = row[headers.indexOf(mapping.price)];
                                                        const costVal = row[headers.indexOf(mapping.cost)];
                                                        const gameVal = row[headers.indexOf(mapping.game_id)];

                                                        return (
