                    </div>

                    {loading ? (
                        <div className="w-full space-y-6 p-8 bg-black/40 backdrop-blur-xl rounded-[2rem] border border-white/10 shadow-2xl animate-in fade-in zoom-in-95 duration-500 relative overflow-hidden">
