                                    className="absolute -bottom-4 h-8 bg-geeko-cyan/20 blur-2xl transition-all duration-700 rounded-full"
                                    style={{
                                        width: `${(progress.current / progress.total) * 100}%`,
                                        left: 0
                                    }}
                                />
                            </div>

                            <div className="flex justify-between items-center relative z-10">
                                <p className="text-[9px] font-black text-slate-500 uppercase tracking-[0.2em]">
                                    Arquitectura Geekorium v2.0 <span className="mx-2">|</span> Optimizaci├│n Activa
                                </p>
                                <div className="flex gap-1">
                                    {[1, 2, 3].map(i => (
                                        <div
                                            key={i}
                                            className="w-1 h-1 bg-geeko-cyan rounded-full animate-bounce"
                                            style={{ animationDelay: `${i * 0.2}s` }}
                                        />
                                    ))}
                                </div>
                            </div>
                        </div>
                    ) : (
                        <button
                            onClick={handleImport}
                            disabled={loading}
                            className="w-full bg-geeko-cyan text-black py-4 rounded-2xl font-black uppercase tracking-widest text-sm hover:scale-[1.02] active:scale-95 transition-all shadow-[0_0_30px_rgba(0, 209, 255, 0.2)] flex items-center justify-center gap-2 disabled:opacity-50"
                        >
                            Confirmar Importaci├│n <ArrowRight size={18} />
                        </button>
                    )}
                </GlassCard>
            )}

            {step === 3 && (
                <GlassCard className="p-16 text-center space-y-8 animate-in zoom-in-95">
                    <div className="w-24 h-24 bg-geeko-cyan/20 rounded-full flex items-center justify-center border border-geeko-cyan/30 mx-auto">
                        <CheckCircle2 className="text-geeko-cyan w-12 h-12" />
                    </div>
                    <div>
                        <h2 className="text-4xl font-black italic uppercase tracking-tighter mb-2">┬íSincronizaci├│n Finalizada!</h2>
                        <p className="text-slate-400 font-bold">
                            Hemos importado <span className="text-geeko-cyan">{result?.imported_count || 0}</span> de <span className="text-white">{rows.length}</span> cartas detectadas.
                        </p>
                        {result?.errors?.length > 0 && (
                            <div className="mt-4 p-4 bg-red-500/10 border border-red-500/20 rounded-xl text-left max-h-40 overflow-y-auto scrollbar-thin scrollbar-thumb-white/10">
                                <p className="text-red-500 text-[10px] font-black uppercase tracking-widest mb-2 sticky top-0 bg-[#0c0c0c]/90 backdrop-blur p-1">
                                    Inconsistencias ({result.errors.length}):
                                </p>
                                <ul className="text-[10px] text-slate-400 font-medium space-y-1">
                                    {result.errors.map((err: string, i: number) => (
                                        <li key={i}>ΓÇó {err}</li>
                                    ))}
                                </ul>
                            </div>
                        )}

                        {result?.failed_indices?.length > 0 && (
                            <button
                                onClick={downloadFailedRows}
                                className="mt-2 text-[10px] font-black uppercase tracking-widest text-geeko-cyan hover:underline hover:text-white transition-colors"
                            >
                                Descargar {result.failed_indices.length} filas fallidas (.txt)
                            </button>
                        )}
                    </div>
                    <div className="flex justify-center gap-4">
                        <button
                            onClick={() => setStep(1)}
                            className="px-8 py-3 bg-white/5 border border-white/10 rounded-xl font-black text-xs uppercase tracking-widest hover:bg-white/10 transition-all"
                        >
                            Cargar otro
                        </button>
                        <button
                            onClick={() => onImportComplete(rows)}
                            className="px-8 py-3 bg-geeko-cyan text-black rounded-xl font-black text-xs uppercase tracking-widest hover:scale-105 transition-all"
                        >
                            {importType === 'catalog' ? 'Ver Cat├ílogo' : 'Ver Portafolio'}
                        </button>
                    </div>
                </GlassCard>
            )}
        </div>
    );
};

import React, { createContext, useContext, useEffect, useState, useCallback } from 'react';
import { fetchCart, listUserCarts, switchActiveCart, createNamedCart, clearActiveCart as clearActiveCartApi } from '../utils/api';
import { useAuth } from './AuthContext';

interface CartItem {
    id: string;
    product_id: string | null;
    accessory_id?: string | null;
    quantity: number;
    price: number;
    name?: string;
    image_url?: string;
    is_foil?: boolean;
    set_code?: string;
}

interface CartContextType {
    cartItems: CartItem[];
    availableCarts: any[];
    cartCount: number;
    priceChangeAlert: boolean;
    dismissPriceAlert: () => void;
    refreshCart: (isPos?: boolean) => Promise<void>;
    switchCart: (cartId: string) => Promise<void>;
    createCart: (name: string, isPos?: boolean) => Promise<void>;
    removeCart: (cartId: string) => Promise<void>;
    clearActiveCart: () => Promise<void>;
    isLoading: boolean;
    activeCartName: string | null;
    currentIsPos: boolean;
}

const CartContext = createContext<CartContextType>({
    cartItems: [],
    availableCarts: [],
    cartCount: 0,
    priceChangeAlert: false,
    dismissPriceAlert: () => { },
    refreshCart: async () => { },
    switchCart: async () => { },
    createCart: async () => { },
    removeCart: async () => { },
    clearActiveCart: async () => { },
    isLoading: false,
    activeCartName: null,
    currentIsPos: false,
});

const CART_STORAGE_KEY = 'geekorium_cart_snapshot';

export const CartProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    console.log('DEBUG: CartProvider Mounting v18 - POS Provider Order Fixed');
    const { user } = useAuth();
    const [cartItems, setCartItems] = useState<CartItem[]>([]);
    const [availableCarts, setAvailableCarts] = useState<any[]>([]);
    const [isLoading, setIsLoading] = useState(false);
    const [priceChangeAlert, setPriceChangeAlert] = useState(false);
    const [activeCartName, setActiveCartName] = useState<string | null>(() => {
        return localStorage.getItem('pos_active_name');
    });
    const [currentIsPos, setCurrentIsPos] = useState<boolean>(() => {
        return localStorage.getItem('pos_active_is_pos') === 'true';
    });

    const refreshCart = useCallback(async (_forcedIsPos?: boolean) => {
        console.log(`DEBUG: refreshCart [v25] - fetching state for:`, user?.email || 'guest');
        setIsLoading(true);
        try {
            // 1. Fetch items in the CURRENT ACTIVE cart
            let fetchedItems: CartItem[] = [];
            let cartResponse: any = null;
            try {
                cartResponse = await fetchCart();
                const rawItems = (cartResponse && cartResponse.items) || [];
                
                // CRITICAL: If logged in, prioritize DB items and IGNORE local guest items 
                // to prevent $0.00 ghosting/contamination.
                fetchedItems = rawItems
                    .filter((item: any) => !user || !String(item.id).startsWith('guest-'))
                    .map((item: any) => ({
                        id: item.id,
                        product_id: item.product_id,
                        accessory_id: item.accessory_id,
                        quantity: Number(item.quantity || 1),
                        price: Number(item.price || item.products?.price || 0),
                        name: item.name || item.products?.name,
                        image_url: item.image_url || item.products?.image_url,
                        is_foil: (item.finish || item.products?.finish) === 'foil',
                        set_code: item.set_code || item.products?.set_code,
                    }));
                
                setCartItems(Array.isArray(fetchedItems) ? fetchedItems : []);
                
                // Update Session state from unified RPC result
                if (user && cartResponse && cartResponse.id) {
                    setActiveCartName(cartResponse.name || 'Carrito Principal');
                    setCurrentIsPos(!!cartResponse.is_pos);
                    localStorage.setItem('pos_active_name', cartResponse.name || '');
                    localStorage.setItem('pos_active_is_pos', String(!!cartResponse.is_pos));
                }

                // Save snapshot for price change detection
                localStorage.setItem(CART_STORAGE_KEY, JSON.stringify(fetchedItems));
            } catch (err) {
                console.warn('CartContext: current cart items load failed', err);
                setCartItems([]);
            }
            
            // 2. Fetch list of available carts (Crucial for Admin Management)
            if (user) {
                try {
                    const carts = await listUserCarts(true); // Fetch all POS-aware carts
                    setAvailableCarts(carts);
                    
                    // If metadata wasn't set by fetchCart result alone (fallback):
                    const active = carts.find(c => c.is_active);
                    if (active && (!cartResponse?.id || active.id === cartResponse.id)) {
                        setActiveCartName(active.name || 'Carrito Principal');
                        setCurrentIsPos(active.is_pos || false);
                    }
                } catch (err) {
                    console.error('CartContext: available carts load failed', err);
                    setAvailableCarts([]);
                }
            } else {
                setActiveCartName(null);
                setCurrentIsPos(false);
                setAvailableCarts([]);
                localStorage.removeItem('pos_active_name');
                localStorage.removeItem('pos_active_is_pos');
            }

            // Compare against localStorage snapshot to detect price changes
            const snapshot = localStorage.getItem(CART_STORAGE_KEY);
            if (snapshot) {
                try {
                    const savedItems: CartItem[] = JSON.parse(snapshot);
                    const hasPriceChange = fetchedItems.some(item => {
                        const itemKey = item.product_id || item.accessory_id;
                        const saved = savedItems.find(s => (s.product_id || s.accessory_id) === itemKey);
                        return saved && Math.abs(saved.price - item.price) > 0.01;
                    });
                    if (hasPriceChange) {
                        setPriceChangeAlert(true);
                    }
                } catch {
                    // Ignore parsing errors
                }
            }
        } catch (err) {
            console.error('CartContext: failed to load cart state', err);
        } finally {
            setIsLoading(false);
            // Dispatch custom event for vanilla components
            window.dispatchEvent(new CustomEvent('cart-refreshed', { 
                detail: { activeCartName, currentIsPos } 
            }));
        }
    }, [user]);

    // Persistent storage synchronization
    useEffect(() => {
        if (activeCartName !== null) {
            localStorage.setItem('pos_active_name', activeCartName);
        } else {
            localStorage.removeItem('pos_active_name');
        }
    }, [activeCartName]);

    useEffect(() => {
        localStorage.setItem('pos_active_is_pos', String(currentIsPos));
    }, [currentIsPos]);

    // Load whenever user or auth state changes
    useEffect(() => {
        // Only run if we actually have context or after initial mount delay
        const timer = setTimeout(() => {
            refreshCart();
        }, 100);
        
        return () => clearTimeout(timer);
    }, [user, refreshCart]);

    useEffect(() => {
        const handler = () => {
            console.log(`DEBUG: cart-updated event detected [v25] - refreshing...`);
            refreshCart();
        };
        
        const storageHandler = (e: StorageEvent) => {
            if (e.key === 'cart_sync_timestamp' || e.key === 'guest_cart' || e.key === 'supabase.auth.token') {
                console.log(`DEBUG: cross-tab storage event detected (${e.key}) - refreshing...`);
                refreshCart();
            }
        };

        window.addEventListener('cart-updated', handler as any);
        window.addEventListener('storage', storageHandler);
        
        return () => {
            window.removeEventListener('cart-updated', handler as any);
            window.removeEventListener('storage', storageHandler);
        };
    }, [refreshCart]);
    const cartCount = Array.isArray(cartItems)
        ? cartItems.reduce((acc, item) => acc + (item.quantity || 1), 0)
        : 0;

    const dismissPriceAlert = () => setPriceChangeAlert(false);

    const switchCart = async (cartId: string) => {
        setIsLoading(true);
        console.log(`DEBUG: Switching to cart ${cartId}...`);
        try {
            await switchActiveCart(cartId);
            // Give a small breathing room for DB consistency if needed, 
            // though RPC should be synchronous.
            await new Promise(resolve => setTimeout(resolve, 100));
            await refreshCart();
            console.log(`DEBUG: Switch complete.`);
        } catch (err) {
            console.error('Failed to switch cart:', err);
        } finally {
            setIsLoading(false);
        }
    };

    const createCart = async (name: string, isPos: boolean = false) => {
        setIsLoading(true);
        try {
            await createNamedCart(name, isPos);
            await refreshCart(isPos);
        } catch (err: any) {
            console.error('Failed to create cart:', err);
            // Alert user of permission issues
            if (err.message?.includes('admin') || err.message?.includes('permisos')) {
                alert('Error: Solo los administradores pueden realizar esta acci├│n.');
            }
        } finally {
            setIsLoading(false);
        }
    };

    const removeCart = async (cartId: string) => {
        if (!window.confirm('┬┐Est├ís seguro de eliminar este cliente de la terminal?')) return;
        
        setIsLoading(true);
        try {
            await (import('../utils/api').then(api => api.deleteCart(cartId)));
            await refreshCart(currentIsPos);
        } catch (err: any) {
            console.error('Failed to delete cart:', err);
            alert(err.message || 'Error al eliminar el carrito');
        } finally {
            setIsLoading(false);
        }
    };

    const clearActiveCart = async () => {
        setIsLoading(true);
        try {
            await clearActiveCartApi();
            await refreshCart(false);
        } catch (err) {
            console.error('Failed to clear active cart:', err);
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <CartContext.Provider value={{ 
            cartItems, 
            availableCarts,
            cartCount, 
            priceChangeAlert, 
            dismissPriceAlert, 
            refreshCart, 
            switchCart,
            createCart,
            removeCart,
            clearActiveCart,
            isLoading,
            activeCartName,
            currentIsPos
        }}>
            {children}
        </CartContext.Provider>
    );
};

