                                <Calendar className="text-rose-400" size={32} />
                            </div>
                        </div>
                    </Link>

                    <Link to="/admin/rankings" className="group relative overflow-hidden rounded-3xl bg-gradient-to-br from-yellow-900/50 to-slate-900 border border-white/10 p-8 hover:border-yellow-500/50 transition-all">
                        <div className="absolute inset-0 bg-yellow-500/10 opacity-0 group-hover:opacity-100 transition-opacity" />
                        <div className="relative z-10 flex items-center justify-between">
                            <div>
                                <h3 className="text-2xl font-black italic text-white mb-2">RANKINGS TCG</h3>
                                <p className="text-yellow-300 text-xs font-bold uppercase tracking-widest">Temporadas y ELO</p>
                            </div>
                            <div className="w-16 h-16 bg-yellow-500/20 rounded-2xl flex items-center justify-center group-hover:scale-110 transition-transform">
                                <Database className="text-yellow-400" size={32} />
                            </div>
                        </div>
                    </Link>

                    <Link to="/admin/presales" className="group relative overflow-hidden rounded-3xl bg-gradient-to-br from-emerald-900/50 to-slate-900 border border-white/10 p-8 hover:border-white/50 transition-all">
                        <div className="absolute inset-0 bg-white/10 opacity-0 group-hover:opacity-100 transition-opacity" />
                        <div className="relative z-10 flex items-center justify-between">
                            <div>
                                <h3 className="text-2xl font-black italic text-white mb-2">PREVENTAS</h3>
                                <p className="text-emerald-300 text-xs font-bold uppercase tracking-widest">Anuncios de Preventa</p>
                            </div>
                            <div className="w-16 h-16 bg-white/20 rounded-2xl flex items-center justify-center group-hover:scale-110 transition-transform">
                                <TrendingUp className="text-white" size={32} />
                            </div>
                        </div>
                    </Link>

                    <Link to="/import" className="group relative overflow-hidden rounded-3xl bg-gradient-to-br from-slate-800 to-slate-900 border border-white/10 p-8 hover:border-white/20 transition-all">
                        <div className="absolute inset-0 bg-white/5 opacity-0 group-hover:opacity-100 transition-opacity" />
                        <div className="relative z-10 flex items-center justify-between">
                            <div>
                                <h3 className="text-2xl font-black italic text-white mb-2">IMPORTAR</h3>
                                <p className="text-slate-400 text-xs font-bold uppercase tracking-widest">Carga Masiva de Colecci├│n</p>
                            </div>
                            <div className="w-16 h-16 bg-slate-800 rounded-2xl flex items-center justify-center group-hover:scale-110 transition-transform">
                                <Upload className="text-slate-300" size={32} />
                            </div>
                        </div>
                    </Link>
                    <button onClick={() => setShowPriceHistory(true)} className="group relative overflow-hidden rounded-3xl bg-gradient-to-br from-pink-900/50 to-slate-900 border border-white/10 p-8 hover:border-pink-500/50 transition-all text-left w-full">
                        <div className="absolute inset-0 bg-pink-500/10 opacity-0 group-hover:opacity-100 transition-opacity" />
                        <div className="relative z-10 flex items-center justify-between">
                            <div>
                                <h3 className="text-2xl font-black italic text-white mb-2">HISTORIAL DE PRECIOS</h3>
                                <p className="text-pink-300 text-xs font-bold uppercase tracking-widest">Logs de Sincronizaci├│n</p>
                            </div>
                            <div className="w-16 h-16 bg-pink-500/20 rounded-2xl flex items-center justify-center group-hover:scale-110 transition-transform">
                                <History className="text-pink-400" size={32} />
                            </div>
                        </div>
                    </button>
                </div>

                <div className="mb-12">
                    <CloudflareAnalytics session={session} apiBase={API_BASE} />
                </div>

                {/* Hidden Scrapers */}
                <div className="grid grid-cols-1 gap-8">
                    <div className="space-y-8">
                            <div className="glass-card rounded-3xl p-8 border border-white/5 bg-slate-900/50">
                                <h2 className="text-2xl font-black mb-6 flex items-center gap-3 italic">
                                    <Shield className="text-white" />
                                    CONTROL DE MISI├ôN
                                </h2>
                                <div className="space-y-4 mb-6">
                                    {activeTasks.length > 0 ? (
                                        activeTasks.map(task => (
                                            <div key={task.id} className="bg-slate-800/20 border border-white/5 rounded-2xl p-4">
                                                <div className="flex items-center justify-between mb-2">
                                                    <span className="font-black text-xs text-slate-300 uppercase tracking-widest">{task.game_code} Ejecutor de Tareas</span>
                                                    <div className="flex items-center gap-2">
                                                        <button onClick={() => fetchTaskLogs(task.id)} className="text-[10px] font-black uppercase text-white hover:underline">Ver Logs</button>
                                                        <span className={`text-[10px] px-2 py-0.5 rounded font-black uppercase ${task.status === 'running' ? 'bg-white/20 text-white' : 'bg-white/20 text-white'}`}>
                                                            {task.status}
                                                        </span>
                                                    </div>
                                                </div>
                                                {task.status === 'running' && (
                                                    <div className="w-full bg-black h-1 mt-2 rounded-full overflow-hidden">
                                                        <div className="bg-white h-full animate-pulse" style={{ width: '100%' }}></div>
                                                    </div>
                                                )}
                                            </div>
                                        ))
                                    ) : (
                                        <div className="text-slate-600 font-bold text-center py-6 bg-black/20 rounded-2xl border border-dashed border-white/5">
                                            NO HAY TAREAS ACTIVAS
                                        </div>
                                    )}
                                </div>
                                <div className="bg-black/60 rounded-2xl p-4 font-mono text-[10px] h-32 overflow-y-auto space-y-1 border border-white/5">
                                    {Object.entries(results).map(([source, result], idx) => (
                                        <div key={idx} className="flex gap-2">
                                            <span className="text-slate-600">[{new Date().toLocaleTimeString()}]</span>
                                            <span className="text-white">{source.toUpperCase()}:</span>
                                            <span className={result.error ? 'text-red-400' : 'text-white'}>
                                                {result.error || result.message || 'OK'}
                                            </span>
                                        </div>
                                    ))}
                                    {Object.keys(results).length === 0 && <div className="text-slate-700 italic">Salida de consola inicializada...</div>}
                                </div>
                            </div>

                            {/* Section: Webhooks & Automation */}
                            <div className="glass-card rounded-3xl p-8 border border-white/10 bg-black/40 border-dashed">
                                <h2 className="text-2xl font-black mb-4 flex items-center gap-3 italic">
                                    <Settings className="text-white" />
                                    AUTOMATIZACI├ôN GITHUB
                                </h2>
                                <p className="text-slate-500 text-xs font-bold mb-6 italic">
                                    Dispara la sincronizaci├│n directamente en GitHub Actions.
                                </p>

                                <div className="space-y-4">
                                    <div className="p-4 bg-black/40 rounded-2xl border border-white/5">
                                        <div className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">Token de Acceso Personal de GitHub</div>
                                        <div className="flex gap-2 mb-2">
                                            <input
                                                type="password"
                                                value={githubToken}
                                                onChange={(e) => saveGithubToken(e.target.value)}
                                                placeholder="ghp_xxxxxxxxxxxx"
                                                className="bg-black/60 p-3 rounded-xl text-white text-[10px] flex-grow border border-white/5 focus:outline-none focus:border-white/50"
                                            />
                                        </div>
                                        <button
                                            onClick={triggerGithubSync}
                                            disabled={isTriggeringGit}
                                            className="w-full mt-2 bg-white/5 hover:bg-white/10 disabled:opacity-50 text-white p-3 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all border border-white/10 flex items-center justify-center gap-2"
                                        >
                                            {isTriggeringGit ? (
                                                <>
                                                    <div className="w-3 h-3 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                                                    Iniciando...
                                                </>
                                            ) : (
                                                <>
                                                    <Shield size={14} className="text-white" />
                                                    Activar Sincronizaci├│n Manual (Actions)
                                                </>
                                            )}
                                        </button>
                                    </div>
                                    <div className="p-4 bg-slate-900/30 rounded-2xl border border-white/5 text-[9px] text-slate-500 leading-relaxed font-bold">
                                        Pega tu PAT de GitHub arriba para habilitar el bot├│n. El token se guarda localmente en tu navegador.
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
            </div>

            {showPriceHistory && (
                <PriceUpdateHistory onClose={() => setShowPriceHistory(false)} />
            )}

            {showLogModal && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/90 backdrop-blur-md">
                    <div className="glass-card border border-white/10 w-full max-w-4xl max-h-[85vh] rounded-[2rem] overflow-hidden flex flex-col shadow-[0_0_50px_rgba(0,0,0,0.5)]">
                        <div className="p-6 border-b border-white/5 flex items-center justify-between bg-white/5">
                            <h3 className="text-xl font-black italic tracking-tighter flex items-center gap-3 uppercase">
                                <Shield className="text-white w-6 h-6" />
                                Registros // {selectedTaskLog?.id}
                            </h3>
                            <button onClick={() => setShowLogModal(false)} className="text-slate-500 hover:text-white transition-colors bg-white/5 p-2 rounded-full">
                                <X size={20} />
                            </button>
                        </div>
                        <div className="p-8 bg-black/60 overflow-y-auto font-mono text-[11px] text-slate-300 whitespace-pre-wrap flex-grow custom-scrollbar">
                            {selectedTaskLog?.logs || 'Escaneando datos...'}
                        </div>
                        <div className="p-6 border-t border-white/5 flex justify-between items-center bg-white/5">
                            <span className="text-[10px] text-slate-600 font-black uppercase tracking-widest">Estado del Sistema: Activo</span>
                            <button
                                onClick={() => selectedTaskLog && fetchTaskLogs(selectedTaskLog.id)}
                                disabled={isRefreshingLogs}
                                className="bg-white text-black px-8 py-3 rounded-2xl font-black text-xs uppercase tracking-widest hover:scale-105 transition-all shadow-[0_0_20px_rgba(34,211,238,0.3)]"
                            >
                                {isRefreshingLogs ? 'Actualizando...' : 'Actualizar Registros'}
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

const StatCard = ({ title, value, change, icon }: { title: string, value: string, change: string, icon: React.ReactNode }) => (
    <div className="glass-card p-6 rounded-[2rem] border border-white/5 bg-slate-900/50 hover:border-white/30 transition-all group">
        <div className="flex items-center justify-between mb-4">
            <div className="w-12 h-12 bg-black/40 rounded-2xl flex items-center justify-center border border-white/5 group-hover:bg-white/10 transition-colors">
                {icon}
            </div>
            <span className="text-white text-[10px] font-black uppercase tracking-[0.2em] bg-white/10 px-3 py-1 rounded-full border border-white/20">{change}</span>
        </div>
        <h3 className="text-slate-500 text-[10px] font-black uppercase tracking-widest mb-1">{title}</h3>
        <p className="text-4xl font-black text-white italic tracking-tighter">{value}</p>
    </div>
);

const X = ({ size, className }: { size: number, className?: string }) => (
    <svg className={className} width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>
);

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { 
  Plus, 
  Trash2, 
  Save, 
  X, 
  Image as ImageIcon, 
  ChevronLeft, 
  Eye, 
  EyeOff,
  Link as LinkIcon
} from 'lucide-react';
import { adminFetchBanners, adminSaveBanner, adminDeleteBanner, uploadAsset } from '../../utils/api';

interface Banner {
  id?: string;
  title: string;
  subtitle: string;
  image_url: string;
  link_url: string;
  is_active: boolean;
  display_order: number;
  category: string;
  game_code?: string | null;
}


export const BannersPage: React.FC = () => {
  const navigate = useNavigate();
  const [banners, setBanners] = useState<Banner[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [editingBanner, setEditingBanner] = useState<Banner | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [uploading, setUploading] = useState(false);

  useEffect(() => {
    loadBanners();
  }, []);

  const loadBanners = async () => {
    try {
      setLoading(true);
      const data = await adminFetchBanners();
      // Only show global banners (game_code is null)
      setBanners((data || []).filter((b: any) => !b.game_code));
    } catch (error) {
      console.error('Error loading banners:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleCreate = () => {
    if (banners.length >= 5) {
      alert('Se ha alcanzado el l├¡mite m├íximo de 5 banners. Debes eliminar uno antes de crear otro.');
      return;
    }
    setEditingBanner({
      title: '',
      subtitle: '',
      image_url: '',
      link_url: '',
      is_active: true,
      display_order: banners.length,
      category: 'main_hero',
      game_code: null
    });
    setIsModalOpen(true);
  };

  const handleEdit = (banner: Banner) => {
    setEditingBanner({ ...banner });
    setIsModalOpen(true);
  };

  const handleDelete = async (id: string) => {
    if (!window.confirm('┬┐Est├ís seguro de eliminar este banner?')) return;
    try {
      await adminDeleteBanner(id);
      setBanners(banners.filter(b => b.id !== id));
    } catch (error) {
      console.error('Error deleting banner:', error);
      alert('Error al eliminar banner');
    }
  };

  const handleSave = async () => {
    if (!editingBanner || !editingBanner.image_url) {
      alert('La imagen es obligatoria');
      return;
    }

    try {
      setSaving(true);
      const saved = await adminSaveBanner(editingBanner);
      if (editingBanner.id) {
        setBanners(banners.map(b => b.id === saved.id ? saved : b));
      } else {
        setBanners([...banners, saved]);
      }
      setIsModalOpen(false);
      setEditingBanner(null);
    } catch (error) {
      console.error('Error saving banner:', error);
      alert('Error al guardar banner');
    } finally {
      setSaving(false);
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    try {
      setUploading(true);
      const url = await uploadAsset(file, 'banners');
      if (editingBanner) {
        setEditingBanner({ ...editingBanner, image_url: url });
      }
    } catch (error) {
      console.error('Upload failed:', error);
      alert('Error al subir imagen');
    } finally {
      setUploading(false);
    }
  };

  const toggleActive = async (banner: Banner) => {
    try {
      const updated = { ...banner, is_active: !banner.is_active };
      await adminSaveBanner(updated);
      setBanners(banners.map(b => b.id === banner.id ? updated : b));
    } catch (error) {
      console.error('Error toggling active:', error);
    }
  };

  return (
    <div className="min-h-screen bg-[#050505] text-white p-4 md:p-8 font-sans">
      <div className="max-w-7xl mx-auto">
        
        {/* Header */}
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-12">
          <div className="space-y-2">
            <button 
              onClick={() => navigate('/admin')}
              className="flex items-center gap-2 text-slate-500 hover:text-white transition-colors text-xs font-black uppercase tracking-widest group"
            >
              <ChevronLeft size={16} className="group-hover:-translate-x-1 transition-transform" />
              Volver al Panel
            </button>
            <h1 className="text-4xl md:text-5xl font-black italic tracking-tighter uppercase">
              Gesti├│n de <span className="text-white">Banners</span>
            </h1>
            <div className="flex items-center gap-2">
              <p className="text-slate-500 text-xs font-bold uppercase tracking-[0.2em]">Carrusel Promocional ({banners.length}/5)</p>
              <div className="flex gap-1">
                {[...Array(5)].map((_, i) => (
                  <div key={i} className={`w-3 h-1.5 rounded-full transition-colors ${i < banners.length ? 'bg-white' : 'bg-white/10'}`} />
                ))}
              </div>
            </div>
          </div>
          
          <button 
            onClick={handleCreate}
            className="flex items-center justify-center gap-3 bg-white text-black px-8 py-4 rounded-2xl font-black text-xs uppercase tracking-widest hover:scale-105 transition-all shadow-[0_0_30px_rgba(34,211,238,0.3)]"
          >
            <Plus size={18} />
            Nuevo Banner
          </button>
        </div>

        {/* Content */}
        {loading ? (
          <div className="flex flex-col items-center justify-center py-20 gap-4">
            <div className="w-12 h-12 border-4 border-white/20 border-t-white rounded-full animate-spin"></div>
            <p className="text-slate-500 font-black text-[10px] uppercase tracking-widest animate-pulse">Sincronizando Banners...</p>
          </div>
        ) : banners.length === 0 ? (
          <div className="text-center py-20 bg-slate-900/20 border-2 border-dashed border-white/5 rounded-[2.5rem]">
            <ImageIcon className="w-16 h-16 text-slate-700 mx-auto mb-4" />
            <h3 className="text-xl font-bold text-slate-500 uppercase tracking-tighter">No hay banners configurados</h3>
            <p className="text-slate-400 text-xs mt-2 font-medium">Crea el primer banner para empezar a promocionar tus productos.</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
            {banners.map((banner) => (
              <div 
                key={banner.id} 
                className="group relative bg-slate-900/40 border border-white/5 rounded-[2rem] overflow-hidden hover:border-white/30 transition-all flex flex-col"
              >
                {/* Preview Image */}
                <div className="aspect-video w-full relative overflow-hidden bg-black">
                  <img 
                    src={banner.image_url} 
                    alt={banner.title} 
                    className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700 opacity-60 group-hover:opacity-100"
                  />
                  <div className="absolute inset-0 bg-gradient-to-t from-black via-black/20 to-transparent" />
                  
                  {/* Status Badge */}
                  <div className="absolute top-4 right-4">
                    <button 
                      onClick={() => toggleActive(banner)}
                      className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest border transition-all shadow-lg ${
                        banner.is_active 
                          ? 'bg-white text-black border-cyan-400 shadow-cyan-500/20' 
                          : 'bg-slate-800 text-slate-400 border-white/10 shadow-black'
                      }`}
                    >
                      {banner.is_active ? (
                        <span className="flex items-center gap-1"><Eye size={12} /> ON</span>
                      ) : (
                        <span className="flex items-center gap-1"><EyeOff size={12} /> OFF</span>
                      )}
                    </button>
                  </div>

                  {/* Order Controls */}
                  <div className="absolute bottom-4 left-4 flex gap-2">
                    <div className="bg-black/60 backdrop-blur-md border border-white/10 px-3 py-1 rounded-lg text-[10px] font-black text-white">
                      # {banner.display_order}
                    </div>
                  </div>
                </div>

                {/* Content */}
                <div className="p-6 flex-1 flex flex-col justify-between">
                  <div>
                    <h3 className="text-lg font-black italic uppercase tracking-tighter mb-1 line-clamp-1">{banner.title || 'Sin T├¡tulo'}</h3>
                    <p className="text-slate-500 text-[10px] font-bold uppercase tracking-widest line-clamp-2 mb-4">{banner.subtitle || 'Sin Subt├¡tulo'}</p>
                    
                    {banner.link_url && (
                      <div className="flex items-center gap-2 text-[9px] text-slate-400 font-bold uppercase tracking-widest">
                        <LinkIcon size={12} className="text-white" />
                        <span className="truncate">{banner.link_url}</span>
                      </div>
                    )}
                  </div>

                  <div className="flex items-center gap-3 mt-6 pt-6 border-t border-white/5">
                    <button 
                      onClick={() => handleEdit(banner)}
                      className="flex-1 bg-white/5 hover:bg-white/10 border border-white/10 p-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all"
                    >
                      Editar
                    </button>
                    <button 
                      onClick={() => banner.id && handleDelete(banner.id)}
                      className="bg-red-500/10 hover:bg-red-500/20 border border-red-500/20 p-3 rounded-xl text-red-500 transition-all"
                    >
                      <Trash2 size={16} />
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}

        {/* Edit/Create Modal */}
        {isModalOpen && editingBanner && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/90 backdrop-blur-md">
            <div className="bg-[#0a0a0a] border border-white/10 w-full max-w-2xl rounded-[2.5rem] overflow-hidden shadow-2xl flex flex-col max-h-[90vh]">
              
              <div className="p-8 border-b border-white/5 flex items-center justify-between">
                <h3 className="text-2xl font-black italic uppercase tracking-tighter">
                  {editingBanner.id ? 'Editar' : 'Nuevo'} <span className="text-white">Banner</span>
                </h3>
                <button onClick={() => setIsModalOpen(false)} className="text-slate-500 hover:text-white transition-colors bg-white/5 p-2 rounded-full">
                  <X size={20} />
                </button>
              </div>

              <div className="p-8 overflow-y-auto space-y-6 custom-scrollbar">
                
                {/* Image Upload Area */}
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Imagen del Banner (1600x600 recomendado)</label>
                  <div className="relative aspect-video w-full rounded-2xl overflow-hidden bg-slate-900 border-2 border-dashed border-white/10 flex flex-col items-center justify-center gap-4 group">
                    {editingBanner.image_url ? (
                      <>
                        <img src={editingBanner.image_url} alt="Preview" className="w-full h-full object-cover" />
                        <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                          <label className="bg-white text-black px-6 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest cursor-pointer hover:scale-105 transition-all">
                            Cambiar Imagen
                            <input type="file" className="hidden" onChange={handleFileUpload} accept="image/*" />
                          </label>
                        </div>
                      </>
                    ) : (
                      <>
                        {uploading ? (
                          <div className="w-8 h-8 border-2 border-white/20 border-t-white rounded-full animate-spin"></div>
                        ) : (
                          <>
                            <ImageIcon className="text-slate-700" size={40} />
                            <label className="bg-white/5 hover:bg-white/10 border border-white/10 px-6 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest cursor-pointer transition-all">
                              Subir Imagen
                              <input type="file" className="hidden" onChange={handleFileUpload} accept="image/*" />
                            </label>
                          </>
                        )}
                      </>
                    )}
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">T├¡tulo Principal</label>
