import { useState, useEffect, useCallback } from "react";
import { 
    Search, Plus, Package, Trash2, Edit2, 
    ChevronLeft, ChevronRight
} from "lucide-react";
import { fetchAccessoriesAdmin, deleteAccessory, fetchAccessoryCategories, updateAccessory } from "../../utils/api";
import { EditProductModal } from "../../components/Admin/EditProductModal";
import { AddAccessoryDrawer } from "../../components/Admin/AddAccessoryDrawer";
import { BulkImportCatalogModal } from "../../components/Admin/BulkImportCatalogModal";
import BulkImageUploadModal from "../../components/Admin/BulkImageUploadModal";
import { FileUp, ImagePlus } from "lucide-react";

export default function CatalogPage() {
    const [items, setItems] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [isDrawerOpen, setIsDrawerOpen] = useState(false);
    const [isImportModalOpen, setIsImportModalOpen] = useState(false);
    const [isImageUploadModalOpen, setIsImageUploadModalOpen] = useState(false);
    const [isEditModalOpen, setIsEditModalOpen] = useState(false);
    const [selectedProduct, setSelectedProduct] = useState<any>(null);
    const [searchQuery, setSearchQuery] = useState("");
    const [page, setPage] = useState(0);
    const [totalCount, setTotalCount] = useState(0);
    const [lastSavedId, setLastSavedId] = useState<string | null>(null);

    const pageSize = 20;

    useEffect(() => {
        fetchAccessoryCategories();
    }, []);

    const loadAccessories = useCallback(async () => {
        setLoading(true);
        try {
            const { data, count } = await fetchAccessoriesAdmin({
                search: searchQuery,
                limit: pageSize,
                offset: page * pageSize
            });
            setItems(data || []);
            setTotalCount(count || 0);
        } catch (err) {
            console.error("Error loading accessories:", err);
        } finally {
            setLoading(false);
        }
    }, [searchQuery, page]);

    useEffect(() => {
        const timer = setTimeout(loadAccessories, 300);
        return () => clearTimeout(timer);
    }, [loadAccessories]);

    const handleDelete = async (id: string) => {
        if (!confirm("┬┐Est├ís seguro de eliminar este producto?")) return;
        try {
            await deleteAccessory(id);
            loadAccessories();
        } catch (err: any) {
            alert("Error al eliminar: " + err.message);
        }
    };

