                        >
                            <ImagePlus size={18} className="text-slate-500" />
                            Carga Masiva Im├ígenes
                        </button>
                        
                        <button
                            onClick={() => setIsDrawerOpen(true)}
                            className="px-8 py-4 bg-white text-black font-black text-xs uppercase tracking-widest rounded-2xl hover:bg-orange-500 transition-all active:scale-95 shadow-2xl flex items-center gap-3"
                        >
                            <Plus size={18} />
                            Nuevo Producto
                        </button>
                    </div>
                </div>

                {/* Filters */}
                <div className="bg-slate-900/50 border border-white/5 p-4 rounded-[2.5rem] backdrop-blur-xl">
                    <div className="relative group">
                        <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-600 group-focus-within:text-orange-500 transition-colors" size={20} />
                        <input
                            type="text"
                            placeholder="Buscar por nombre o categor├¡a..."
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                            className="w-full bg-black/40 border border-white/5 rounded-3xl pl-16 pr-6 py-5 text-sm text-white focus:outline-none focus:border-orange-500/50 transition-all placeholder:text-slate-700 font-bold"
                        />
                    </div>
                </div>

                {/* Table */}
                <div className="bg-slate-900/30 border border-white/5 rounded-[2.5rem] overflow-hidden shadow-2xl">
                    <table className="w-full text-left border-collapse">
                        <thead className="bg-black/40 border-b border-white/5">
                            <tr>
                                <th className="pl-8 py-6 font-black text-[10px] text-slate-500 uppercase tracking-widest">Producto / Item</th>
                                <th className="px-6 py-6 font-black text-[10px] text-slate-500 uppercase tracking-widest text-center">Categor├¡a</th>
                                <th className="px-6 py-6 font-black text-[10px] text-slate-500 uppercase tracking-widest text-right">Precio</th>
                                <th className="px-6 py-6 font-black text-[10px] text-slate-500 uppercase tracking-widest text-center">Stock</th>
                                <th className="px-6 py-6 font-black text-[10px] text-slate-500 uppercase tracking-widest text-center">Estado</th>
                                <th className="pr-8 py-6 font-black text-[10px] text-slate-500 uppercase tracking-widest text-right">Acciones</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-white/5">
                            {loading && items.length === 0 ? (
                                <tr>
                                    <td colSpan={6} className="py-32 text-center">
                                        <div className="w-12 h-12 border-4 border-orange-500/30 border-t-orange-500 rounded-full animate-spin mx-auto mb-4" />
                                        <span className="text-xs font-black uppercase tracking-widest text-slate-500">Sincronizando...</span>
                                    </td>
                                </tr>
                            ) : items.length === 0 ? (
                                <tr>
                                    <td colSpan={6} className="py-32 text-center grayscale opacity-30">
                                        <Package size={48} className="mx-auto mb-4" />
                                        <p className="text-sm font-black uppercase tracking-widest">No hay resultados</p>
                                    </td>
                                </tr>
                            ) : (
                                items.map((item) => (
                                    <tr key={item.id} className="group hover:bg-white/[0.02] transition-all">
                                        <td className="pl-8 py-6">
                                            <div className="flex items-center gap-4">
                                                <div className="w-12 h-12 bg-black rounded-xl overflow-hidden border border-white/10 shrink-0">
                                                    <img src={item.image_url || '/placeholder-accessory.png'} alt={item.name} className="w-full h-full object-cover" />
                                                </div>
                                                <div>
                                                    <p className="text-sm font-black italic text-white uppercase">{item.name}</p>
                                                    <p className="text-[10px] font-bold text-slate-500 uppercase tracking-tighter mt-1 line-clamp-1 max-w-xs">
                                                        {item.description || 'Sin descripci├│n'}
                                                    </p>
                                                </div>
                                            </div>
                                        </td>
                                        <td className="px-6 py-6 text-center">
                                            <span className="px-3 py-1 bg-white/5 rounded-full text-[10px] font-black uppercase tracking-widest text-slate-400 border border-white/5">
                                                {item.category}
                                            </span>
                                        </td>
                                        <td className="px-6 py-6 text-right">
                                            <div className="flex flex-col items-end">
                                                <span className="text-lg font-black font-mono tracking-tighter">
                                                    ${(item.original_price ?? item.price).toFixed(2)}
                                                </span>
                                                {item.discount_percentage > 0 && (
                                                    <span className="text-[10px] text-orange-500 font-mono mt-1 bg-orange-500/10 px-2 py-0.5 rounded border border-orange-500/20">
                                                        Venta: ${(item.price ?? 0).toFixed(2)}
                                                    </span>
                                                )}
                                            </div>
                                        </td>
                                        <td className="px-6 py-6 text-center">
                                            <span className={`px-2 py-1 rounded-lg text-[10px] font-black font-mono border ${
                                                item.stock > 10 
                                                ? 'bg-white/10 text-white border-white/20' 
                                                : item.stock > 0 
                                                ? 'bg-orange-500/10 text-orange-500 border-orange-500/20'
                                                : 'bg-rose-500/10 text-rose-500 border-rose-500/20'
                                            }`}>
                                                {item.stock}
                                            </span>
                                        </td>
                                        <td className="px-6 py-6 text-center">
                                            <button 
                                                onClick={async () => {
                                                    await updateAccessory(item.id, { is_active: !item.is_active });
                                                    loadAccessories();
                                                }}
                                                className={`px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-tighter border transition-all ${
                                                    item.is_active 
                                                    ? 'bg-white/10 text-white border-white/20' 
                                                    : 'bg-rose-500/10 text-rose-500 border-rose-500/20'
                                                }`}
                                            >
                                                {item.is_active ? 'Activo' : 'Inactivo'}
                                            </button>
                                        </td>
                                        <td className="pr-8 py-6 text-right">
                                            <div className="flex items-center justify-end gap-2">
                                                <button 
                                                    onClick={() => {
                                                        setSelectedProduct(item);
                                                        setIsEditModalOpen(true);
                                                    }}
                                                    className="p-3 bg-white/5 text-slate-400 hover:text-white hover:bg-white/10 rounded-xl transition-all"
                                                >
                                                    <Edit2 size={16} />
                                                </button>
                                                <button 
                                                    onClick={() => handleDelete(item.id)}
                                                    className="p-3 bg-red-500/10 text-red-500/70 hover:bg-red-500 hover:text-white rounded-xl transition-all"
                                                >
                                                    <Trash2 size={16} />
                                                </button>
                                            </div>
                                            {lastSavedId === item.id && <p className="text-[8px] font-black text-white uppercase mt-1 animate-pulse">Guardado</p>}
                                        </td>
                                    </tr>
                                ))
                            )}
                        </tbody>
                    </table>
                </div>

                {/* Pagination */}
                {totalCount > pageSize && (
                    <div className="flex items-center justify-center gap-4 pt-4">
                        <button 
                            disabled={page === 0}
                            onClick={() => setPage(p => p - 1)}
                            className="p-4 bg-white/5 rounded-2xl disabled:opacity-20 hover:bg-white/10 transition-all"
                        >
                            <ChevronLeft size={20} />
                        </button>
                        <span className="text-xs font-black uppercase tracking-widest text-slate-500">
                            P├ígina {page + 1} de {Math.ceil(totalCount / pageSize)}
                        </span>
                        <button 
                            disabled={(page + 1) * pageSize >= totalCount}
                            onClick={() => setPage(p => p + 1)}
                            className="p-4 bg-white/5 rounded-2xl disabled:opacity-20 hover:bg-white/10 transition-all"
                        >
                            <ChevronRight size={20} />
                        </button>
                    </div>
                )}
            </div>

            <AddAccessoryDrawer 
                isOpen={isDrawerOpen} 
                onClose={() => setIsDrawerOpen(false)} 
                onSuccess={loadAccessories} 
            />

            <BulkImportCatalogModal
                isOpen={isImportModalOpen}
                onClose={() => setIsImportModalOpen(false)}
                onSuccess={() => {
                    loadAccessories();
                }}
            />

            {isImageUploadModalOpen && (
                <BulkImageUploadModal
                    onClose={() => setIsImageUploadModalOpen(false)}
                    onSuccess={() => loadAccessories()}
                />
            )}

            <EditProductModal
                isOpen={isEditModalOpen}
                onClose={() => {
                    setIsEditModalOpen(false);
                    setSelectedProduct(null);
                }}
                onSuccess={() => {
                    if (selectedProduct) setLastSavedId(selectedProduct.id);
                    setTimeout(() => setLastSavedId(null), 3000);
                    loadAccessories();
                }}
                product={selectedProduct}
            />
        </div>
    );
}

import { useState, useEffect, useCallback } from "react";
import { supabase } from "../../utils/supabaseClient";
import { AddProductDrawer } from "../../components/Admin/AddProductDrawer";
import {
    Plus, Search, Trash2, Package, Save, X,
    ChevronUp, ChevronDown, ChevronLeft, Check,
    ArrowUpDown,
    FileUp, ArrowDownFromLine,
    Download, ShoppingCart, Sparkles, Tag, PackagePlus
} from "lucide-react";
import { ImportInventoryModal } from "../../components/Admin/ImportInventoryModal";
import { EgressInventoryModal } from "../../components/Admin/EgressInventoryModal";
import { OfferManagementModal } from "../../components/Admin/OfferManagementModal";
import { BulkRarityOfferModal } from "../../components/Admin/BulkRarityOfferModal";
import { useCart } from "../../context/CartContext";
import { useAuth } from "../../context/AuthContext";
import { addProductToCart, isDiscountActive, manageProductOffer } from "../../utils/api";

interface InventoryItem {
    product_id: string;
    printing_id: string;
    name: string;
    game: string;
    set_code: string;
    condition: string;
    finish: string;
    price: number;
    original_price: number;
    stock: number;
    image_url: string;
    rarity: string;
    updated_at: string;
    total_count: number;
    discount_percentage?: number;
    discount_end_date?: string;
}

type SortField = 'name' | 'price' | 'stock' | 'newest';
type SortOrder = 'asc' | 'desc';

export function InventoryPage() {
    // Core State
    const [items, setItems] = useState<InventoryItem[]>([]);
    const [loading, setLoading] = useState(true);
    const [isDrawerOpen, setIsDrawerOpen] = useState(false);
    const [isImportModalOpen, setIsImportModalOpen] = useState(false);
    const [isEgressModalOpen, setIsEgressModalOpen] = useState(false);
    const [isBulkRarityModalOpen, setIsBulkRarityModalOpen] = useState(false);

    // Filtering & Sorting
    const [searchQuery, setSearchQuery] = useState("");
    const [page, setPage] = useState(0);
    const [selectedCondition, setSelectedCondition] = useState<string | null>(null);
    const [selectedGame, setSelectedGame] = useState<string | null>(null);
    const [sortBy, setSortBy] = useState<SortField>('name');
    const [sortOrder, setSortOrder] = useState<SortOrder>('asc');
    const [isNewFilterActive, setIsNewFilterActive] = useState(false);

    // NEW: Catalog Suggestions State
    const [catalogResults, setCatalogResults] = useState<any[]>([]);
    const [prefillCard, setPrefillCard] = useState<any>(null);

    // UI State
    const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
    const [editingPriceId, setEditingPriceId] = useState<string | null>(null);
    const [tempPrice, setTempPrice] = useState<string>("");
    const [totalItems, setTotalItems] = useState(0);
    const [lastSavedId, setLastSavedId] = useState<string | null>(null);

    // Offer Management State
    const [selectedOfferProduct, setSelectedOfferProduct] = useState<InventoryItem | null>(null);

    // State for Stock Editing
    const [editingStockId, setEditingStockId] = useState<string | null>(null);
    const [tempStock, setTempStock] = useState<string>("");

    // Cart Integration
    const { activeCartName, currentIsPos } = useCart();
    const { session } = useAuth();
    const [addingId, setAddingId] = useState<string | null>(null);

    const pageSize = 50;

    const fetchInventory = useCallback(async () => {
        setLoading(true);
        try {
            const { data, error } = await supabase.rpc('get_inventory_list', {
                p_page: page,
                p_page_size: pageSize,
                p_search: searchQuery || null,
                p_game: selectedGame || null,
                p_condition: selectedCondition || null,
                p_sort_by: sortBy,
                p_sort_order: sortOrder,
                p_only_new: isNewFilterActive
            });

            if (error) throw error;

            if (data && data.length > 0) {
                setItems(data);
                setTotalItems(Number(data[0].total_count));
            } else {
                setItems([]);
                setTotalItems(0);
            }
        } catch (err) {
            console.error("Error fetching inventory:", err);
        } finally {
            setLoading(false);
        }

        // Fetch Catalog Recommendations if query exists and local results are few
        if (searchQuery && searchQuery.length >= 3) {
            try {
                const { data: catData } = await supabase
                    .from('card_printings')
                    .select(`
                        printing_id,
                        image_url,
                        cards!inner (
                            card_name
                        ),
                        sets!inner (
                            set_name,
                            set_code
                        )
                    `)
                    .ilike('cards.card_name', `%${searchQuery}%`)
                    .limit(4);
                setCatalogResults(catData || []);
            } catch (e) {
                console.error("Catalog fetch error:", e);
            }
        } else {
            setCatalogResults([]);
        }
    }, [page, searchQuery, selectedGame, selectedCondition, sortBy, sortOrder]);

    useEffect(() => {
        const debounce = setTimeout(fetchInventory, 300);
        return () => clearTimeout(debounce);
    }, [fetchInventory]);

    // Keyboard Shortcuts
    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            // Focus search with CMD/CTRL + K
            if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
                e.preventDefault();
                document.querySelector<HTMLInputElement>('input[placeholder*="Identify"]')?.focus();
            }
            // Close editing with Escape
            if (e.key === 'Escape') {
                setEditingPriceId(null);
            }
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, []);

    // Handlers
    const toggleSelectAll = () => {
        if (selectedIds.size === items.length) {
            setSelectedIds(new Set());
        } else {
            setSelectedIds(new Set(items.map(i => i.product_id)));
        }
    };

    const toggleSelect = (id: string) => {
        const next = new Set(selectedIds);
        if (next.has(id)) next.delete(id);
        else next.add(id);
        setSelectedIds(next);
    };

    const handleUpdateStock = async (productId: string, currentStock: number, delta: number) => {
        const newStock = Math.max(0, currentStock + delta);

        // Optimistic Update
        setItems(prev => prev.map(item =>
            item.product_id === productId ? { ...item, stock: newStock } : item
        ));

        try {
            const { error } = await supabase
                .from('products')
                .update({ stock: newStock })
                .eq('id', productId);

            if (error) throw error;

            setLastSavedId(productId);
            setTimeout(() => setLastSavedId(null), 2000);
        } catch (err: any) {
            alert("Error al actualizar el stock: " + err.message);
            fetchInventory(); // Revert
        }
    };

    const handleSavePrice = async (productId: string) => {
        const newPrice = parseFloat(tempPrice);
        if (isNaN(newPrice) || newPrice < 0) return;

        // Optimistic Update
        setItems(prev => prev.map(item =>
            item.product_id === productId ? { ...item, price: newPrice } : item
        ));
        setEditingPriceId(null);

        try {
            const { error } = await supabase
                .from('products')
                .update({ price: newPrice })
                .eq('id', productId);

            if (error) throw error;

            setLastSavedId(productId);
            setTimeout(() => setLastSavedId(null), 2000);
        } catch (err: any) {
            alert("Error al actualizar el precio: " + err.message);
            fetchInventory(); // Revert
        }
    };

    const handleSaveStock = async (productId: string) => {
        const newStock = parseInt(tempStock);
        if (isNaN(newStock) || newStock < 0) return;

        // Optimistic Update
        setItems(prev => prev.map(item =>
            item.product_id === productId ? { ...item, stock: newStock } : item
        ));
        setEditingStockId(null);

        try {
            const { error } = await supabase.rpc('update_product_stock', {
                p_product_id: productId,
                p_new_quantity: newStock
            });

            if (error) throw error;

            setLastSavedId(productId);
            setTimeout(() => setLastSavedId(null), 2000);
        } catch (err: any) {
            alert("Error al actualizar el stock: " + err.message);
            fetchInventory(); // Revert
        }
    };

    const handleBatchDelete = async () => {
        if (!confirm(`┬┐Est├ís seguro de que deseas eliminar ${selectedIds.size} art├¡culos?`)) return;

        setLoading(true);
        try {
            const { error } = await supabase
                .from('products')
                .delete()
                .in('id', Array.from(selectedIds));

            if (error) throw error;
            setSelectedIds(new Set());
            fetchInventory();
        } catch (err: any) {
            alert("Error en eliminaci├│n por lotes: " + err.message);
        } finally {
            setLoading(false);
        }
    };

    const handleBatchOdooSync = async () => {
        if (!confirm(`┬┐Est├ís seguro de que deseas sincronizar ${selectedIds.size} art├¡culos con Odoo?`)) return;

        setLoading(true);
        try {
            const selectedItems = items.filter(i => selectedIds.has(i.product_id));
            const API_BASE = import.meta.env.VITE_API_BASE || import.meta.env.VITE_SUPABASE_URL + '/functions/v1';
            
            const response = await fetch(`${API_BASE}/odoo-sync`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${session?.access_token}`
                },
                body: JSON.stringify({
                    action: 'sync_inventory',
                    payload: { items: selectedItems }
                })
            });

            if (!response.ok) {
                const err = await response.json().catch(() => ({}));
                throw new Error(err.error || response.statusText);
            }

            alert("┬íSincronizaci├│n con Odoo completada!");
            setSelectedIds(new Set());
        } catch (err: any) {
            alert("Error en sincronizaci├│n Odoo: " + err.message);
        } finally {
            setLoading(false);
        }
    };

    const handleBatchDiscount = async (apply: boolean) => {
        let pct = 0;
        let endDate = new Date().toISOString();
        
        if (apply) {
            const inputPct = prompt(`┬┐Qu├⌐ porcentaje de descuento aplicar a ${selectedIds.size} art├¡culos? (ej: 10 para 10%)`);
            if (!inputPct) return;
            pct = parseFloat(inputPct);
            if (isNaN(pct) || pct <= 0) return alert("Porcentaje inv├ílido");
            
            const days = prompt("┬┐Cu├íntos d├¡as durar├í la oferta?", "7");
            if (!days) return;
            const numDays = parseInt(days);
            if (isNaN(numDays) || numDays <= 0) return alert("D├¡as inv├ílidos");
            
            const date = new Date();
            date.setDate(date.getDate() + numDays);
            endDate = date.toISOString().split('T')[0] + "T23:59:59.999-04:00";
        } else {
            if (!confirm(`┬┐Remover ofertas de ${selectedIds.size} art├¡culos?`)) return;
        }

        setLoading(true);
        try {
            const selectedItems = items.filter(i => selectedIds.has(i.product_id));
            
            // Apply offers sequentially or via Promise.all to ensure all go through
            await Promise.all(selectedItems.map(item => 
                manageProductOffer(item.product_id, pct, endDate)
            ));

            setSelectedIds(new Set());
            fetchInventory();
        } catch (err: any) {
            alert("Error en actualizaci├│n de descuentos por lotes: " + err.message);
        } finally {
            setLoading(false);
        }
    };

    const toggleSort = (field: SortField) => {
        if (sortBy === field) {
            setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc');
        } else {
            setSortBy(field);
            setSortOrder('asc');
        }
        setPage(0);
    };

    const handleAddToCart = async (item: InventoryItem) => {
        if (!activeCartName) return;
        
        setAddingId(item.product_id);
        try {
            const result = await addProductToCart(item.product_id, 1);
            if (result && !result.success) {
                alert(result.message || "Error al agregar al carrito");
            }
        } catch (err) {
            console.error("Add to cart error:", err);
        } finally {
            setAddingId(null);
        }
    };

    const handleExportInventory = async () => {
        try {
            const { data, error } = await supabase.rpc('get_inventory_for_export');
            if (error) throw error;
            if (!data || data.length === 0) {
                alert("No hay inventario para exportar.");
                return;
            }

            const headers = ['name', 'set_code', 'collector', 'condition', 'finish', 'qty'];
            // Map RPC result properties (out_ prefixed) back to the expected CSV headers
            const csvRows = [
                headers.join(','),
                ...data.map((row: any) => 
                    headers.map(fieldName => {
                        const rpcKey = `out_${fieldName}`;
                        const val = row[rpcKey] ?? "";
                        const stringVal = String(val).includes(',') ? `"${val}"` : String(val);
                        return stringVal;
                    }).join(',')
                )
            ];

            const csvContent = csvRows.join('\n');
            const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
            const url = URL.createObjectURL(blob);
            const link = document.createElement('a');
            link.setAttribute('href', url);
            link.setAttribute('download', `Geekorium_Inventario_${new Date().toISOString().split('T')[0]}.csv`);
            link.style.visibility = 'hidden';
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
        } catch (err: any) {
            console.error("Export error:", err);
            alert("Error al exportar inventario: " + err.message);
        }
    };

    return (
        <div className="min-h-screen bg-[#050505] text-white font-sans selection:bg-purple-500/30">
            <div className="max-w-[1600px] mx-auto p-4 md:p-8 space-y-8">

                {/* Header */}
                <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
                    <div className="space-y-2">
                        <div className="flex items-center gap-3">
                            <div className="w-12 h-12 bg-gradient-to-br from-purple-500 to-pink-600 rounded-2xl flex items-center justify-center shadow-lg shadow-purple-500/20">
                                <Package className="text-white" size={24} />
                            </div>
                            <h1 className="text-4xl font-black italic tracking-tighter uppercase">
                                Inventario <span className="text-purple-500">Global</span>
                            </h1>
                        </div>
                        <p className="text-neutral-500 text-xs font-bold uppercase tracking-[0.2em] ml-1">
                            Terminal del Sistema v2.1 ΓÇó {totalItems} Nodos ├Ünicos Indexados
                        </p>
                    </div>

                    <div className="flex flex-wrap items-center gap-3">
                        <a
                            href="/admin"
                            className="group relative px-6 py-4 bg-neutral-900 border border-white/10 text-white font-black text-xs uppercase tracking-[0.2em] rounded-2xl overflow-hidden active:scale-95 transition-all w-full md:w-auto hover:bg-neutral-800 flex items-center gap-2"
                        >
                            <ChevronLeft size={18} />
                            Volver al Panel
                        </a>

                        <button
                            onClick={() => setIsDrawerOpen(true)}
                            className="group relative px-8 py-4 bg-white text-black font-black text-xs uppercase tracking-[0.2em] rounded-2xl overflow-hidden active:scale-95 transition-all w-full md:w-auto shadow-2xl shadow-white/5"
                        >
                            <span className="relative z-10 flex items-center gap-3">
                                <Plus size={18} />
                                Agregar Producto
                            </span>
                            <div className="absolute inset-0 bg-purple-500 translate-y-full group-hover:translate-y-0 transition-transform duration-300" />
                        </button>

                        <button
                            onClick={() => setIsImportModalOpen(true)}
                            className="group relative px-6 py-4 bg-black border border-white/10 text-white font-black text-xs uppercase tracking-[0.2em] rounded-2xl overflow-hidden active:scale-95 transition-all w-full md:w-auto hover:border-purple-500/50"
                        >
                            <span className="relative z-10 flex items-center gap-3">
                                <FileUp size={18} className="text-neutral-500 group-hover:text-purple-400 transition-colors" />
                                Ingreso (Lote)
                            </span>
                        </button>

                        <button
                            onClick={handleExportInventory}
                            className="group relative px-6 py-4 bg-black border border-white/10 text-white font-black text-xs uppercase tracking-[0.2em] rounded-2xl overflow-hidden active:scale-95 transition-all w-full md:w-auto hover:border-white/50"
                            title="Descargar inventario actual"
                        >
                            <span className="relative z-10 flex items-center gap-3">
                                <Download size={18} className="text-white/70 group-hover:text-white transition-colors" />
                                Exportar
                            </span>
                        </button>

                        <button
                            onClick={() => setIsEgressModalOpen(true)}
                            className="group relative px-6 py-4 bg-black border border-white/10 text-rose-500 font-black text-xs uppercase tracking-[0.2em] rounded-2xl overflow-hidden active:scale-95 transition-all w-full md:w-auto hover:border-rose-500/50"
                        >
                            <span className="relative z-10 flex items-center gap-3">
                                <ArrowDownFromLine size={18} className="text-rose-500/70 group-hover:text-rose-400 transition-colors" />
                                Egreso (Lote)
                            </span>
                        </button>

                        <button
                            onClick={() => setIsBulkRarityModalOpen(true)}
                            className="group relative px-6 py-4 bg-purple-900/20 border border-purple-500/30 text-purple-400 font-black text-xs uppercase tracking-[0.2em] rounded-2xl overflow-hidden active:scale-95 transition-all w-full md:w-auto hover:border-purple-500/70 hover:bg-purple-900/40"
                        >
                            <span className="relative z-10 flex items-center gap-3">
                                <Sparkles size={18} className="text-purple-400/70 group-hover:text-purple-300 transition-colors" />
                                Ofertas (Bulk)
                            </span>
                        </button>
                    </div>
                </div>

                {/* Filters Row */}
                <div className="grid grid-cols-1 lg:grid-cols-12 gap-4 items-center bg-neutral-900/50 border border-white/5 p-4 rounded-[2rem] backdrop-blur-xl">
                    <div className="lg:col-span-5 relative group">
                        <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-neutral-600 group-focus-within:text-purple-500 transition-colors" size={20} />
                        <input
                            type="text"
                            placeholder="Identificar Carta por Nombre..."
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                            className="w-full bg-black/40 border border-white/5 rounded-2xl pl-12 pr-4 py-4 text-sm text-white focus:outline-none focus:border-purple-500/50 transition-all placeholder:text-neutral-700 font-medium"
                        />
                    </div>

                    <div className="lg:col-span-7 flex flex-wrap items-center gap-3">
                        {/* 
                        <div className="flex bg-black/40 p-1 rounded-2xl border border-white/5">
                            {['Magic', 'Pokemon', 'One Piece'].map(game => (
                                <button
                                    key={game}
                                    onClick={() => setSelectedGame(selectedGame === game ? null : game)}
                                    className={`px-4 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${selectedGame === game
                                        ? 'bg-purple-500 text-white shadow-lg shadow-purple-500/20'
                                        : 'text-neutral-500 hover:text-neutral-300'
                                        }`}
                                >
                                    {game}
                                </button>
                            ))}
                        </div> 
                        */}

                        <select
                            value={selectedCondition || ""}
                            onChange={(e) => setSelectedCondition(e.target.value || null)}
                            className="flex-1 lg:flex-none bg-black/40 border border-white/5 rounded-2xl px-4 py-4 text-[10px] font-black uppercase tracking-widest text-neutral-400 focus:outline-none focus:border-purple-500/50"
                        >
                            <option value="">Estado: Todas las Condiciones</option>
                            <option value="NM">Mint/NM</option>
                            <option value="LP">Lightly Played (LP)</option>
                            <option value="MP">Moderately Played (MP)</option>
                            <option value="HP">Heavily Played (HP)</option>
                            <option value="DMG">Da├▒ada (DMG)</option>
                        </select>

                        <button
                            onClick={() => {
                                setIsNewFilterActive(!isNewFilterActive);
                                setPage(0);
                            }}
                            className={`flex items-center gap-2 px-4 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all border ${
                                isNewFilterActive 
                                    ? 'bg-purple-500 border-purple-500 text-white shadow-lg shadow-purple-500/20' 
                                    : 'bg-black/40 border-white/5 text-neutral-400 hover:border-purple-500/30'
                            }`}
                        >
                            <Sparkles size={14} className={isNewFilterActive ? 'animate-pulse' : ''} />
                            Nuevo
                        </button>

                        <button
                            onClick={() => {
                                setSearchQuery("");
                                setSelectedGame(null);
                                setSelectedCondition(null);
                                setIsNewFilterActive(false);
                                setPage(0);
                            }}
                            className="p-4 bg-white/5 hover:bg-white/10 rounded-2xl text-neutral-500 hover:text-white transition-all border border-white/5"
                            title="Reiniciar Filtros"
                        >
                            <X size={20} />
                        </button>
                    </div>
                </div>

                {/* Batch Actions Bar (Sticky) */}
                {selectedIds.size > 0 && (
                    <div className="sticky top-4 z-40 animate-in slide-in-from-top-4 duration-500">
                        <div className="bg-purple-600 rounded-3xl p-4 flex items-center justify-between shadow-[0_20px_40px_rgba(147,51,234,0.3)]">
                            <div className="flex items-center gap-6 ml-4">
                                <div className="flex flex-col">
                                    <span className="text-[10px] font-black text-white/60 uppercase tracking-widest">Nodos Seleccionados</span>
                                    <span className="text-lg font-black italic">{selectedIds.size} Art├¡culos</span>
                                </div>
                                <div className="h-8 w-px bg-white/20" />
                                <div className="flex items-center gap-2">
                                    <button
                                        onClick={() => handleBatchDiscount(true)}
                                        className="bg-purple-500 hover:bg-purple-600 px-4 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all shadow-lg shadow-purple-500/20 text-white flex items-center gap-2"
                                    >
                                        <Tag size={12} />
                                        Aplicar Oferta Lote
                                    </button>
                                    <button
                                        onClick={() => handleBatchDiscount(false)}
                                        className="bg-white/10 hover:bg-white/20 px-4 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all text-white flex items-center gap-2"
                                    >
                                        <X size={12} />
                                        Remover Ofertas Lote
                                    </button>
                                </div>
                            </div>

                            <div className="flex items-center gap-3">
                                <button
                                    onClick={handleBatchOdooSync}
                                    className="bg-blue-500 hover:bg-blue-600 px-6 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all flex items-center gap-2"
                                >
                                    <PackagePlus size={14} /> Sync Odoo
                                </button>
                                <button
                                    onClick={handleBatchDelete}
                                    className="bg-red-500 hover:bg-red-600 px-6 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all flex items-center gap-2"
                                >
                                    <Trash2 size={14} /> Eliminar Selecci├│n
                                </button>
                                <button
                                    onClick={() => setSelectedIds(new Set())}
                                    className="p-3 text-white/60 hover:text-white transition-all"
                                >
                                    <X size={20} />
                                </button>
                            </div>
                        </div>
                    </div>
                )}

                {/* Main Table Content */}
                <div className="relative bg-[#0a0a0a] border border-white/5 rounded-[2.5rem] overflow-hidden shadow-2xl">
                    {loading && items.length === 0 ? (
                        <div className="flex flex-col items-center justify-center h-[500px] gap-4">
                            <div className="w-12 h-12 border-4 border-purple-500/30 border-t-purple-500 rounded-full animate-spin" />
                            <span className="font-black text-xs uppercase tracking-[0.3em] text-neutral-500">Escaneando Base de Datos...</span>
                        </div>
                    ) : items.length === 0 ? (
                        <div className="flex flex-col items-center justify-center min-h-[500px] p-8 space-y-12">
                            <div className="flex flex-col items-center justify-center grayscale opacity-30 gap-6">
                                <Package size={80} />
                                <div className="text-center space-y-2">
                                    <p className="text-xl font-black italic uppercase tracking-tighter">Nodo de Inventario Vac├¡o</p>
                                    <p className="text-xs uppercase tracking-widest font-bold">Consulta: "{searchQuery}" no encontrada en el almac├⌐n local</p>
                                </div>
                            </div>

                            {/* Catalog Suggestions */}
                            {catalogResults.length > 0 && (
                                <div className="w-full max-w-4xl space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-700">
                                    <div className="flex items-center gap-4">
                                        <div className="h-px flex-1 bg-gradient-to-r from-transparent to-white/10" />
                                        <h3 className="text-[10px] font-black text-purple-400 uppercase tracking-[0.3em]">Encontrado en Cat├ílogo Global</h3>
                                        <div className="h-px flex-1 bg-gradient-to-l from-transparent to-white/10" />
                                    </div>

                                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                                        {catalogResults.map((cat) => (
                                            <div key={cat.printing_id} className="bg-white/5 border border-white/5 rounded-2xl p-4 flex flex-col items-center gap-4 group hover:border-purple-500/30 transition-all">
                                                <div className="relative w-20 h-28 bg-black rounded-xl overflow-hidden shadow-2xl transition-transform group-hover:scale-105">
                                                    <img src={cat.image_url} alt={cat.cards.card_name} className="w-full h-full object-cover" />
                                                </div>
                                                <div className="text-center min-w-0 w-full">
                                                    <div className="text-xs font-black text-white italic truncate tracking-tight lowercase">{cat.cards.card_name}</div>
                                                    <div className="text-[8px] text-neutral-500 font-black uppercase tracking-widest mt-1">{cat.sets.set_code}</div>
                                                </div>
                                                <button
                                                    onClick={() => {
                                                        setPrefillCard(cat);
                                                        setIsDrawerOpen(true);
                                                    }}
                                                    className="w-full py-2 bg-purple-500 hover:bg-purple-600 text-white text-[9px] font-black uppercase tracking-widest rounded-lg transition-all shadow-lg shadow-purple-500/20"
                                                >
                                                    Agregar al Stock
                                                </button>
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            )}
                        </div>
                    ) : (
                        <div className="overflow-x-auto">
                            <table className="w-full text-left border-collapse">
                                <thead className="bg-[#0f0f0f] border-b border-white/5">
                                    <tr>
                                        <th className="pl-8 py-6 w-12">
                                            <button
                                                onClick={toggleSelectAll}
                                                className={`w-5 h-5 rounded border transition-all flex items-center justify-center ${selectedIds.size === items.length && items.length > 0
                                                    ? 'bg-purple-500 border-purple-500'
                                                    : 'bg-black border-white/10 hover:border-purple-500/50'
                                                    }`}
                                            >
                                                {selectedIds.size === items.length && <Check size={14} />}
                                            </button>
                                        </th>
                                        <th className="px-6 py-6 font-black text-[10px] text-neutral-500 uppercase tracking-widest">
                                            <button onClick={() => toggleSort('name')} className="flex items-center gap-2 hover:text-white transition-colors">
                                                Identificaci├│n de Entidad <ArrowUpDown size={12} className={sortBy === 'name' ? 'text-purple-500' : ''} />
                                            </button>
                                        </th>
                                        <th className="px-6 py-6 font-black text-[10px] text-neutral-500 uppercase tracking-widest text-center">Calidad</th>
                                        <th className="px-6 py-6 font-black text-[10px] text-neutral-500 uppercase tracking-widest text-right">
                                            <button onClick={() => toggleSort('price')} className="flex items-center gap-2 justify-end float-right hover:text-white transition-colors">
                                                Valoraci├│n <ArrowUpDown size={12} className={sortBy === 'price' ? 'text-purple-500' : ''} />
                                            </button>
                                        </th>
                                        <th className="px-6 py-6 font-black text-[10px] text-neutral-500 uppercase tracking-widest text-center">Descuento %</th>
                                        <th className="px-6 py-6 font-black text-[10px] text-neutral-500 uppercase tracking-widest text-center">Oferta Hasta</th>
                                        <th className="px-6 py-6 font-black text-[10px] text-neutral-500 uppercase tracking-widest text-center">
                                            <button onClick={() => toggleSort('stock')} className="flex items-center gap-2 justify-center mx-auto hover:text-white transition-colors">
                                                Nodos de Stock <ArrowUpDown size={12} className={sortBy === 'stock' ? 'text-purple-500' : ''} />
                                            </button>
                                        </th>
                                        <th className="px-6 py-6 font-black text-[10px] text-neutral-500 uppercase tracking-widest text-center">Venta</th>
                                        <th className="pr-8 py-6 font-black text-[10px] text-neutral-500 uppercase tracking-widest text-right">Ops</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-white/5 bg-[#080808]/50">
                                    {items.map((item) => (
                                        <tr key={item.product_id} className={`group hover:bg-white/[0.02] transition-colors relative ${selectedIds.has(item.product_id) ? 'bg-purple-500/5' : ''}`}>
                                            <td className="pl-8 py-4">
                                                <button
                                                    onClick={() => toggleSelect(item.product_id)}
                                                    className={`w-5 h-5 rounded border transition-all flex items-center justify-center ${selectedIds.has(item.product_id)
                                                        ? 'bg-purple-500 border-purple-500'
                                                        : 'bg-black border-white/10 hover:border-purple-500/50'
                                                        }`}
                                                >
                                                    {selectedIds.has(item.product_id) && <Check size={14} />}
                                                </button>
                                            </td>
                                            <td className="px-6 py-4">
                                                <div className="flex items-center gap-4">
                                                    <div className="relative w-12 h-16 bg-black rounded-xl overflow-hidden shadow-2xl border border-white/5 transition-transform group-hover:scale-105 group-hover:-rotate-3">
                                                        <img src={item.image_url} alt={item.name} className="w-full h-full object-cover" loading="lazy" />
                                                    </div>
                                                    <div className="flex flex-col min-w-0 max-w-[200px] md:max-w-md">
                                                        <span className="text-sm font-black text-white italic tracking-tight lowercase truncate">
                                                            {item.name}
                                                            {item.set_code && ['msh', 'msc', 'mar'].includes(item.set_code.toLowerCase()) && (
                                                                <span className="ml-2 items-center px-1.5 py-0.5 bg-gradient-to-r from-purple-500 to-pink-500 text-[7px] font-black uppercase rounded shadow-lg shadow-purple-500/20 animate-in fade-in zoom-in duration-500">Nuevo</span>
                                                            )}
                                                        </span>
                                                        <div className="flex items-center gap-2 mt-1">
                                                            <span className="text-[9px] font-black text-neutral-600 uppercase tracking-widest px-2 py-0.5 bg-white/5 rounded-md">
