                prefillCard={prefillCard}
                onSuccess={() => fetchInventory()}
            />

            <ImportInventoryModal
                isOpen={isImportModalOpen}
                onClose={() => setIsImportModalOpen(false)}
                onSuccess={() => {
                    fetchInventory();
                }}
            />

            <EgressInventoryModal
                isOpen={isEgressModalOpen}
                onClose={() => setIsEgressModalOpen(false)}
                onSuccess={() => {
                    fetchInventory();
                }}
            />

            <BulkRarityOfferModal
                isOpen={isBulkRarityModalOpen}
                onClose={() => setIsBulkRarityModalOpen(false)}
                gameCode={selectedGame || undefined}
                onSuccess={() => {
                    fetchInventory();
                }}
            />

            {selectedOfferProduct && (
                <OfferManagementModal
                    isOpen={!!selectedOfferProduct}
                    onClose={() => setSelectedOfferProduct(null)}
                     productId={selectedOfferProduct.product_id}
                     productName={selectedOfferProduct.name}
                     currentPrice={selectedOfferProduct.price || 0}
                     initialDiscountPercentage={selectedOfferProduct.discount_percentage}
                     initialDiscountEndDate={selectedOfferProduct.discount_end_date}
                     onSuccess={() => {
                        fetchInventory();
                        setSelectedOfferProduct(null);
                    }}
                />
            )}
        </div>
    );
}

