import { useState, useEffect } from 'react';
import { supabase } from '../../utils/supabaseClient';
import { Image, Trash2, Copy, ChevronLeft, RefreshCw, Folder, ImagePlus } from 'lucide-react';
import BulkImageUploadModal from '../../components/Admin/BulkImageUploadModal';

interface StorageFile {
    name: string;
    id: string;
    updated_at: string;
    created_at: string;
    last_accessed_at: string;
    metadata: {
        size: number;
        mimetype: string;
    };
    publicUrl: string;
}

export default function MediaPage() {
    const [files, setFiles] = useState<StorageFile[]>([]);
    const [loading, setLoading] = useState(true);
    const [folder, setFolder] = useState<'accessories' | 'banners'>('accessories');
    const [isUploadModalOpen, setIsUploadModalOpen] = useState(false);

    const loadFiles = async () => {
        setLoading(true);
        try {
            const { data, error } = await supabase.storage
                .from('public_assets')
                .list(folder, {
                    limit: 200, // Fetch up to 200 latest files
                    offset: 0,
                    sortBy: { column: 'created_at', order: 'desc' },
                });

            if (error) throw error;

            // Map public URLs
            const mappedFiles = (data || []).filter((f: any) => f.name !== '.emptyFolderPlaceholder').map((f: any) => {
                const { data: urlData } = supabase.storage.from('public_assets').getPublicUrl(`${folder}/${f.name}`);
                return {
                    ...f,
                    publicUrl: urlData.publicUrl
                };
            });

            setFiles(mappedFiles as StorageFile[]);
        } catch (err: any) {
            console.error('Error fetching media:', err);
            alert('Error al cargar la galer├¡a: ' + err.message);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        loadFiles();
    }, [folder]);

    const handleDelete = async (fileName: string) => {
        if (!confirm(`ΓÜá∩╕Å ALERTA: ┬┐Est├ís seguro de borrar "${fileName}"?\n\nSi alg├║n producto en el cat├ílogo est├í usando esta imagen, se romper├í su enlace visual y se ver├í en blanco.`)) {
            return;
        }

        try {
            const { error } = await supabase.storage
                .from('public_assets')
                .remove([`${folder}/${fileName}`]);

            if (error) throw error;
            
            // Remove from state
            setFiles(prev => prev.filter(f => f.name !== fileName));
        } catch (err: any) {
            alert('Error al eliminar archivo: ' + err.message);
        }
    };

    const handleCopyUrl = (url: string) => {
        navigator.clipboard.writeText(url);
    };

    const formatBytes = (bytes: number, decimals = 2) => {
        if (!+bytes) return '0 Bytes';
        const k = 1024;
        const dm = decimals < 0 ? 0 : decimals;
        const sizes = ['Bytes', 'KB', 'MB', 'GB'];
        const i = Math.floor(Math.log(bytes) / Math.log(k));
        return `${parseFloat((bytes / Math.pow(k, i)).toFixed(dm))} ${sizes[i]}`;
    };

    return (
        <div className="min-h-screen bg-slate-950 text-white p-8">
            <div className="max-w-[1400px] mx-auto space-y-8">
                
