                                        title="Borrar Archivo"
                                    >
                                        <Trash2 size={16} />
                                    </button>
                                </div>
                            </div>
                        ))}
                    </div>
                )}
            </div>

            {isUploadModalOpen && (
                <BulkImageUploadModal
                    onClose={() => setIsUploadModalOpen(false)}
                    onSuccess={() => {
                        loadFiles();
                    }}
                />
            )}
        </div>
    );
}

