const OrdersPage = () => {
    const { isAdmin } = useAuth();
    const [orders, setOrders] = useState<Order[]>([]);
    const [loading, setLoading] = useState(true);
    const [expandedOrderId, setExpandedOrderId] = useState<string | null>(null);


    const [updatingId, setUpdatingId] = useState<string | null>(null);
    const [deletingId, setDeletingId] = useState<string | null>(null);
    const [filterStatus, setFilterStatus] = useState<string>('all');
    const [showDeleted, setShowDeleted] = useState(false);
    const [removingItemId, setRemovingItemId] = useState<string | null>(null);
    const [confirmingItemId, setConfirmingItemId] = useState<string | null>(null);

    const filteredOrders = orders.filter(order => {
        if (!showDeleted && order.deleted_at) return false;
        if (showDeleted && !order.deleted_at) return false; // Show ONLY deleted if toggled? Or include? usually separate view.
        // Let's make it toggle include/exclude or show/hide.
        // Interpretation: "Soft Delete" usually means hidden by default.
        if (filterStatus !== 'all' && order.status !== filterStatus) return false;
        return true;
    });

    useEffect(() => {
        if (isAdmin) {
            fetchOrders();
        }
    }, [isAdmin]);

    const fetchOrders = async () => {
        setLoading(true);
        try {
            const { data, error } = await supabase
                .from('orders')
                .select(`
                    *,
                    order_items (
                        id,
                        quantity,
                        price_at_purchase,
                        product:products (
                            id,
                            name,
                            image_url,
                            set_code
                        ),
                        finish,
                        is_on_demand
                    )
                `)
                .order('created_at', { ascending: false });

            if (error) throw error;
            setOrders(data || []);
        } catch (err: any) {
            console.error("Error fetching orders:", err);
            alert("Error al obtener las ├│rdenes: " + err.message);
        } finally {
            setLoading(false);
        }
    };

    const handleStatusChange = async (orderId: string, newStatus: string) => {
        // Confirmation for critical actions
        if (newStatus === 'cancelled' || newStatus === 'returned') {
            if (!confirm(`┬┐Est├ís seguro de que deseas cambiar el estado a ${ORDER_STATUSES[newStatus].label}? Esto RESTAURAR├ü el stock de los art├¡culos.`)) return;
        } else if (newStatus === 'pending_payment' || newStatus === 'paid') {
            // If restoring from cancelled
            const currentOrder = orders.find(o => o.id === orderId);
            if (currentOrder?.status === 'cancelled' || currentOrder?.status === 'returned') {
                if (!confirm(`Restaurar esta orden DEDUCIR├ü stock. ┬┐Continuar?`)) return;
            }
        }

        setUpdatingId(orderId);
        try {
            const { data, error } = await supabase.rpc('update_order_status', {
                p_order_id: orderId,
                p_new_status: newStatus
            });

            if (error) throw error;
            if (!data.success) throw new Error(data.error);

            setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status: newStatus } : o));
        } catch (err: any) {
            alert("Error al actualizar el estado: " + err.message);
            fetchOrders(); // Revert/Refresh
        } finally {
            setUpdatingId(null);
        }
    };

    const toggleExpand = (orderId: string) => {
        setExpandedOrderId(expandedOrderId === orderId ? null : orderId);
    };

    const handleRemoveItem = async (orderId: string, itemId: string) => {
        console.log('handleRemoveItem initiated for item:', itemId, 'order:', orderId);
        
        setRemovingItemId(itemId);
        try {
            console.log('Calling Supabase RPC delete_order_item_v1...');
            const { data, error } = await supabase.rpc('delete_order_item_v1', {
                p_order_item_id: itemId
            });

            if (error) {
                console.error('RPC Error:', error);
                throw error;
            }
            if (!data.success) {
                console.error('RPC Business Logic Error:', data.error);
                throw new Error(data.error);
            }

            console.log('RPC Success! New total:', data.new_total);

            // Update local state
            setOrders(prev => {
                const updated = prev.map(order => {
                    if (order.id === orderId) {
                        return {
                            ...order,
                            total_amount: data.new_total,
                            order_items: order.order_items.filter(item => item.id !== itemId)
                        };
                    }
                    return order;
                });
                console.log('Local state updated. Remaining items in order:', 
                    updated.find(o => o.id === orderId)?.order_items.length);
                return updated;
            });
        } catch (err: any) {
            console.error("Critical error in handleRemoveItem:", err);
            alert("Error al eliminar el art├¡culo: " + err.message);
        } finally {
            setRemovingItemId(null);
            setConfirmingItemId(null);
        }
    };

    if (!isAdmin) return <div className="p-8 text-white">Acceso Denegado</div>;

    return (
        <div className="min-h-screen bg-[#050505] text-white font-sans selection:bg-white/30">
            <div className="max-w-[1600px] mx-auto p-4 md:p-8 space-y-8">

                {/* Header */}
                <div className="flex items-center justify-between">
                    <div className="space-y-2">
                        <div className="flex items-center gap-3">
                            <div className="w-12 h-12 bg-gradient-to-br from-white to-cyan-600 rounded-2xl flex items-center justify-center shadow-lg shadow-white/20">
                                <Package className="text-white" size={24} />
                            </div>
                            <h1 className="text-4xl font-black italic tracking-tighter uppercase">
                                Gesti├│n de <span className="text-white">├ôrdenes</span>
                            </h1>
                        </div>
                        <p className="text-neutral-500 text-xs font-bold uppercase tracking-[0.2em] ml-1">
                            Terminal del Sistema v2.1 ΓÇó {filteredOrders.length} ├ôrdenes
                        </p>
                    </div>
                    <div className="flex items-center gap-4">
                        <div className="flex items-center gap-2">
                            <label className="text-[10px] font-bold uppercase text-neutral-500 flex items-center gap-2 cursor-pointer select-none">
                                <input
                                    type="checkbox"
                                    checked={showDeleted}
                                    onChange={(e) => setShowDeleted(e.target.checked)}
                                    className="accent-red-500"
                                />
                                Mostrar Eliminados
                            </label>
                        </div>
                        <select
                            value={filterStatus}
                            onChange={(e) => setFilterStatus(e.target.value)}
                            className="bg-neutral-900 text-white text-xs font-bold uppercase tracking-widest px-4 py-3 rounded-xl border border-white/10 outline-none focus:border-white/50 transition-all hover:bg-white/5 cursor-pointer appearance-none"
                        >
                            <option value="all">TODOS LOS ESTADOS</option>
                            {Object.entries(ORDER_STATUSES).map(([key, config]) => (
                                <option key={key} value={key}>{config.label.toUpperCase()}</option>
                            ))}
                        </select>
                        <Link to="/admin" className="px-6 py-3 bg-white/5 hover:bg-white/10 rounded-xl text-xs font-black uppercase tracking-widest transition-all">
                            Volver al Panel
                        </Link>
                    </div>
                </div>

                {/* Orders List */}
                <div className="space-y-4">
                    {loading ? (
                        <div className="text-center py-20 text-neutral-500 animate-pulse">Cargando ├│rdenes...</div>
                    ) : filteredOrders.length === 0 ? (
                        <div className="text-center py-20 text-neutral-500">No se encontraron ├│rdenes.</div>
                    ) : (
                        filteredOrders.map(order => (
                            <div key={order.id} className="bg-neutral-900/50 border border-white/5 rounded-2xl overflow-hidden backdrop-blur-sm hover:border-white/10 transition-all">
                                {/* Order Summary Row */}
                                <div
                                    className="p-6 flex flex-col md:flex-row md:items-center justify-between gap-6 cursor-pointer hover:bg-white/5 active:scale-[0.99] transition-all duration-200"
                                    onClick={() => toggleExpand(order.id)}
                                >
                                    <div className="flex items-center gap-6 pointer-events-none w-full md:w-auto">
                                        <div className={`p-3 rounded-xl flex-shrink-0 ${order.status === 'cancelled' ? 'bg-red-500/10 text-red-500' : 'bg-white/10 text-white'}`}>
                                            {order.status === 'cancelled' ? <X size={24} /> : <Package size={24} />}
                                        </div>
                                        <div className="flex-1 min-w-0">
                                            <div className="flex items-center gap-3 mb-1 flex-wrap">
                                                <h3 className="text-lg font-black font-mono tracking-tight text-white whitespace-nowrap">
                                                    #{order.id.slice(0, 8)}
                                                </h3>
                                                <div className="relative group pointer-events-auto" onClick={(e) => e.stopPropagation()}>
                                                    <select
                                                        value={order.status}
                                                        onChange={(e) => {
                                                            handleStatusChange(order.id, e.target.value);
                                                        }}
                                                        disabled={updatingId === order.id}
                                                        className={`appearance-none pl-3 pr-8 py-1 rounded-full text-[10px] font-black uppercase tracking-widest cursor-pointer border border-transparent hover:border-white/20 transition-all outline-none ${ORDER_STATUSES[order.status]?.color || 'bg-gray-500/20 text-gray-400'}`}
                                                    >
                                                        {Object.entries(ORDER_STATUSES).map(([key, config]) => (
                                                            <option key={key} value={key} className="bg-neutral-900 text-white">
                                                                {config.label}
                                                            </option>
                                                        ))}
                                                    </select>
                                                    <ChevronDown size={12} className="absolute right-2 top-1/2 -translate-y-1/2 pointer-events-none opacity-50" />
                                                </div>
                                            </div>
                                            <div className="flex items-center gap-4 text-xs text-neutral-400 font-medium">
                                                <span className="flex items-center gap-1"><Calendar size={12} /> {new Date(order.created_at).toLocaleDateString()}</span>
                                                <span className="flex items-center gap-1"><User size={12} /> {order.user_id ? order.user_id.slice(0, 8) : 'Invitado'}</span>
                                            </div>
                                        </div>
                                    </div>

                                    <div className="flex items-center gap-4 md:gap-8 pointer-events-auto mt-4 md:mt-0 justify-between md:justify-end w-full md:w-auto">
                                        <div className="text-right pointer-events-none">
                                            <div className="text-[10px] uppercase tracking-widest text-neutral-500 font-black mb-1">Monto Total</div>
                                            <div className="text-2xl font-black italic font-mono text-white">
                                                ${order.total_amount.toFixed(2)}
                                            </div>
                                        </div>

                                        <div className="flex items-center gap-2 md:gap-4">
                                            {/* Verification Action Buttons */}
                                            {order.status === 'pending_verification' && (
                                                <div className="hidden lg:flex items-center gap-2 mr-2">
                                                    <button
                                                        onClick={(e) => { e.stopPropagation(); handleStatusChange(order.id, 'awaiting_payment'); }}
                                                        disabled={updatingId === order.id}
                                                        className="px-3 py-1.5 bg-white/20 text-white hover:bg-white/30 rounded-lg text-[10px] font-black uppercase tracking-widest transition-colors"
                                                    >
                                                        Γ£à OK Stock
                                                    </button>
                                                    <button
                                                        onClick={(e) => { e.stopPropagation(); handleStatusChange(order.id, 'cancelled'); }}
                                                        disabled={updatingId === order.id}
                                                        className="px-3 py-1.5 bg-red-500/20 text-red-400 hover:bg-red-500/30 rounded-lg text-[10px] font-black uppercase tracking-widest transition-colors"
                                                    >
                                                        Γ¥î Sin Stock
                                                    </button>
                                                </div>
                                            )}

                                            {/* Status Actions Replaced by Dropdown */}
                                            {updatingId === order.id && (
                                                <span className="text-[10px] uppercase text-neutral-500 animate-pulse hidden md:block">Actualizando...</span>
                                            )}

                                            {/* Delete Action */}
                                            {!order.deleted_at && (
                                                <button
                                                    onClick={(e) => {
                                                        e.stopPropagation();
                                                        if (confirm("┬┐Est├ís seguro de que deseas ELIMINAR esta orden? Se ocultar├í de la vista.")) {
                                                            setDeletingId(order.id);
                                                            supabase.rpc('soft_delete_order', { p_order_id: order.id })
                                                                .then(({ data, error }: { data: any, error: any }) => {
                                                                    if (error) throw error;
                                                                    if (!data.success) throw new Error(data.error);
                                                                    setOrders(prev => prev.map(o => o.id === order.id ? { ...o, deleted_at: new Date().toISOString() } : o));
                                                                })
                                                                .catch((err: any) => alert("Error al eliminar: " + err.message))
                                                                .finally(() => setDeletingId(null));
                                                        }
                                                    }}
                                                    disabled={deletingId === order.id}
                                                    className="p-2 hover:bg-red-500/10 text-neutral-600 hover:text-red-500 rounded-full transition-colors relative z-10"
                                                    title="Eliminar Orden (Soft)"
                                                >
                                                    <X size={16} />
                                                </button>
                                            )}

                                            <div className="p-2 hover:bg-white/10 rounded-full transition-colors cursor-pointer">
                                                <ChevronDown size={20} className={`text-neutral-500 transition-transform duration-300 ${expandedOrderId === order.id ? 'rotate-180' : ''}`} />
                                            </div>
                                        </div>
                                    </div>
                                </div>

                                {/* Order Details Layout */}
                                {expandedOrderId === order.id && (
                                    <div className="border-t border-white/5 bg-black/40 p-6 animate-in slide-in-from-top-2 duration-200 space-y-8">
                                        
                                        {/* Buyer & Shipping Info */}
                                        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 pb-8 border-b border-white/5">
                                            {/* Contact Details */}
                                            <div className="space-y-4">
                                                <h4 className="text-sm font-black uppercase tracking-widest text-blue-400 flex items-center gap-2">
                                                    <User size={14} /> Informaci├│n del Comprador
                                                </h4>
                                                <div className="bg-white/5 rounded-2xl p-5 border border-white/5 space-y-4">
                                                    <div className="grid grid-cols-2 gap-4">
                                                        <div>
                                                            <p className="text-[10px] uppercase font-black text-neutral-500 tracking-widest mb-1">Nombre Completo</p>
                                                            <p className="text-sm font-bold text-white">
                                                                {order.guest_info?.full_name || order.shipping_address?.full_name || 'No proporcionado'}
                                                            </p>
                                                        </div>
                                                        <div>
                                                            <p className="text-[10px] uppercase font-black text-neutral-500 tracking-widest mb-1">Tel├⌐fono</p>
                                                            <p className="text-sm font-bold text-white">
                                                                {order.guest_info?.phone || order.shipping_address?.phone || 'No proporcionado'}
                                                            </p>
                                                        </div>
                                                    </div>
                                                    <div>
                                                        <p className="text-[10px] uppercase font-black text-neutral-500 tracking-widest mb-1">Correo Electr├│nico</p>
                                                        <p className="text-sm font-bold text-white">
                                                            {order.guest_info?.email || order.shipping_address?.email || 'N/A'}
                                                        </p>
                                                    </div>
                                                </div>
                                            </div>

                                            {/* Shipping Details */}
                                            <div className="space-y-4">
                                                <h4 className="text-sm font-black uppercase tracking-widest text-white flex items-center gap-2">
                                                    <Package size={14} /> Detalles de Env├¡o
                                                </h4>
                                                <div className="bg-white/5 rounded-2xl p-5 border border-white/5 space-y-4">
                                                    <div>
                                                        <p className="text-[10px] uppercase font-black text-neutral-500 tracking-widest mb-1">Direcci├│n de Entrega</p>
                                                        <p className="text-sm font-bold text-white leading-relaxed">
                                                            {order.shipping_address?.address || order.shipping_address?.address_line1 || 'Recojo en tienda / No especificado'}
                                                        </p>
                                                        <p className="text-xs text-neutral-400 mt-1 font-medium">
                                                            {order.shipping_address?.city || order.shipping_address?.state || ''}{order.shipping_address?.department ? `, ${order.shipping_address?.department}` : ''}
                                                            {order.shipping_address?.zip_code ? ` (${order.shipping_address.zip_code})` : ''}
                                                        </p>
                                                    </div>
                                                    <div className="pt-2 border-t border-white/5 flex items-center justify-between">
                                                        <div>
                                                            <p className="text-[10px] uppercase font-black text-neutral-500 tracking-widest mb-0.5">M├⌐todo</p>
                                                            <span className="text-[10px] font-black uppercase px-2 py-0.5 bg-white/20 text-white rounded-md border border-cyan-500/20">
                                                                {order.shipping_address?.shipping_method || 'Env├¡o Standard'}
                                                            </span>
                                                        </div>
                                                        {order.payment_proof_url && (
                                                            <div className="text-right">
                                                                <p className="text-[10px] uppercase font-black text-neutral-500 tracking-widest mb-0.5">Comprobante</p>
                                                                <a
                                                                    href={order.payment_proof_url}
                                                                    target="_blank"
                                                                    rel="noopener noreferrer"
                                                                    className="text-[10px] font-black uppercase text-lime-400 hover:text-white transition-colors underline decoration-lime-400/30 underline-offset-4"
                                                                >
                                                                    Abrir Adjunto
                                                                </a>
                                                            </div>
                                                        )}
                                                    </div>
                                                </div>
                                            </div>
                                        </div>

                                        {/* Order Contents */}
                                        <div className="space-y-4">
                                            <div className="flex justify-between items-center mb-4">
                                                <h4 className="text-sm font-black uppercase tracking-widest text-neutral-400 flex items-center gap-2">
                                                    <Package size={14} /> Contenido de la Orden
                                                </h4>
                                                <button
                                                    onClick={() => {
                                                        const html = generateOrderReceiptHTML(order);
                                                        const win = window.open('', '_blank');
                                                        if (win) { win.document.write(html); win.document.close(); }
                                                    }}
                                                    className="flex items-center gap-1.5 px-3 py-1.5 bg-[#0066FF]/10 border border-[#0066FF]/30 text-[#0066FF] hover:bg-[#0066FF]/20 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all"
                                                >
                                                    <FileDown size={12} /> Comprobante PDF
                                                </button>
                                            </div>
                                            {order.order_items && order.order_items.length > 0 ? (
                                                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                                                    {order.order_items.map((item) => (
                                                        <div key={item.id} className="flex gap-4 p-4 bg-white/5 rounded-xl border border-white/5 hover:border-white/10 transition-colors">
                                                            {(item.product?.image_url || item.accessory?.image_url) ? (
                                                                <img
                                                                    src={item.product?.image_url || item.accessory?.image_url}
                                                                    alt={item.product?.name || item.accessory?.name}
                                                                    className="w-16 h-24 object-cover rounded-lg shadow-lg"
                                                                />
                                                            ) : (
                                                                <div className="w-16 h-24 bg-neutral-800 rounded-lg flex items-center justify-center text-neutral-600">
                                                                    <Package size={20} />
                                                                </div>
                                                            )}
                                                            <div className="flex flex-col justify-between py-1">
                                                                <div>
                                                                    <h5 className="font-bold text-sm text-white line-clamp-1">{item.product?.name || item.accessory?.name || 'Cargando...'}</h5>
                                                                    <div className="flex items-center gap-1.5 mt-0.5">
                                                                        <p className="text-[10px] text-neutral-400 uppercase tracking-wider font-bold">
                                                                            {item.product?.set_code || item.accessory?.category || 'Accesorio'}
                                                                        </p>
                                                                        {(item.finish === 'foil' || item.finish === 'etched') && (
                                                                            <span className={`text-[8px] px-1 py-0.5 rounded font-black uppercase tracking-widest ${item.finish === 'foil' ? 'bg-purple-500/20 text-purple-400 border border-purple-500/20' : 'bg-white/20 text-white border border-cyan-500/20'}`}>
                                                                                {item.finish}
                                                                            </span>
                                                                        )}
                                                                        {item.is_on_demand && (
                                                                            <span className="text-[8px] px-1 py-0.5 rounded bg-orange-500/20 text-orange-400 border border-orange-500/20 font-black uppercase tracking-widest italic">
                                                                                Por Encargo
                                                                            </span>
                                                                        )}
                                                                    </div>
                                                                </div>
                                                                <div className="flex items-center justify-between gap-4 mt-2">
                                                                    <div className="flex items-center gap-2">
                                                                        <span className="text-xs bg-white/10 px-2 py-1 rounded font-mono text-white">x{item.quantity}</span>
                                                                        <div className="flex items-center gap-1">
                                                                            {confirmingItemId === item.id ? (
                                                                                <div className="flex items-center gap-1 bg-red-500/10 p-0.5 rounded-lg border border-red-500/20">
                                                                                    <button
                                                                                        type="button"
                                                                                        onClick={(e) => {
                                                                                            e.stopPropagation();
                                                                                            handleRemoveItem(order.id, item.id);
                                                                                        }}
                                                                                        disabled={removingItemId === item.id}
                                                                                        className="p-1.5 bg-red-500 text-white rounded-md hover:bg-red-600 transition-colors shadow-lg"
                                                                                        title="Confirmar eliminaci├│n"
                                                                                    >
                                                                                        {removingItemId === item.id ? (
                                                                                            <Loader2 size={12} className="animate-spin" />
                                                                                        ) : (
                                                                                            <Check size={12} />
                                                                                        )}
                                                                                    </button>
                                                                                    <button
                                                                                        type="button"
                                                                                        onClick={(e) => {
                                                                                            e.stopPropagation();
                                                                                            setConfirmingItemId(null);
                                                                                        }}
                                                                                        className="p-1.5 text-neutral-400 hover:text-white transition-colors"
                                                                                        title="Cancelar"
                                                                                    >
                                                                                        <X size={12} />
                                                                                    </button>
                                                                                </div>
                                                                            ) : (
                                                                                <button
                                                                                    type="button"
                                                                                    onClick={(e) => {
                                                                                        e.stopPropagation();
                                                                                        setConfirmingItemId(item.id);
                                                                                    }}
                                                                                    disabled={removingItemId === item.id}
                                                                                    className="p-2 hover:bg-red-500/20 text-neutral-500 hover:text-red-500 rounded-xl transition-all active:scale-90 border border-transparent hover:border-red-500/20"
                                                                                    title="Eliminar de la orden"
                                                                                >
                                                                                    <Trash2 size={14} />
                                                                                </button>
                                                                            )}
                                                                        </div>
                                                                    </div>
                                                                    <span className="font-mono text-white font-bold">${item.price_at_purchase.toFixed(2)}</span>
                                                                </div>
                                                            </div>
                                                        </div>
                                                    ))}
                                                </div>
                                            ) : (
                                                <div className="text-neutral-500 text-sm font-mono italic p-4 text-center bg-white/5 rounded-xl border border-dashed border-white/10">
                                                    <AlertCircle size={16} className="inline mr-2 mb-1" />
                                                    No se encontraron art├¡culos en el historial de esta orden.
                                                </div>
                                            )}
                                        </div>
                                    </div>
                                )}
                            </div>
                        ))
                    )}
                </div>
            </div>
        </div>
    );
};

export default OrdersPage;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { 
  Plus, 
  Trash2, 
  Save, 
  X, 
  Image as ImageIcon, 
  ChevronLeft, 
  Eye, 
  EyeOff,
  Link as LinkIcon,
  Search
} from 'lucide-react';
import { 
  adminFetchPresales, 
  adminSavePresale, 
  adminDeletePresale, 
  uploadAsset,
  fetchAccessoriesAdmin,
  fetchInventoryList
} from '../../utils/api';

interface Presale {
  id?: string;
  title: string;
  subtitle: string;
  image_url: string;
  link_url: string;
  is_active: boolean;
  display_order: number;
}

export const PresalesPage: React.FC = () => {
  const navigate = useNavigate();
  const [presales, setPresales] = useState<Presale[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [editingPresale, setEditingPresale] = useState<Presale | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [uploading, setUploading] = useState(false);
  
  // Product search state
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState<any[]>([]);
  const [searching, setSearching] = useState(false);

  useEffect(() => {
    loadPresales();
  }, []);

  const loadPresales = async () => {
    try {
      setLoading(true);
      const data = await adminFetchPresales();
      setPresales(data || []);
    } catch (error) {
      console.error('Error loading presales:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleCreate = () => {
    setEditingPresale({
      title: '',
      subtitle: '',
      image_url: '',
      link_url: '',
      is_active: true,
      display_order: presales.length
    });
    setSearchQuery('');
    setSearchResults([]);
    setIsModalOpen(true);
  };

  const handleEdit = (presale: Presale) => {
    setEditingPresale({ ...presale });
    setSearchQuery('');
    setSearchResults([]);
    setIsModalOpen(true);
  };

  const handleDelete = async (id: string) => {
    if (!window.confirm('┬┐Est├ís seguro de eliminar esta preventa?')) return;
    try {
      await adminDeletePresale(id);
      setPresales(presales.filter(b => b.id !== id));
    } catch (error) {
      console.error('Error deleting presale:', error);
      alert('Error al eliminar preventa');
    }
  };

  const handleSave = async () => {
    if (!editingPresale || !editingPresale.image_url) {
      alert('La imagen es obligatoria');
      return;
    }

    try {
      setSaving(true);
      const saved = await adminSavePresale(editingPresale);
      if (editingPresale.id) {
        setPresales(presales.map(b => b.id === saved.id ? saved : b));
      } else {
        setPresales([...presales, saved]);
      }
      setIsModalOpen(false);
      setEditingPresale(null);
    } catch (error) {
      console.error('Error saving presale:', error);
      alert('Error al guardar preventa');
    } finally {
      setSaving(false);
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    try {
      setUploading(true);
      const url = await uploadAsset(file, 'presales');
      if (editingPresale) {
        setEditingPresale({ ...editingPresale, image_url: url });
      }
    } catch (error) {
      console.error('Upload failed:', error);
      alert('Error al subir imagen');
    } finally {
      setUploading(false);
    }
  };

  const toggleActive = async (presale: Presale) => {
    try {
      const updated = { ...presale, is_active: !presale.is_active };
      await adminSavePresale(updated);
      setPresales(presales.map(b => b.id === presale.id ? updated : b));
    } catch (error) {
      console.error('Error toggling active:', error);
    }
  };

  const handleSearchProducts = async () => {
    if (!searchQuery.trim()) return;
    try {
      setSearching(true);
      // Search in both accessories and singles
      const [accRes, singlesRes] = await Promise.all([
        fetchAccessoriesAdmin({ search: searchQuery, limit: 10 }),
        fetchInventoryList(0, 10, searchQuery)
      ]);

      const results = [
        ...(accRes.data || []).map((p: any) => ({ ...p, type: 'accessory' })),
        ...(singlesRes.data || []).map((p: any) => ({ ...p, type: 'single', id: p.printing_id }))
      ];

      setSearchResults(results);
    } catch (error) {
      console.error('Error searching products:', error);
    } finally {
      setSearching(false);
    }
  };

  const selectProduct = (product: any) => {
    if (!editingPresale) return;
    const link = `/card/${product.id}`;
    setEditingPresale({
      ...editingPresale,
      link_url: link,
      title: product.name,
      subtitle: product.type === 'accessory' ? 'Nuevo Producto' : 'Carta Especial'
    });
    setSearchResults([]);
    setSearchQuery('');
  };

  return (
    <div className="min-h-screen bg-[#050505] text-white p-4 md:p-8 font-sans">
      <div className="max-w-7xl mx-auto">
        
        {/* Header */}
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-12">
          <div className="space-y-2">
            <button 
              onClick={() => navigate('/admin')}
              className="flex items-center gap-2 text-slate-500 hover:text-white transition-colors text-xs font-black uppercase tracking-widest group"
            >
              <ChevronLeft size={16} className="group-hover:-translate-x-1 transition-transform" />
              Volver al Panel
            </button>
            <h1 className="text-4xl md:text-5xl font-black italic tracking-tighter uppercase">
              Gesti├│n de <span className="text-white">Preventas</span>
            </h1>
            <p className="text-slate-500 text-xs font-bold uppercase tracking-[0.2em]">Banners secundarios de anuncios</p>
          </div>
          
          <button 
            onClick={handleCreate}
            className="flex items-center justify-center gap-3 bg-white text-black px-8 py-4 rounded-2xl font-black text-xs uppercase tracking-widest hover:scale-105 transition-all shadow-[0_0_30px_rgba(34,211,238,0.3)]"
          >
            <Plus size={18} />
            Nueva Preventa
          </button>
        </div>

        {/* Content */}
        {loading ? (
          <div className="flex flex-col items-center justify-center py-20 gap-4">
            <div className="w-12 h-12 border-4 border-white/20 border-t-white rounded-full animate-spin"></div>
            <p className="text-slate-500 font-black text-[10px] uppercase tracking-widest animate-pulse">Sincronizando Preventas...</p>
          </div>
        ) : presales.length === 0 ? (
          <div className="text-center py-20 bg-slate-900/20 border-2 border-dashed border-white/5 rounded-[2.5rem]">
            <ImageIcon className="w-16 h-16 text-slate-700 mx-auto mb-4" />
            <h3 className="text-xl font-bold text-slate-500 uppercase tracking-tighter">No hay preventas configuradas</h3>
            <p className="text-slate-400 text-xs mt-2 font-medium">Crea la primera preventa para mostrar debajo del banner principal.</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
            {presales.map((presale) => (
              <div 
                key={presale.id} 
                className="group relative bg-slate-900/40 border border-white/5 rounded-[2rem] overflow-hidden hover:border-white/30 transition-all flex flex-col"
              >
                {/* Preview Image */}
                <div className="aspect-[3.5/1] w-full relative overflow-hidden bg-black">
                  <img 
                    src={presale.image_url} 
                    alt={presale.title} 
                    className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700 opacity-60 group-hover:opacity-100"
                  />
                  <div className="absolute inset-0 bg-gradient-to-t from-black via-black/20 to-transparent" />
                  
                  {/* Status Badge */}
                  <div className="absolute top-4 right-4">
                    <button 
                      onClick={() => toggleActive(presale)}
                      className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest border transition-all shadow-lg ${
                        presale.is_active 
                          ? 'bg-white text-black border-cyan-400 shadow-cyan-500/20' 
                          : 'bg-slate-800 text-slate-400 border-white/10 shadow-black'
                      }`}
                    >
                      {presale.is_active ? (
                        <span className="flex items-center gap-1"><Eye size={12} /> ON</span>
                      ) : (
                        <span className="flex items-center gap-1"><EyeOff size={12} /> OFF</span>
                      )}
                    </button>
                  </div>
                </div>

                {/* Content */}
                <div className="p-6 flex-1 flex flex-col justify-between">
                  <div>
                    <h3 className="text-lg font-black italic uppercase tracking-tighter mb-1 line-clamp-1">{presale.title || 'Sin T├¡tulo'}</h3>
                    <p className="text-slate-500 text-[10px] font-bold uppercase tracking-widest line-clamp-2 mb-4">{presale.subtitle || 'Sin Subt├¡tulo'}</p>
                    
                    {presale.link_url && (
                      <div className="flex items-center gap-2 text-[9px] text-slate-400 font-bold uppercase tracking-widest">
                        <LinkIcon size={12} className="text-white" />
                        <span className="truncate">{presale.link_url}</span>
                      </div>
                    )}
                  </div>

                  <div className="flex items-center gap-3 mt-6 pt-6 border-t border-white/5">
                    <button 
                      onClick={() => handleEdit(presale)}
                      className="flex-1 bg-white/5 hover:bg-white/10 border border-white/10 p-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all"
                    >
                      Editar
                    </button>
                    <button 
                      onClick={() => presale.id && handleDelete(presale.id)}
                      className="bg-red-500/10 hover:bg-red-500/20 border border-red-500/20 p-3 rounded-xl text-red-500 transition-all"
                    >
                      <Trash2 size={16} />
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}

        {/* Edit/Create Modal */}
        {isModalOpen && editingPresale && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/90 backdrop-blur-md">
            <div className="bg-[#0a0a0a] border border-white/10 w-full max-w-2xl rounded-[2.5rem] overflow-hidden shadow-2xl flex flex-col max-h-[90vh]">
              
              <div className="p-8 border-b border-white/5 flex items-center justify-between">
                <h3 className="text-2xl font-black italic uppercase tracking-tighter">
                  {editingPresale.id ? 'Editar' : 'Nueva'} <span className="text-white">Preventa</span>
                </h3>
                <button onClick={() => setIsModalOpen(false)} className="text-slate-500 hover:text-white transition-colors bg-white/5 p-2 rounded-full">
                  <X size={20} />
                </button>
              </div>

              <div className="p-8 overflow-y-auto space-y-6 custom-scrollbar">
                
                {/* Image Upload Area */}
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Imagen de Preventa (800x230 aprox)</label>
                  <div className="relative aspect-[3.5/1] w-full rounded-2xl overflow-hidden bg-slate-900 border-2 border-dashed border-white/10 flex flex-col items-center justify-center gap-4 group">
                    {editingPresale.image_url ? (
                      <>
                        <img src={editingPresale.image_url} alt="Preview" className="w-full h-full object-cover" />
                        <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                          <label className="bg-white text-black px-6 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest cursor-pointer hover:scale-105 transition-all">
                            Cambiar Imagen
                            <input type="file" className="hidden" onChange={handleFileUpload} accept="image/*" />
                          </label>
                        </div>
                      </>
                    ) : (
                      <>
                        {uploading ? (
                          <div className="w-8 h-8 border-2 border-white/20 border-t-white rounded-full animate-spin"></div>
                        ) : (
                          <>
                            <ImageIcon className="text-slate-700" size={40} />
                            <label className="bg-white/5 hover:bg-white/10 border border-white/10 px-6 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest cursor-pointer transition-all">
                              Subir Imagen
                              <input type="file" className="hidden" onChange={handleFileUpload} accept="image/*" />
                            </label>
                          </>
                        )}
                      </>
                    )}
                  </div>
                </div>

                {/* Product Search Tool */}
                <div className="p-6 bg-slate-900/50 border border-white/5 rounded-3xl space-y-4">
                  <div className="flex items-center gap-2 mb-2">
                    <Search size={14} className="text-white" />
                    <label className="text-[10px] font-black text-white uppercase tracking-widest">Vinculaci├│n R├ípida con Producto</label>
                  </div>
                  <div className="flex gap-2">
                    <input 
                      type="text" 
                      value={searchQuery}
                      onChange={(e) => setSearchQuery(e.target.value)}
                      onKeyDown={(e) => e.key === 'Enter' && handleSearchProducts()}
                      placeholder="Buscar producto o carta..."
                      className="flex-1 bg-black border border-white/10 p-3 rounded-xl text-xs font-bold focus:border-white transition-all"
                    />
                    <button 
                      onClick={handleSearchProducts}
                      disabled={searching}
                      className="bg-white/10 hover:bg-white/20 p-3 rounded-xl transition-all"
                    >
                      {searching ? <div className="w-4 h-4 border-2 border-white/20 border-t-white rounded-full animate-spin"></div> : <Search size={18} />}
                    </button>
                  </div>

                  {searchResults.length > 0 && (
                    <div className="max-h-40 overflow-y-auto space-y-2 mt-2 custom-scrollbar">
                      {searchResults.map((p, i) => (
                        <button 
                          key={i}
                          onClick={() => selectProduct(p)}
                          className="w-full flex items-center gap-3 p-3 bg-black hover:bg-white hover:text-black rounded-xl border border-white/5 transition-all text-left group"
                        >
                          <div className="w-10 h-10 rounded-lg overflow-hidden bg-slate-800 shrink-0">
                            <img src={p.image_url} alt="" className="w-full h-full object-cover" />
                          </div>
                          <div className="flex-1 min-w-0">
                            <div className="text-[10px] font-black uppercase truncate">{p.name}</div>
                            <div className="text-[8px] font-bold opacity-60 uppercase tracking-widest">{p.type === 'accessory' ? 'Producto/Accesorio' : 'Carta/Single'}</div>
                          </div>
                          <Plus size={14} />
                        </button>
                      ))}
                    </div>
                  )}
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">T├¡tulo de Preventa</label>
                    <input 
                      type="text" 
                      value={editingPresale.title}
                      onChange={(e) => setEditingPresale({ ...editingPresale, title: e.target.value })}
                      className="w-full bg-slate-900/50 border border-white/5 p-4 rounded-xl text-xs font-bold text-white focus:outline-none focus:border-white/50 transition-all"
                      placeholder="Ej: NUEVO LANZAMIENTO"
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Texto Secundario</label>
                    <input 
                      type="text" 
                      value={editingPresale.subtitle}
                      onChange={(e) => setEditingPresale({ ...editingPresale, subtitle: e.target.value })}
                      className="w-full bg-slate-900/50 border border-white/5 p-4 rounded-xl text-xs font-bold text-white focus:outline-none focus:border-white/50 transition-all"
                      placeholder="Ej: DISPONIBLE PR├ôXIMAMENTE"
                    />
                  </div>
                </div>

                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">URL de Destino (Link)</label>
                  <div className="relative">
                    <LinkIcon className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-600" size={16} />
                    <input 
                      type="text" 
                      value={editingPresale.link_url}
                      onChange={(e) => setEditingPresale({ ...editingPresale, link_url: e.target.value })}
                      className="w-full bg-slate-900/50 border border-white/5 p-4 pl-12 rounded-xl text-xs font-bold text-white focus:outline-none focus:border-white/50 transition-all"
                      placeholder="/card/abc-123"
                    />
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-6">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Orden</label>
                    <input 
                      type="number" 
                      value={editingPresale.display_order}
                      onChange={(e) => setEditingPresale({ ...editingPresale, display_order: parseInt(e.target.value) || 0 })}
                      className="w-full bg-slate-900/50 border border-white/5 p-4 rounded-xl text-xs font-bold text-white focus:outline-none focus:border-white/50 transition-all"
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Estado</label>
                    <button 
                      onClick={() => setEditingPresale({ ...editingPresale, is_active: !editingPresale.is_active })}
                      className={`w-full p-4 rounded-xl text-[10px] font-black uppercase tracking-widest border transition-all flex items-center justify-center gap-3 ${
                        editingPresale.is_active 
                          ? 'bg-white/10 border-white/20 text-white' 
                          : 'bg-slate-900/50 border-white/5 text-slate-500'
                      }`}
                    >
                      {editingPresale.is_active ? <Eye size={16} /> : <EyeOff size={16} />}
                      {editingPresale.is_active ? 'Visible' : 'Oculto'}
                    </button>
                  </div>
                </div>
              </div>

              <div className="p-8 border-t border-white/5 bg-black/40 flex items-center justify-end gap-4">
                <button 
                  onClick={() => setIsModalOpen(false)}
                  className="px-8 py-4 bg-white/5 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-white/10 transition-all"
                >
                  Cancelar
                </button>
                <button 
                  onClick={handleSave}
                  disabled={saving || uploading}
                  className="flex items-center gap-3 bg-white text-black px-10 py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest hover:scale-105 transition-all shadow-[0_0_20px_rgba(34,211,238,0.3)] disabled:opacity-50"
                >
                  {saving ? (
                    <>
                      <div className="w-3 h-3 border-2 border-black/20 border-t-black rounded-full animate-spin"></div>
                      Guardando...
                    </>
                  ) : (
                    <>
                      <Save size={16} />
                      Guardar Cambios
                    </>
                  )}
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { 
  Plus, 
  Trash2, 
  Save, 
  X, 
  Image as ImageIcon, 
  ChevronLeft, 
  Eye, 
  EyeOff,
  Link as LinkIcon
} from 'lucide-react';
import { adminFetchBanners, adminSaveBanner, adminDeleteBanner, uploadAsset, fetchGames } from '../../utils/api';

interface Banner {
  id?: string;
  title: string;
  subtitle: string;
  image_url: string;
  link_url: string;
  is_active: boolean;
  display_order: number;
  category: string;
  game_code?: string | null;
}

interface Game {
  game_id: number;
  game_name: string;
  game_code: string;
}

export const TcgBannersPage: React.FC = () => {
  const navigate = useNavigate();
  const [banners, setBanners] = useState<Banner[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [editingBanner, setEditingBanner] = useState<Banner | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [games, setGames] = useState<Game[]>([]);
  const [gameFilter, setGameFilter] = useState<string>('');

  useEffect(() => {
    loadBanners();
    loadGames();
  }, []);

  const loadGames = async () => {
    try {
      const data = await fetchGames();
      // Only show the 8 featured TCGs from the storefront menu
      const FEATURED_CODES = ['MTG', 'POKEMON', 'PKM', 'YUGIOH', 'YGO', 'RFB', 'ONEPIECE', 'OPC', 'DGM', 'GND', 'FAB'];
      const filtered = (data || []).filter((g: Game) => FEATURED_CODES.includes(g.game_code));
      
      // Remove duplicates if any (like PKM vs POKEMON) - prioritize the one with more data or canonical
      const unique = filtered.reduce((acc: Game[], current: Game) => {
        const isDuplicate = acc.find(g => 
          (g.game_code === 'PKM' && current.game_code === 'POKEMON') ||
          (g.game_code === 'POKEMON' && current.game_code === 'PKM') ||
          (g.game_code === 'YGO' && current.game_code === 'YUGIOH') ||
          (g.game_code === 'YUGIOH' && current.game_code === 'YGO') ||
          (g.game_code === 'OPC' && current.game_code === 'ONEPIECE') ||
          (g.game_code === 'ONEPIECE' && current.game_code === 'OPC')
        );
        if (!isDuplicate) acc.push(current);
        return acc;
      }, []);

      setGames(unique);
      if (unique.length > 0) {
        setGameFilter(unique[0].game_code);
      }
    } catch (error) {
      console.error('Error loading games:', error);
    }
  };

  const loadBanners = async () => {
    try {
      setLoading(true);
      const data = await adminFetchBanners();
      // Filter to only show banners with a game_code
      setBanners((data || []).filter((b: any) => b.game_code !== null));
    } catch (error) {
      console.error('Error loading banners:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleCreate = () => {
    const bannersForThisGame = banners.filter(b => b.game_code === gameFilter);
    if (bannersForThisGame.length >= 5) {
      alert(`Se ha alcanzado el l├¡mite m├íximo de 5 banners para ${gameFilter}. Debes eliminar uno antes de crear otro.`);
      return;
    }
    setEditingBanner({
      title: '',
      subtitle: '',
      image_url: '',
      link_url: '',
      is_active: true,
      display_order: bannersForThisGame.length,
      category: 'main_hero',
      game_code: gameFilter
    });
    setIsModalOpen(true);
  };

  const handleEdit = (banner: Banner) => {
    setEditingBanner({ ...banner });
    setIsModalOpen(true);
  };

  const handleDelete = async (id: string) => {
    if (!window.confirm('┬┐Est├ís seguro de eliminar este banner?')) return;
    try {
      await adminDeleteBanner(id);
      setBanners(banners.filter(b => b.id !== id));
    } catch (error) {
      console.error('Error deleting banner:', error);
      alert('Error al eliminar banner');
    }
  };

  const handleSave = async () => {
    if (!editingBanner || !editingBanner.image_url) {
      alert('La imagen es obligatoria');
      return;
    }

    try {
      setSaving(true);
      const saved = await adminSaveBanner(editingBanner);
      if (editingBanner.id) {
        setBanners(banners.map(b => b.id === saved.id ? saved : b));
      } else {
        setBanners([...banners, saved]);
      }
      setIsModalOpen(false);
      setEditingBanner(null);
    } catch (error) {
      console.error('Error saving banner:', error);
      alert('Error al guardar banner');
    } finally {
      setSaving(false);
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    try {
      setUploading(true);
      const url = await uploadAsset(file, 'banners');
      if (editingBanner) {
        setEditingBanner({ ...editingBanner, image_url: url });
      }
    } catch (error) {
      console.error('Upload failed:', error);
      alert('Error al subir imagen');
    } finally {
      setUploading(false);
    }
  };

  const toggleActive = async (banner: Banner) => {
    try {
      const updated = { ...banner, is_active: !banner.is_active };
      await adminSaveBanner(updated);
      setBanners(banners.map(b => b.id === banner.id ? updated : b));
    } catch (error) {
      console.error('Error toggling active:', error);
    }
  };

  return (
    <div className="min-h-screen bg-[#050505] text-white p-4 md:p-8 font-sans">
      <div className="max-w-7xl mx-auto">
        
        {/* Header */}
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-12">
          <div className="space-y-2">
            <button 
              onClick={() => navigate('/admin')}
              className="flex items-center gap-2 text-slate-500 hover:text-white transition-colors text-xs font-black uppercase tracking-widest group"
            >
              <ChevronLeft size={16} className="group-hover:-translate-x-1 transition-transform" />
              Volver al Panel
            </button>
            <h1 className="text-4xl md:text-5xl font-black italic tracking-tighter uppercase">
              Banners <span className="text-geeko-purple">por TCG</span>
            </h1>
            <div className="flex items-center gap-2">
              <p className="text-slate-500 text-xs font-bold uppercase tracking-[0.2em]">Administraci├│n Independiente de Juegos</p>
            </div>
          </div>
          
          <button 
            onClick={handleCreate}
            className="flex items-center justify-center gap-3 bg-geeko-purple text-white px-8 py-4 rounded-2xl font-black text-xs uppercase tracking-widest hover:scale-105 transition-all shadow-[0_0_30px_rgba(168,85,247,0.3)]"
          >
            <Plus size={18} />
            Nuevo Banner TCG
          </button>
        </div>

        {/* TCG Selector Tabs */}
        <div className="flex flex-wrap items-center gap-3 mb-8 bg-slate-900/20 p-2 rounded-[2rem] border border-white/5">
          {games.map(game => (
            <button
              key={game.game_code}
              onClick={() => setGameFilter(game.game_code)}
              className={`px-6 py-2.5 rounded-full text-[10px] font-black uppercase tracking-widest transition-all ${
                gameFilter === game.game_code 
                  ? 'bg-geeko-purple text-white shadow-lg' 
                  : 'text-slate-500 hover:text-white'
              }`}
            >
              {game.game_name}
            </button>
          ))}
        </div>

        {/* Content */}
        {loading ? (
          <div className="flex flex-col items-center justify-center py-20 gap-4">
            <div className="w-12 h-12 border-4 border-white/20 border-t-white rounded-full animate-spin"></div>
            <p className="text-slate-500 font-black text-[10px] uppercase tracking-widest animate-pulse">Sincronizando Banners...</p>
          </div>
        ) : banners.filter(b => b.game_code === gameFilter).length === 0 ? (
          <div className="text-center py-20 bg-slate-900/20 border-2 border-dashed border-white/5 rounded-[2.5rem]">
            <ImageIcon className="w-16 h-16 text-slate-700 mx-auto mb-4" />
            <h3 className="text-xl font-bold text-slate-500 uppercase tracking-tighter">No hay banners para {gameFilter}</h3>
            <p className="text-slate-400 text-xs mt-2 font-medium">Crea el primer banner para este TCG.</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
            {banners
              .filter(b => b.game_code === gameFilter)
              .map((banner) => (
              <div 
                key={banner.id} 
                className="group relative bg-slate-900/40 border border-white/5 rounded-[2rem] overflow-hidden hover:border-white/30 transition-all flex flex-col"
              >
                {/* Preview Image */}
                <div className="aspect-video w-full relative overflow-hidden bg-black">
                  <img 
                    src={banner.image_url} 
                    alt={banner.title} 
                    className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700 opacity-60 group-hover:opacity-100"
                  />
                  <div className="absolute inset-0 bg-gradient-to-t from-black via-black/20 to-transparent" />
                  
                  {/* Status Badge */}
                  <div className="absolute top-4 right-4">
                    <button 
                      onClick={() => toggleActive(banner)}
                      className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest border transition-all shadow-lg ${
                        banner.is_active 
                          ? 'bg-geeko-purple text-white border-purple-400 shadow-purple-500/20' 
                          : 'bg-slate-800 text-slate-400 border-white/10 shadow-black'
                      }`}
                    >
                      {banner.is_active ? (
                        <span className="flex items-center gap-1"><Eye size={12} /> ON</span>
                      ) : (
                        <span className="flex items-center gap-1"><EyeOff size={12} /> OFF</span>
                      )}
                    </button>
                  </div>

                  {/* Order Controls */}
                  <div className="absolute bottom-4 left-4 flex gap-2">
                    <div className="bg-black/60 backdrop-blur-md border border-white/10 px-3 py-1 rounded-lg text-[10px] font-black text-white">
                      # {banner.display_order}
                    </div>
                  </div>
                </div>

                {/* Content */}
                <div className="p-6 flex-1 flex flex-col justify-between">
                  <div>
                    <h3 className="text-lg font-black italic uppercase tracking-tighter mb-1 line-clamp-1">{banner.title || 'Sin T├¡tulo'}</h3>
                    <p className="text-slate-500 text-[10px] font-bold uppercase tracking-widest line-clamp-2 mb-4">{banner.subtitle || 'Sin Subt├¡tulo'}</p>
                    
                    {banner.link_url && (
                      <div className="flex items-center gap-2 text-[9px] text-slate-400 font-bold uppercase tracking-widest">
                        <LinkIcon size={12} className="text-white" />
                        <span className="truncate">{banner.link_url}</span>
                      </div>
                    )}
                  </div>

                  <div className="flex items-center gap-3 mt-6 pt-6 border-t border-white/5">
                    <button 
                      onClick={() => handleEdit(banner)}
                      className="flex-1 bg-white/5 hover:bg-white/10 border border-white/10 p-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all"
                    >
                      Editar
                    </button>
                    <button 
                      onClick={() => banner.id && handleDelete(banner.id)}
                      className="bg-red-500/10 hover:bg-red-500/20 border border-red-500/20 p-3 rounded-xl text-red-500 transition-all"
                    >
                      <Trash2 size={16} />
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}

        {/* Edit/Create Modal */}
        {isModalOpen && editingBanner && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/90 backdrop-blur-md">
            <div className="bg-[#0a0a0a] border border-white/10 w-full max-w-2xl rounded-[2.5rem] overflow-hidden shadow-2xl flex flex-col max-h-[90vh]">
              
              <div className="p-8 border-b border-white/5 flex items-center justify-between">
                <h3 className="text-2xl font-black italic uppercase tracking-tighter">
                  {editingBanner.id ? 'Editar' : 'Nuevo'} <span className="text-geeko-purple">Banner TCG</span>
                </h3>
                <button onClick={() => setIsModalOpen(false)} className="text-slate-500 hover:text-white transition-colors bg-white/5 p-2 rounded-full">
                  <X size={20} />
                </button>
              </div>

              <div className="p-8 overflow-y-auto space-y-6 custom-scrollbar">
                
                {/* Image Upload Area */}
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Imagen del Banner (TCG)</label>
                  <div className="relative aspect-video w-full rounded-2xl overflow-hidden bg-slate-900 border-2 border-dashed border-white/10 flex flex-col items-center justify-center gap-4 group">
                    {editingBanner.image_url ? (
                      <>
                        <img src={editingBanner.image_url} alt="Preview" className="w-full h-full object-cover" />
                        <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                          <label className="bg-white text-black px-6 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest cursor-pointer hover:scale-105 transition-all">
                            Cambiar Imagen
                            <input type="file" className="hidden" onChange={handleFileUpload} accept="image/*" />
                          </label>
                        </div>
                      </>
                    ) : (
                      <>
                        {uploading ? (
                          <div className="w-8 h-8 border-2 border-white/20 border-t-white rounded-full animate-spin"></div>
                        ) : (
                          <>
                            <ImageIcon className="text-slate-700" size={40} />
                            <label className="bg-white/5 hover:bg-white/10 border border-white/10 px-6 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest cursor-pointer transition-all">
                              Subir Imagen
                              <input type="file" className="hidden" onChange={handleFileUpload} accept="image/*" />
                            </label>
                          </>
                        )}
                      </>
                    )}
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">T├¡tulo Principal</label>
                    <input 
                      type="text" 
                      value={editingBanner.title}
                      onChange={(e) => setEditingBanner({ ...editingBanner, title: e.target.value })}
                      className="w-full bg-slate-900/50 border border-white/5 p-4 rounded-xl text-xs font-bold text-white focus:outline-none focus:border-white/50 transition-all"
                      placeholder="Ej: NUEVA EXPANSI├ôN"
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Subt├¡tulo</label>
                    <input 
                      type="text" 
                      value={editingBanner.subtitle}
                      onChange={(e) => setEditingBanner({ ...editingBanner, subtitle: e.target.value })}
                      className="w-full bg-slate-900/50 border border-white/5 p-4 rounded-xl text-xs font-bold text-white focus:outline-none focus:border-white/50 transition-all"
                      placeholder="Ej: CARTAS DISPONIBLES"
                    />
                  </div>
                </div>

                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">TCG Seleccionado</label>
                  <div className="w-full bg-slate-900/20 border border-geeko-purple/30 p-4 rounded-xl text-xs font-black text-geeko-purple uppercase tracking-widest">
                    {games.find(g => g.game_code === editingBanner.game_code)?.game_name || editingBanner.game_code}
                  </div>
                </div>

                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">URL de Destino</label>
                  <div className="relative">
                    <LinkIcon className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-600" size={16} />
                    <input 
                      type="text" 
                      value={editingBanner.link_url}
                      onChange={(e) => setEditingBanner({ ...editingBanner, link_url: e.target.value })}
                      className="w-full bg-slate-900/50 border border-white/5 p-4 pl-12 rounded-xl text-xs font-bold text-white focus:outline-none focus:border-white/50 transition-all"
                      placeholder="https://geekorium.shop/..."
                    />
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-6">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Orden</label>
                    <input 
                      type="number" 
                      value={editingBanner.display_order}
                      onChange={(e) => setEditingBanner({ ...editingBanner, display_order: parseInt(e.target.value) || 0 })}
                      className="w-full bg-slate-900/50 border border-white/5 p-4 rounded-xl text-xs font-bold text-white focus:outline-none focus:border-white/50 transition-all"
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Estado</label>
                    <button 
                      onClick={() => setEditingBanner({ ...editingBanner, is_active: !editingBanner.is_active })}
                      className={`w-full p-4 rounded-xl text-[10px] font-black uppercase tracking-widest border transition-all flex items-center justify-center gap-3 ${
                        editingBanner.is_active 
                          ? 'bg-geeko-purple/20 border-geeko-purple/50 text-geeko-purple' 
                          : 'bg-slate-900/50 border-white/5 text-slate-500'
                      }`}
                    >
                      {editingBanner.is_active ? <Eye size={16} /> : <EyeOff size={16} />}
                      {editingBanner.is_active ? 'Visible' : 'Oculto'}
                    </button>
                  </div>
                </div>
              </div>

              <div className="p-8 border-t border-white/5 bg-black/40 flex items-center justify-end gap-4">
                <button 
                  onClick={() => setIsModalOpen(false)}
                  className="px-8 py-4 bg-white/5 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-white/10 transition-all"
                >
                  Cancelar
                </button>
                <button 
                  onClick={handleSave}
                  disabled={saving || uploading}
                  className="flex items-center gap-3 bg-geeko-purple text-white px-10 py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest hover:scale-105 transition-all shadow-[0_0_20px_rgba(168,85,247,0.3)] disabled:opacity-50"
                >
                  {saving ? (
                    <>
                      <div className="w-3 h-3 border-2 border-white/20 border-t-white rounded-full animate-spin"></div>
                      Guardando...
                    </>
                  ) : (
                    <>
                      <Save size={16} />
                      Guardar Cambios
                    </>
                  )}
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useEffect, useState, useMemo } from 'react';
import { useParams, useNavigate, Link, useSearchParams, useLocation } from 'react-router-dom';
import {
    X, ShoppingCart, RotateCw, ExternalLink, Loader2,
    ArrowLeft, CheckCircle2, AlertCircle, ChevronLeft, ChevronRight
} from 'lucide-react';
import { getCardKingdomUrl } from '../utils/urlUtils';
import { fetchCardDetails, addToCart } from '../utils/api';
import { useAuth } from '../context/AuthContext';
import { Header } from '../components/Navigation/Header';
import { useCart } from '../context/CartContext';
import { ManaText } from '../components/Mana/ManaText';
import { Footer } from '../components/Navigation/Footer';
import { CartDrawer } from '../components/Navigation/CartDrawer';
import { CardImage } from '../components/Card/CardImage';

export const CardDetail: React.FC = () => {
    const { id } = useParams<{ id: string }>();
    const navigate = useNavigate();
    const { user, openAuthModal } = useAuth();
    const [searchParams] = useSearchParams();
    const location = useLocation();
    const initialImage = location.state?.initialImage as string | undefined;
    const initialCard = location.state?.initialCard as any;
    const baseId = id ? id.replace(/-foil$/, '').replace(/-nonfoil$/, '').replace(/-etched$/, '') : undefined;
    const urlSuffix = id ? (id.endsWith('-foil') ? 'foil' : id.endsWith('-etched') ? 'etched' : id.endsWith('-nonfoil') ? 'nonfoil' : null) : null;
    const activeFinish = searchParams.get('finish') || urlSuffix || 'nonfoil';

    // Build initial placeholder data from the Home page card data
    const getInitialDetails = () => {
        if (!initialCard) return null;
        return {
            printing_id: baseId || initialCard.card_id,
            card_id: baseId || initialCard.card_id,
            name: initialCard.name,
            set: initialCard.set,
            set_code: initialCard.set_code || '',
            game_id: initialCard.game_id,
            game: initialCard.game || (initialCard.game_id === 17 ? 'GND' : 'MTG'),
            image_url: initialCard.image_url || initialImage,
            price: initialCard.price,
            original_price: initialCard.original_price,
            discount_percentage: initialCard.discount_percentage,
            rarity: initialCard.rarity,
            type: initialCard.type,
            finish: initialCard.finish,
            is_foil: initialCard.is_foil,
            total_stock: initialCard.total_stock || initialCard.stock || 0,
            valuation: initialCard.valuation || { market_price: initialCard.price },
            all_versions: [], // Start empty, will be populated by fetchCardDetails
            card_faces: initialCard.card_faces
        };
    };

    const [details, setDetails] = useState<any>(getInitialDetails());
    const [loading, setLoading] = useState(!initialCard);
    const [error, setError] = useState<string | null>(null);
    const [activePrintingId, setActivePrintingId] = useState<string | undefined>(baseId);
    const [currentFaceIndex, setCurrentFaceIndex] = useState(0);
    const [isAdding, setIsAdding] = useState(false);

    const { cartCount } = useCart();
    const [isCartOpen, setIsCartOpen] = useState(false);

    useEffect(() => {
        if (id) {
            const cleanId = id.replace(/-foil$/, '').replace(/-nonfoil$/, '').replace(/-etched$/, '');
            setActivePrintingId(cleanId);
            loadDetails(id);
        }
    }, [id]);

    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === 'Escape') {
                navigate(-1);
            }
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [navigate]);

    const loadDetails = async (printingId: string) => {
        if (!details) setLoading(true);
        setError(null);
        try {
            const data = await fetchCardDetails(printingId);
            setDetails(data);
        } catch (err) {
            console.error('Error loading card details:', err);
            setError('Failed to load card details. Please try again.');
        } finally {
            setLoading(false);
        }
    };

    const handleVersionClick = (printingId: string, finish?: string) => {
        const params = new URLSearchParams();
        if (finish && finish !== 'nonfoil') {
            params.set('finish', finish);
        }
        const search = params.toString();
        navigate(`/card/${printingId}${search ? `?${search}` : ''}`);
    };

    const handleAddToCart = async (e?: React.MouseEvent) => {
        if (e) {
            e.preventDefault();
            e.stopPropagation();
        }
        if (!user) {
            openAuthModal();
            return;
        }
        if (!activeVersion) return;

        setIsAdding(true);
        try {
            // Strip synthetic suffix from id, pass finish explicitly
            const baseId = activeVersion.printing_id.replace(/-foil$/, '').replace(/-nonfoil$/, '').replace(/-etched$/, '');
            const result = await addToCart(baseId, 1, activeFinish, !!details?.is_accessory);

            if (result && !result.success) {
                console.error("ADD TO CART FAILED:", result);
                alert(`Error al agregar al carrito: ${result.message || result.error || JSON.stringify(result)}`);
                return;
            }

            // Show success
            setIsCartOpen(true);
        } catch (err: any) {
            console.error('Error adding to cart:', err);
            alert(err.message || 'Error al agregar al carrito');
        } finally {
            setIsAdding(false);
        }
    };


    const [currentImageIndex, setCurrentImageIndex] = useState(0);

    const getLegalityIcon = (status: string) => {
        switch (status) {
            case 'legal': return <CheckCircle2 size={16} className="text-geeko-cyan" />;
            case 'not_legal': return <X size={16} className="text-neutral-700" />;
            case 'restricted': return <AlertCircle size={16} className="text-amber-500" />;
            case 'banned': return <AlertCircle size={16} className="text-red-500" />;
            default: return <X size={16} className="text-neutral-700" />;
        }
    };

    const relevantFormats = ['standard', 'pioneer', 'modern', 'legacy', 'commander', 'pauper'];

    const isDFC = details?.name?.includes(' // ');
    const hasMultipleFaces = (details?.card_faces && details.card_faces.length > 1) || isDFC;

    const allImages = useMemo(() => {
        const list: string[] = [];
        let mainImg = details?.image_url;
        if (details?.card_faces && details.card_faces.length > 0) {
            const face = details.card_faces[currentFaceIndex];
            mainImg = face?.image_uris?.normal || face?.image_uris?.large || face?.image_uris?.png || face?.image_url || details.image_url;
        } else if (isDFC && currentFaceIndex === 1 && mainImg) {
            if (mainImg.includes('/front/')) mainImg = mainImg.replace('/front/', '/back/');
            else if (mainImg.includes('.jpg')) mainImg = mainImg.replace('.jpg', '_back.jpg');
            else if (mainImg.includes('.png')) mainImg = mainImg.replace('.png', '_back.png');
        }

        if (mainImg) list.push(mainImg);

        if (details?.additional_images && details.additional_images.length > 0) {
            details.additional_images.forEach((img: string) => {
                if (img && !list.includes(img)) list.push(img);
            });
        }
        return list;
    }, [details?.card_faces, currentFaceIndex, details?.image_url, details?.additional_images, isDFC]);

    const currentImage = allImages[currentImageIndex] || allImages[0] || '';

    const versionGroups = useMemo(() => {
        if (!details?.all_versions) return [];

        const groups = (Array.isArray(details.all_versions) ? details.all_versions : []).reduce((acc: any, v: any) => {
            const key = `${v.set_code}-${v.collector_number}`;
            if (!acc[key]) {
                acc[key] = {
                    base: v,
                    normal: !(v.is_foil || v.finish === 'foil') ? v : null,
                    foil: (v.is_foil || v.finish === 'foil') ? v : null,
                };
            } else {
                if (!(v.is_foil || v.finish === 'foil')) acc[key].normal = v;
                else acc[key].foil = v;
            }
            return acc;
        }, {} as Record<string, any>);

        return Object.values(groups).sort((a: any, b: any) => {
            return a.base.set_name.localeCompare(b.base.set_name);
        });
    }, [details?.all_versions]);

    const activeGroup = useMemo<any>(() => {
        return versionGroups.find((g: any) => g.normal?.printing_id === activePrintingId || g.foil?.printing_id === activePrintingId);
    }, [versionGroups, activePrintingId]);

    const activeVersion = useMemo(() => {
        if (!activeGroup) return null;
        // Use activeFinish from URL searchParams
        const reqFinish = activeFinish || 'nonfoil';
        if (reqFinish === 'foil' && activeGroup.foil) return activeGroup.foil;
        if (reqFinish === 'etched' && activeGroup.etched) return activeGroup.etched;
        // Fallback to whichever is available in the group
        return activeGroup.normal || activeGroup.foil || activeGroup.etched || activeGroup.base;
    }, [activeGroup, activeFinish]);

    const isFoil = activeVersion ? (activeVersion.is_foil || activeVersion.finish === 'foil') : !!(details?.is_foil || details?.finish === 'foil');

    const ckUrl = useMemo(() => {
        if (!details) return '#';
        return getCardKingdomUrl(details.name, isFoil);
    }, [details?.name, isFoil]);

    if (error) {
        return (
            <div className="min-h-screen bg-neutral-50 dark:bg-[#050505] text-black dark:text-white flex flex-col items-center justify-center p-6 text-center">
                <AlertCircle size={64} className="text-red-500 mb-6" />
                <h1 className="text-3xl font-black mb-4">Error loading card</h1>
                <p className="text-text-low max-w-md mb-8">{error}</p>
                <Link to="/" className="px-8 py-3 bg-geeko-cyan rounded-full font-black text-black hover:scale-105 transition-all flex items-center gap-2 shadow-[0_0_20px_rgba(0, 209, 255, 0.3)]">
                    <ArrowLeft size={18} /> Back to Market
                </Link>
            </div>
        );
    }

    return (
        <div className="min-h-screen flex flex-col bg-neutral-50 dark:bg-[#050505] text-black dark:text-white font-sans selection:bg-geeko-cyan/30">
            {/* Ambient Background */}
            <div className="fixed inset-0 z-0 pointer-events-none">
                <div className="absolute top-[-20%] left-[-10%] w-[50%] h-[50%] bg-purple-600/5 rounded-full blur-[150px]" />
                <div className="absolute bottom-[-20%] right-[-10%] w-[50%] h-[50%] bg-geeko-cyan/5 rounded-full blur-[150px]" />
            </div>

            {/* Header */}
            <Header onCartOpen={() => setIsCartOpen(true)} cartCount={cartCount} />

            <main className="relative z-10 w-full max-w-[1600px] mx-auto p-4 lg:p-8 flex-1 flex flex-col items-center">
                {loading && !details ? (
                    <div className="flex flex-col items-center justify-center h-[60vh]">
                        {initialImage ? (
                            <img src={initialImage} alt="Loading..." className="w-[300px] rounded-xl object-contain opacity-50 blur-sm animate-pulse mb-4" />
                        ) : (
                            <Loader2 size={48} className="text-geeko-cyan animate-spin mb-4" />
                        )}
                        <p className="text-text-low font-bold tracking-widest uppercase text-xs">Loading Card Data...</p>
                    </div>
                ) : details ? (
                    <div data-testid="card-modal" className="w-full glass-panel rounded-[32px] border border-neutral-200 dark:border-white/10 shadow-[0_0_100px_rgba(0,0,0,0.05)] dark:shadow-[0_0_100px_rgba(0,209,255,0.15)] flex flex-col lg:flex-row overflow-hidden lg:min-h-[calc(100vh-220px)] relative">
                        {/* LEFT: IMAGE & VERSIONS LIST */}
                        <div className="w-full lg:w-[340px] bg-neutral-100 dark:bg-[#0c0c0c] flex flex-col lg:border-r border-b lg:border-b-0 border-neutral-200 dark:border-white/5 shrink-0 relative">
                            <div className="flex-1 min-h-[350px] lg:min-h-[250px] p-6 sm:p-8 md:p-10 relative bg-gradient-to-b from-white/[0.04] to-transparent overflow-hidden">
                                <div className={`absolute inset-6 sm:inset-8 md:inset-10 flex items-center justify-center ${isFoil ? 'holo-effect' : ''} group`}>
                                    <div className="absolute inset-0 bg-geeko-cyan/25 blur-[120px] rounded-full opacity-40 group-hover:opacity-60 transition-opacity duration-700 animate-pulse pointer-events-none" />
                                    {isFoil && (
                                        <div className="absolute inset-0 z-20 foil-shimmer opacity-30 mix-blend-overlay pointer-events-none rounded-[10%] scale-[0.95]" />
                                    )}
                                    <CardImage
                                        src={currentImage}
                                        alt={details.name}
                                        size="normal"
                                        objectFit="contain"
                                        placeholderSrc={initialImage}
                                        className="drop-shadow-[0_45px_100px_rgba(0,0,0,0.95)] z-10 hover:scale-[1.03] transition-all duration-700 !bg-transparent"
                                    />
                                </div>
                                
                                {/* Carousel Navigation */}
                                {!hasMultipleFaces && allImages.length > 1 && (
                                    <div className="absolute bottom-6 left-1/2 -translate-x-1/2 z-20 flex items-center gap-4 bg-black/60 px-4 py-2 rounded-full border border-white/10 shadow-xl backdrop-blur-md">
                                        <button
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                e.preventDefault();
                                                setCurrentImageIndex((prev) => prev === 0 ? allImages.length - 1 : prev - 1);
                                            }}
                                            className="text-white hover:text-geeko-cyan transition-colors"
                                        >
                                            <ChevronLeft size={18} />
                                        </button>

                                        <div className="flex gap-2">
                                            {allImages.map((_, idx) => (
                                                <button
                                                    key={idx}
                                                    onClick={(e) => {
                                                        e.stopPropagation();
                                                        setCurrentImageIndex(idx);
                                                    }}
                                                    className={`w-2 h-2 rounded-full transition-all ${idx === currentImageIndex ? 'bg-geeko-cyan shadow-[0_0_8px_rgba(0,209,255,0.8)] scale-125' : 'bg-white/30 hover:bg-white/60'}`}
                                                />
                                            ))}
                                        </div>

                                        <button
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                e.preventDefault();
                                                setCurrentImageIndex((prev) => (prev + 1) % allImages.length);
                                            }}
                                            className="text-white hover:text-geeko-cyan transition-colors"
                                        >
                                            <ChevronRight size={18} />
                                        </button>
                                    </div>
                                )}

                                {hasMultipleFaces && (
                                    <button
                                        onClick={() => setCurrentFaceIndex(prev => (prev + 1) % 2)}
                                        className="absolute bottom-6 right-6 p-4 bg-black/80 hover:bg-geeko-cyan text-white hover:text-black rounded-full border border-white/20 transition-all z-20 group shadow-2xl backdrop-blur-md"
                                    >
                                        <RotateCw size={22} className="group-hover:rotate-180 transition-transform duration-500" />
                                    </button>
                                )}
                            </div>

                            {/* MOXFIELD-STYLE VERSIONS LIST */}
                            {!details?.is_accessory && (
                                <div className="min-h-[150px] max-h-[250px] border-t border-neutral-200 dark:border-white/5 bg-white dark:bg-[#080808] flex flex-col shrink-0 overflow-hidden rounded-bl-[32px]">
                                    <div className="px-6 py-4 flex items-center justify-between border-b border-white/5">
                                        <h3 className="text-xs font-black uppercase tracking-widest text-text-low">Edition / Printings</h3>
                                        <span className="text-[10px] text-text-low font-bold">{details.all_versions?.length || 0} Versions</span>
                                    </div>
                                    <div className="flex-1 overflow-y-auto overflow-x-hidden custom-scrollbar">
                                    {versionGroups.length > 0 ? (
                                        versionGroups.map((group: any) => {
                                            const isGroupActive = activePrintingId === group.base.printing_id;
                                            const rowActiveVersion = (activeFinish === 'foil' && group.foil) ? group.foil : (group.normal || group.base);

                                            return (
                                                <div
                                                    key={`${group.base.set_code}-${group.base.collector_number}`}
                                                    data-testid="edition-link"
                                                    role="button"
                                                    tabIndex={0}
                                                    onClick={() => {
                                                        const isCurrentlyFoil = !!(details?.is_foil || details?.finish === 'foil');
                                                        const targetPrintingId = isCurrentlyFoil
                                                            ? (group.foil?.printing_id || group.normal?.printing_id)
                                                            : (group.normal?.printing_id || group.foil?.printing_id);
