                {!isRealOrder && (
                    <div className="p-4 bg-amber-500/5 border border-amber-500/20 rounded-xl mb-8 flex items-start gap-3 text-left">
                        <AlertCircle className="text-amber-500 shrink-0 mt-0.5" size={16} />
