              </div>

                {/* Desktop Utilities */}
              <div className="hidden lg:flex items-center gap-4">
                <div className="flex bg-neutral-100 dark:bg-neutral-900/50 p-1 rounded-full border border-neutral-200 dark:border-neutral-800">
