export const createOrder = async (orderData: {
  userId: string | null;
  items: { product_id?: string | null; accessory_id?: string | null; quantity: number; price: number; finish?: string; is_on_demand?: boolean }[];
  shippingAddress: any;
  totalAmount: number;
  guestInfo?: { email: string; phone: string };
  cartId?: string;
  customerName?: string;
}): Promise<any> => {
  try {
    const { data, error } = await supabase.rpc('create_order_atomic', {
      p_user_id: orderData.userId,
      p_items: orderData.items,
      p_shipping_address: orderData.shippingAddress,
      p_total_amount: orderData.totalAmount,
      p_guest_info: orderData.guestInfo || null,
      p_cart_id: orderData.cartId || null
    });

    if (error) throw error;

    // Clear guest cart if successful
    if (!orderData.userId) {
      localStorage.removeItem('guest_cart');
      window.dispatchEvent(new Event('cart-updated'));
    }

    // Fire & Forget: Sync order to Odoo
    if (data) {
      let email = orderData.guestInfo?.email || 'guest@geekorium.com';
      if (orderData.userId && !orderData.guestInfo?.email) {
        const { data: userData } = await supabase.auth.getUser();
        if (userData.user?.email) email = userData.user.email;
      }
      
      supabase.functions.invoke('odoo-sync', {
        body: {
          action: 'sync_order',
          order_data: {
            id: data,
            items: orderData.items,
            customer_email: email,
            customer_name: orderData.customerName || 'Web Customer'
          }
        }
      }).catch((err: any) => console.error("Failed to sync order to Odoo:", err));
    }

    return data;
  } catch (error) {
    console.error('Order creation failed:', error);
    throw error;
  }
};

